INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Regex from Plain English with Live Match Preview', 'Regex desde lenguaje natural con vista previa de coincidencias', 'Describe what you want to match in plain English and the tool drafts a regex, then highlights every hit on a sample string you paste below. Each suggestion shows a confidence note and a one-line explanation of what the pattern does. A tight single-screen build perfect for a short sprint, useful the moment you write it.', 'Describe en lenguaje natural lo que querés capturar y la herramienta arma un regex, luego resalta cada coincidencia sobre un texto de ejemplo que pegás debajo. Cada sugerencia muestra una nota de confianza y una explicación de una línea de lo que hace el patrón. Una construcción de una sola pantalla ideal para un sprint corto y útil al instante.', 'ai-ml', '1-3h', 1, 3, 'beginner', '["llm-apps","nlp"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Webcam Posture Coach that Nudges You When You Slouch', 'Coach de postura por webcam que te avisa cuando te encorvás', 'A tiny background tool that watches your webcam, estimates your head and shoulder line, and pops a gentle nudge when you slouch for too long. It calibrates to your good posture in ten seconds and shows a live skeleton overlay so you trust what it sees. One sharp feature you can demo in minutes by leaning forward on camera.', 'Una herramienta liviana en segundo plano que observa tu webcam, estima la línea de cabeza y hombros y lanza un aviso suave cuando te encorvás demasiado tiempo. Se calibra a tu postura correcta en diez segundos y muestra un esqueleto en vivo para que confíes en lo que detecta. Una sola función contundente que demostrás en minutos inclinándote ante la cámara.', 'ai-ml', '1-3h', 1, 3, 'beginner', '["computer-vision"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Cold-Email Tone Checker that Scores Pushiness', 'Verificador de tono de emails fríos que puntúa lo invasivo', 'Paste a sales or outreach email and the tool scores it on pushiness, vagueness, and length, then rewrites the worst sentence into something a stranger would actually answer. It highlights the phrases that trigger each flag so you learn, not just copy. A focused single-input build that lands a clear before-and-after in any demo.', 'Pegá un email de ventas o contacto y la herramienta lo puntúa por lo invasivo, lo vago y su largo, luego reescribe la peor frase en algo que un desconocido sí respondería. Resalta las expresiones que disparan cada alerta para que aprendas, no solo copies. Una construcción enfocada de una sola entrada que logra un claro antes y después en cualquier demo.', 'ai-ml', '1-3h', 1, 3, 'beginner', '["llm-apps","nlp"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Fridge-Photo to Three Recipes You Can Cook Tonight', 'Foto de la heladera a tres recetas para cocinar esta noche', 'Snap a photo of your open fridge and the tool identifies the ingredients it can see, then proposes three realistic recipes ranked by how few extra items you''d need to buy. It flags anything close to spoiling so you cook that first. A crowd-pleasing single-shot demo that turns a messy shelf into dinner in seconds.', 'Sacá una foto de tu heladera abierta y la herramienta identifica los ingredientes que ve, luego propone tres recetas realistas ordenadas según cuántas cosas extra tendrías que comprar. Marca lo que está por vencerse para que lo cocines primero. Una demo de una sola toma que conquista al público y convierte un estante caótico en cena en segundos.', 'ai-ml', '1-3h', 1, 3, 'beginner', '["computer-vision","generative"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Meeting Recording to a One-Screen Decision Log', 'Grabación de reunión a una bitácora de decisiones de una pantalla', 'Drop in a meeting audio file and instead of a wall of transcript you get a clean board of just the decisions made, who owns each one, and the open questions left hanging. It links every item back to the timestamp where it was said so nobody argues. A sharp half-hour-of-audio demo that produces an artifact a team would actually keep.', 'Subí un audio de reunión y en vez de un muro de transcripción obtenés un tablero limpio con solo las decisiones tomadas, quién es responsable de cada una y las preguntas abiertas que quedaron. Enlaza cada ítem al minuto exacto donde se dijo para que nadie discuta. Una demo nítida con audio de media hora que produce un artefacto que un equipo realmente conservaría.', 'ai-ml', '3-6h', 3, 6, 'intermediate', '["audio","nlp","llm-apps"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Whiteboard Photo to Editable Flowchart in One Tap', 'Foto de pizarra a diagrama de flujo editable en un toque', 'Photograph a hand-drawn whiteboard and the tool reconstructs the boxes, arrows, and labels into a clean, editable flowchart you can drag around. It guesses the diagram type and snaps wobbly shapes straight while preserving your actual text. A satisfying single-photo demo that erases the worst part of meetings: redrawing the board afterward.', 'Fotografiá una pizarra dibujada a mano y la herramienta reconstruye las cajas, flechas y etiquetas en un diagrama de flujo limpio y editable que podés arrastrar. Adivina el tipo de diagrama y endereza las formas torcidas conservando tu texto real. Una demo satisfactoria de una sola foto que elimina lo peor de las reuniones: volver a dibujar el tablero después.', 'ai-ml', '3-6h', 3, 6, 'intermediate', '["computer-vision","generative"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Accent-Neutralizing Live Captions for Group Calls', 'Subtítulos en vivo que neutralizan acentos en llamadas grupales', 'Real-time captions tuned for accented speech: it adapts to each speaker''s voice over the first minute and surfaces the words it''s least sure about so listeners can ask instead of guess. Speakers get a private confidence meter showing when they''re being understood. A live two-person demo where captions visibly sharpen as the system learns the voice.', 'Subtítulos en tiempo real pensados para habla con acento: se adapta a la voz de cada persona en el primer minuto y resalta las palabras de las que menos seguro está para que el oyente pregunte en vez de adivinar. Quien habla recibe un medidor privado de confianza que muestra cuándo se le entiende. Una demo en vivo entre dos personas donde los subtítulos se afinan a ojos vistas.', 'ai-ml', '3-6h', 3, 6, 'intermediate', '["audio","nlp"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Plant-Leaf Photo Triage that Names the Disease', 'Triaje por foto de hoja que nombra la enfermedad de la planta', 'Point your camera at a sick leaf and the tool names the most likely disease or deficiency, shows two reference photos side by side, and gives a short do-this-next for a home grower. It states its confidence honestly and says when it can''t tell. A clean single-shot demo where a judge holds up a plant and gets an answer they can act on.', 'Apuntá la cámara a una hoja enferma y la herramienta nombra la enfermedad o deficiencia más probable, muestra dos fotos de referencia lado a lado y da un breve qué-hacer-ahora para alguien que cultiva en casa. Declara su confianza con honestidad y avisa cuando no puede decidir. Una demo nítida de una sola toma donde un jurado levanta una planta y obtiene una respuesta accionable.', 'ai-ml', '3-6h', 3, 6, 'intermediate', '["computer-vision","prediction"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Job Posting to Tailored Resume Bullet Suggestions', 'Aviso de empleo a sugerencias de viñetas de CV a medida', 'Paste a job posting and your current resume; the tool maps which of your real experiences match the role and rewrites those bullets to mirror the posting''s language without inventing anything. It flags genuine gaps so you know what to address in the cover letter. A focused two-input demo that produces a visibly stronger, honest resume in one pass.', 'Pegá un aviso de empleo y tu CV actual; la herramienta mapea cuáles de tus experiencias reales encajan con el puesto y reescribe esas viñetas para reflejar el lenguaje del aviso sin inventar nada. Marca los vacíos genuinos para que sepas qué abordar en la carta de presentación. Una demo enfocada de dos entradas que produce un CV honesto y notablemente más fuerte en una sola pasada.', 'ai-ml', '3-6h', 3, 6, 'beginner', '["llm-apps","nlp"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Hum-to-Search that Finds the Song Stuck in Your Head', 'Buscador por tarareo que encuentra la canción que tenés en la cabeza', 'Hum or whistle a melody for ten seconds and the tool extracts the pitch contour, matches it against a library, and returns its best guesses ranked with a similarity score. It shows the contour it heard versus the match so the result feels earned, not magic. A delightful live demo where someone hums off-key and still gets the right track.', 'Tarareá o silbá una melodía por diez segundos y la herramienta extrae el contorno de tono, lo compara contra una biblioteca y devuelve sus mejores apuestas ordenadas con un puntaje de similitud. Muestra el contorno que escuchó frente al de la coincidencia para que el resultado se sienta merecido y no magia. Una demo en vivo encantadora donde alguien tararea desafinado y aun así obtiene la canción correcta.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["audio","recommendation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Sign-Language Finger-Spelling Tutor with Webcam Drills', 'Tutor de deletreo en lengua de señas con ejercicios por webcam', 'A webcam tutor for sign-language finger-spelling: it reads your hand shape in real time, scores it against the target letter, and runs drills that speed up as you improve. Missed letters resurface more often so practice adapts to your weak spots. The demo has you spell a word on camera and watch the accuracy meter react instantly.', 'Un tutor por webcam para el deletreo en lengua de señas: lee la forma de tu mano en tiempo real, la puntúa contra la letra objetivo y corre ejercicios que se aceleran a medida que mejorás. Las letras falladas reaparecen más seguido para que la práctica se adapte a tus puntos débiles. La demo te hace deletrear una palabra ante la cámara y ver el medidor de precisión reaccionar al instante.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["computer-vision","prediction"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Receipt-Photo Expense Splitter that Reads Who Ate What', 'Divisor de gastos por foto de ticket que lee quién comió qué', 'Snap a restaurant receipt and the tool extracts each line item, then lets the table tap their dishes so it splits the bill with tax and tip handled fairly per person. It handles shared appetizers by letting people co-claim an item. A fast, relatable demo where a messy receipt becomes an exact who-owes-what in under a minute.', 'Sacá una foto del ticket del restaurante y la herramienta extrae cada ítem, luego deja que la mesa toque sus platos para dividir la cuenta con impuestos y propina repartidos justo por persona. Maneja las entradas compartidas dejando que varios reclamen un mismo ítem. Una demo rápida y cercana donde un ticket desprolijo se vuelve un quién-debe-cuánto exacto en menos de un minuto.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["computer-vision","nlp"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Codebase Onboarding Agent that Traces a Feature End to End', 'Agente de onboarding que rastrea una función de punta a punta', 'Point the agent at a repo and ask how a feature works; it walks the code, follows imports and calls, and returns a narrated map from entry point to database with the key files linked. It marks the spots it''s unsure about instead of bluffing. A strong demo where a stranger''s repo becomes legible in one question, scoped right for a focused day.', 'Apuntá el agente a un repositorio y preguntá cómo funciona una función; recorre el código, sigue imports y llamadas y devuelve un mapa narrado desde el punto de entrada hasta la base de datos con los archivos clave enlazados. Marca los puntos donde no está seguro en vez de improvisar. Una demo fuerte donde el repo de un desconocido se vuelve legible con una sola pregunta.', 'ai-ml', '6-12h', 6, 12, 'advanced', '["agents","llm-apps"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Spoken-Story Coach that Flags Filler Words Live', 'Coach de relato hablado que marca muletillas en vivo', 'Practice a talk out loud and the tool listens, counting filler words, flagging long rambles, and charting your pace so you see where you lose the room. After each take it picks the single habit to fix next so feedback stays actionable. A lively demo where someone delivers a pitch and gets a one-glance scorecard the moment they stop.', 'Practicá una charla en voz alta y la herramienta escucha, cuenta muletillas, marca divagues largos y grafica tu ritmo para que veas dónde perdés a la audiencia. Tras cada toma elige el único hábito a corregir después para que la devolución sea accionable. Una demo dinámica donde alguien da un pitch y obtiene una tarjeta de un vistazo en cuanto termina.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["audio","nlp"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Style-Match Outfit Recommender from Your Own Closet', 'Recomendador de outfits que combina desde tu propio placard', 'Photograph your clothes once and the tool catalogs them by color, type, and formality, then suggests outfits for a given occasion using only what you own. It learns from the looks you save or reject so suggestions get more you over time. A relatable demo where a pile of clothing photos turns into three ready outfits for tonight.', 'Fotografiá tu ropa una vez y la herramienta la cataloga por color, tipo y formalidad, luego sugiere outfits para una ocasión usando solo lo que tenés. Aprende de los looks que guardás o rechazás para que las sugerencias se vuelvan más tuyas con el tiempo. Una demo cercana donde un montón de fotos de ropa se transforma en tres outfits listos para esta noche.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["computer-vision","recommendation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Lecture Video to Spaced-Repetition Flashcards Automatically', 'Video de clase a tarjetas de repaso espaciado en automático', 'Feed in a recorded lecture and the tool transcribes it, finds the testable claims, and generates question-and-answer flashcards timestamped to where each was explained. It schedules reviews so you revisit weak cards before you forget. A demo that turns an hour of video into a study deck a student would open the next morning.', 'Cargá una clase grabada y la herramienta la transcribe, encuentra las afirmaciones evaluables y genera tarjetas de pregunta y respuesta con marca de tiempo del momento en que se explicó cada una. Programa repasos para que vuelvas a las tarjetas débiles antes de olvidarlas. Una demo que convierte una hora de video en un mazo de estudio que un estudiante abriría a la mañana siguiente.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["nlp","audio","llm-apps"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Crowd-Density Estimator for Safer Event Entrances', 'Estimador de densidad de multitud para entradas de eventos seguras', 'Point a camera at a queue or entrance and the tool estimates crowd density per zone, draws a heat overlay, and warns when a spot is trending toward a crush. It counts flow over time so organizers can open a second gate before it''s urgent. A vivid demo on real crowd footage where danger zones light up before anything goes wrong.', 'Apuntá una cámara a una fila o entrada y la herramienta estima la densidad de multitud por zona, dibuja una capa de calor y avisa cuando un punto tiende a una aglomeración peligrosa. Cuenta el flujo en el tiempo para que los organizadores abran una segunda puerta antes de que sea urgente. Una demo vívida sobre filmaciones reales donde las zonas de riesgo se encienden antes de que algo salga mal.', 'ai-ml', '6-12h', 6, 12, 'advanced', '["computer-vision","prediction"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Voice Journal that Charts Your Mood Across Weeks', 'Diario de voz que grafica tu ánimo a lo largo de las semanas', 'Speak a daily entry and the tool transcribes it, reads tone and word choice, and plots your mood trend without you ever rating a number. It surfaces recurring themes gently and lets you reread any spike in context. A quietly powerful demo where a week of voice notes becomes a mood line you didn''t know you needed to see.', 'Hablá una entrada diaria y la herramienta la transcribe, lee el tono y la elección de palabras, y grafica tu tendencia de ánimo sin que califiques un número jamás. Resalta con delicadeza los temas recurrentes y te deja releer cualquier pico en su contexto. Una demo discretamente poderosa donde una semana de notas de voz se vuelve una línea de ánimo que no sabías que necesitabas ver.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["audio","nlp","prediction"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Research-Paper Reading Agent that Builds a Lit Review', 'Agente lector de papers que arma una revisión de literatura', 'Give the agent a topic and a few seed papers; it pulls related work, reads abstracts and methods, and assembles a structured literature review grouping papers by approach with the disagreements between them noted. Every claim links to its source so a reviewer can check. A meaty demo where a blank topic becomes a navigable map of a field.', 'Dale al agente un tema y unos papers semilla; trae trabajos relacionados, lee resúmenes y métodos y ensambla una revisión de literatura estructurada que agrupa papers por enfoque y anota los desacuerdos entre ellos. Cada afirmación enlaza a su fuente para que un revisor pueda verificar. Una demo sustanciosa donde un tema en blanco se vuelve un mapa navegable de un campo.', 'ai-ml', '12-24h', 12, 24, 'advanced', '["agents","nlp","llm-apps"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Shelf-Photo Inventory Counter for Small Shops', 'Contador de inventario por foto de estante para comercios chicos', 'A shopkeeper photographs a shelf and the tool counts each product, spots gaps where stock ran out, and flags items running low against a simple threshold. Over days it predicts which products will sell out next so reordering beats the rush. A practical demo where one photo of a messy shelf becomes a clean restock list.', 'Un comerciante fotografía un estante y la herramienta cuenta cada producto, detecta huecos donde se agotó el stock y marca los ítems que escasean contra un umbral simple. Con los días predice qué productos se agotarán próximo para que el repedido le gane al apuro. Una demo práctica donde una foto de un estante caótico se vuelve una lista de reposición limpia.', 'ai-ml', '12-24h', 12, 24, 'advanced', '["computer-vision","prediction"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Personalized Podcast that Reads Your Day''s Updates Aloud', 'Podcast personalizado que te narra las novedades de tu día', 'Pick the feeds and topics you care about and the tool gathers the day''s items, writes a tight conversational script, and renders it as a short audio briefing in a natural voice you choose. It skips repeats and adjusts length to your commute. A satisfying demo where scattered updates become a five-minute show made just for you.', 'Elegí las fuentes y temas que te importan y la herramienta junta lo del día, escribe un guion conversacional ajustado y lo renderiza como un briefing de audio corto en una voz natural que elegís. Salta repetidos y ajusta el largo a tu viaje. Una demo satisfactoria donde novedades dispersas se vuelven un programa de cinco minutos hecho solo para vos.', 'ai-ml', '12-24h', 12, 24, 'intermediate', '["audio","generative","recommendation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Spreadsheet-to-Chart Agent You Talk to in Plain Language', 'Agente de planilla a gráfico al que le hablás en lenguaje natural', 'Upload a messy spreadsheet and ask questions like a colleague would; the agent cleans the data, picks a sensible chart, and explains what it shows, then lets you refine by saying what''s wrong. It shows the steps it took so the analysis is auditable, not a black box. A strong demo where raw rows become a clear answer through conversation.', 'Subí una planilla desprolija y preguntá como le preguntarías a un colega; el agente limpia los datos, elige un gráfico sensato y explica qué muestra, luego te deja refinar diciendo qué está mal. Muestra los pasos que dio para que el análisis sea auditable y no una caja negra. Una demo fuerte donde filas crudas se vuelven una respuesta clara mediante conversación.', 'ai-ml', '12-24h', 12, 24, 'advanced', '["agents","llm-apps","prediction"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Real-Time Translator Earpiece App for Two-Way Talks', 'App de auricular traductor en tiempo real para charlas bidireccionales', 'Two people speaking different languages each hear the other in their own tongue with minimal lag; the app handles turn-taking, shows a running transcript, and lets a tap replay the last line when noise wins. It marks low-confidence stretches so you can confirm a critical word. A memorable demo where two strangers hold a real conversation across a language gap.', 'Dos personas que hablan idiomas distintos escuchan cada una a la otra en su propia lengua con mínimo retraso; la app maneja los turnos, muestra una transcripción corrida y permite con un toque repetir la última frase cuando gana el ruido. Marca los tramos de baja confianza para confirmar una palabra clave. Una demo memorable donde dos desconocidos sostienen una conversación real cruzando la barrera del idioma.', 'ai-ml', '12-24h', 12, 24, 'advanced', '["audio","nlp"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Form-Filling Agent that Reads Your Docs and Asks Only Gaps', 'Agente que completa formularios leyendo tus documentos y solo pregunta lo que falta', 'Hand the agent a long application form and a folder of your documents; it fills every field it can verify from your files and asks you only for what''s genuinely missing, in plain questions. It shows the source for each filled value so you can trust and correct. A relieving demo where a dreaded form is two-thirds done before you type a word.', 'Dale al agente un formulario largo y una carpeta de tus documentos; completa cada campo que puede verificar desde tus archivos y solo te pregunta lo que falta de verdad, en preguntas simples. Muestra la fuente de cada valor cargado para que confíes y corrijas. Una demo aliviadora donde un formulario temido queda dos tercios hecho antes de que escribas una palabra.', 'ai-ml', '12-24h', 12, 24, 'advanced', '["agents","nlp","llm-apps"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Drawing-to-Game-Sprite Generator that Keeps Your Style', 'Generador de sprites de juego desde tu dibujo que conserva tu estilo', 'Sketch one character and the tool generates a matching sprite set: walk frames, idle, and a few poses, all consistent with your drawing''s style and palette. You can nudge any frame and regenerate just that one. A delightful demo for game jams where a single doodle becomes an animatable character in minutes instead of an afternoon.', 'Dibujá un personaje y la herramienta genera un set de sprites a juego: cuadros de caminata, reposo y algunas poses, todos consistentes con el estilo y la paleta de tu dibujo. Podés retocar cualquier cuadro y regenerar solo ese. Una demo encantadora para game jams donde un único garabato se vuelve un personaje animable en minutos en lugar de una tarde.', 'ai-ml', '12-24h', 12, 24, 'intermediate', '["generative","computer-vision"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Symptom-Aware Triage Companion that Knows When to Escalate', 'Compañero de triaje sintomático que sabe cuándo escalar', 'A careful conversational triage tool that asks structured follow-up questions, summarizes likely non-emergency causes in plain language, and clearly flags red-flag symptoms that mean see-a-doctor-now. It never diagnoses; it routes and explains. A weekend-scale build with safety guardrails front and center, demoable by walking a judge through one realistic case.', 'Una herramienta de triaje conversacional cuidadosa que hace preguntas de seguimiento estructuradas, resume en lenguaje simple las causas probables no urgentes y marca con claridad los síntomas de alarma que significan ver-a-un-médico-ya. Nunca diagnostica; orienta y explica. Una construcción de fin de semana con barreras de seguridad al frente, demostrable recorriendo con un jurado un caso realista.', 'ai-ml', '24-48h', 24, 48, 'advanced', '["llm-apps","nlp","prediction"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Multi-Agent Trip Planner that Negotiates a Group''s Constraints', 'Planificador de viajes multiagente que negocia las restricciones del grupo', 'Each traveler states their budget, dates, and must-haves; a set of agents proposes itineraries, debates the tradeoffs, and converges on a plan that honors the hard constraints while flagging the compromises. It shows the negotiation so the group sees why it landed there. A rich weekend demo where five conflicting wishlists become one trip everyone can accept.', 'Cada viajero declara su presupuesto, fechas e imprescindibles; un conjunto de agentes propone itinerarios, debate los tradeoffs y converge en un plan que respeta las restricciones duras mientras marca las concesiones. Muestra la negociación para que el grupo vea por qué llegó ahí. Una demo rica de fin de semana donde cinco listas de deseos en conflicto se vuelven un viaje que todos pueden aceptar.', 'ai-ml', '24-48h', 24, 48, 'advanced', '["agents","recommendation","llm-apps"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Wildlife Camera-Trap Sorter that IDs and Counts Species', 'Clasificador de cámaras trampa que identifica y cuenta especies', 'Researchers dump thousands of camera-trap images and the tool sorts them by species, discards the empty triggers, and builds a timeline of when each animal appeared. It surfaces rare sightings for a human to confirm and exports a tidy dataset. A weekend-scale build with real conservation value, demoable on a folder where noise becomes a species log.', 'Investigadores vuelcan miles de imágenes de cámaras trampa y la herramienta las ordena por especie, descarta los disparos vacíos y arma una línea de tiempo de cuándo apareció cada animal. Resalta los avistajes raros para que un humano confirme y exporta un dataset prolijo. Una construcción de fin de semana con valor real de conservación, demostrable sobre una carpeta donde el ruido se vuelve un registro de especies.', 'ai-ml', '24-48h', 24, 48, 'advanced', '["computer-vision","prediction"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Living NPC Townsfolk with Memory of Your Past Choices', 'Aldeanos NPC vivos que recuerdan tus decisiones pasadas', 'A small game world where villagers hold real conversations, remember what you did to them earlier, and let that color how they treat you next time. They gossip among themselves so a rumor spreads if you wrong someone. An ambitious weekend demo where a judge plays two scenes and watches the town visibly react to who they became.', 'Un pequeño mundo de juego donde los aldeanos sostienen conversaciones reales, recuerdan lo que les hiciste antes y dejan que eso tiña cómo te tratan después. Chusmean entre ellos, así que un rumor se esparce si maltratás a alguien. Una demo ambiciosa de fin de semana donde un jurado juega dos escenas y ve al pueblo reaccionar a quién se volvió.', 'ai-ml', '24-48h', 24, 48, 'advanced', '["agents","generative","nlp"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Bird-Song Identifier that Maps What''s Singing Around You', 'Identificador de cantos de aves que mapea qué canta a tu alrededor', 'Record ambient outdoor audio and the tool separates overlapping bird calls, names the species it hears, and builds a running list of who''s around as you walk. It shows the spectrogram with each detection highlighted so birders trust it. A charming demo where stepping outside with a phone turns the dawn chorus into a labeled field log.', 'Grabá audio ambiente al aire libre y la herramienta separa los cantos de aves superpuestos, nombra las especies que escucha y arma una lista corrida de quién anda cerca mientras caminás. Muestra el espectrograma con cada detección resaltada para que los observadores confíen. Una demo encantadora donde salir con el teléfono convierte el coro del amanecer en un registro de campo etiquetado.', 'ai-ml', '12-24h', 12, 24, 'advanced', '["audio","prediction"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Plain-English Translator for Any Smart Contract You Paste', 'Traductor a lenguaje claro para cualquier contrato inteligente', 'Paste a contract address or its source and get back a plain-language summary of what it can do to your funds: who can mint, who can pause, whether the owner can drain it, and any hidden fees. Each claim links to the exact line that proves it. A sharp single-screen build that turns scary bytecode into a readable risk briefing for a short sprint.', 'Pegá una dirección de contrato o su código y obtené un resumen en lenguaje claro de lo que puede hacer con tus fondos: quién puede emitir, quién puede pausar, si el dueño puede vaciarlo y qué comisiones ocultas hay. Cada afirmación enlaza a la línea exacta que la respalda. Una construcción de una sola pantalla que convierte bytecode aterrador en un informe de riesgo legible para un sprint corto.', 'crypto-web3', '3-6h', 3, 6, 'intermediate', '["smart-contracts","on-chain-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Wallet Drainer Detector that Simulates a Transaction First', 'Detector de drenadores de wallet que simula la transacción primero', 'Before you sign, paste the pending transaction and the tool simulates it against a forked chain, showing exactly which tokens leave your wallet and which approvals you are granting. It flags infinite approvals and contracts that move assets to an unknown address. The demo signs a malicious-looking swap and watches the red warning fire before any money moves.', 'Antes de firmar, pegá la transacción pendiente y la herramienta la simula contra una cadena bifurcada, mostrando exactamente qué tokens salen de tu wallet y qué aprobaciones estás otorgando. Marca aprobaciones infinitas y contratos que mueven activos a una dirección desconocida. La demo firma un swap de apariencia maliciosa y muestra la alerta roja antes de que se mueva el dinero.', 'crypto-web3', '6-12h', 6, 12, 'advanced', '["wallets","smart-contracts","on-chain-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Split-the-Bill Wallet that Settles a Dinner in Stablecoins', 'Wallet para dividir la cuenta que salda una cena en stablecoins', 'Snap a photo of a restaurant bill, tag who had what, and the app generates one payment request each friend settles in stablecoins by tapping a link, no app install. It nets out who owes whom so the table makes the fewest transfers. A friendly, demoable consumer flow that hides the chain behind a normal split-the-bill moment.', 'Sacá una foto de la cuenta del restaurante, etiquetá quién pidió qué y la app genera una solicitud de pago que cada amigo salda en stablecoins tocando un enlace, sin instalar nada. Compensa quién le debe a quién para que la mesa haga la menor cantidad de transferencias. Un flujo de consumo amigable y demostrable que esconde la cadena detrás de un momento normal de dividir la cuenta.', 'crypto-web3', '6-12h', 6, 12, 'intermediate', '["payments","wallets"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('One-Tap Recurring Crypto Allowance for Kids and Teams', 'Mesada cripto recurrente de un toque para chicos y equipos', 'Set up a streaming allowance that drips a fixed stablecoin amount to a recipient every week, with a hard monthly cap and a one-tap pause. Parents or team leads see a simple timeline of what flowed and can claw back unused funds. A tight build whose hook is making recurring on-chain payments feel as calm as a standing order.', 'Configurá una mesada en streaming que envíe un monto fijo en stablecoins a un destinatario cada semana, con un tope mensual firme y pausa de un toque. Padres o líderes de equipo ven una línea de tiempo simple de lo que se envió y pueden recuperar los fondos no usados. Una construcción ajustada cuyo gancho es hacer que los pagos recurrentes on-chain se sientan tan tranquilos como una orden permanente.', 'crypto-web3', '6-12h', 6, 12, 'intermediate', '["payments","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('ENS-Style Vanity Name That Doubles as a Tip Jar Page', 'Nombre vanidoso estilo ENS que también es una página de propinas', 'Claim a human-readable name that resolves to your wallet and instantly get a shareable tip page where anyone can send you a coffee in one tap. The page shows recent tippers and a live total without exposing your full address. A small, polished build perfect for a half-day sprint that makes getting paid feel personal.', 'Reclamá un nombre legible que resuelva a tu wallet y obtené al instante una página de propinas compartible donde cualquiera puede invitarte un café de un toque. La página muestra los últimos donantes y un total en vivo sin exponer tu dirección completa. Una construcción pequeña y pulida, perfecta para un sprint de medio día, que hace que cobrar se sienta personal.', 'crypto-web3', '3-6h', 3, 6, 'beginner', '["identity","payments","wallets"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Proof-of-Attendance Badge You Mint by Scanning a Live QR', 'Insignia de asistencia que acuñás escaneando un QR en vivo', 'Event hosts display a rotating QR that only works inside the venue and time window; attendees scan it to mint a free, non-transferable badge to their wallet. Later they can show a wall of badges proving where they actually showed up. A clean, demoable flow whose anti-fraud rotating code is the whole trick for a short build.', 'Los organizadores muestran un QR rotativo que solo funciona dentro del lugar y la ventana horaria; los asistentes lo escanean para acuñar una insignia gratuita e intransferible en su wallet. Después pueden mostrar un muro de insignias que prueba dónde estuvieron realmente. Un flujo limpio y demostrable cuyo código rotativo antifraude es todo el truco para una construcción corta.', 'crypto-web3', '6-12h', 6, 12, 'intermediate', '["nfts","identity"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Gas Fee Time-Machine that Tells You When to Hit Send', 'Máquina del tiempo de gas que te dice cuándo enviar', 'Type the transaction you want to make and the tool charts predicted gas over the next hours, highlighting the cheapest window and what you would save by waiting. It can ping you when fees drop below your target. A focused single-feature build that turns a frustrating guessing game into one clear chart for a short sprint.', 'Escribí la transacción que querés hacer y la herramienta grafica el gas previsto en las próximas horas, resaltando la ventana más barata y cuánto ahorrarías esperando. Puede avisarte cuando las comisiones bajen de tu objetivo. Una construcción enfocada en una sola función que convierte un frustrante juego de adivinanzas en un gráfico claro para un sprint corto.', 'crypto-web3', '3-6h', 3, 6, 'intermediate', '["on-chain-data","wallets"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Read-Only Whale Tracker that Narrates Big Wallet Moves', 'Rastreador de ballenas de solo lectura que narra movimientos grandes', 'Follow a handful of large wallets and get a plain-language feed: this address just swapped a million into a new token, that one started withdrawing from an exchange. Each event links to the on-chain proof and a tiny chart. A demoable read-only dashboard whose hook is turning raw transfers into a gossip column you can actually follow.', 'Seguí un puñado de wallets grandes y obtené un feed en lenguaje claro: esta dirección acaba de cambiar un millón a un token nuevo, aquella empezó a retirar de un exchange. Cada evento enlaza a la prueba on-chain y a un mini gráfico. Un panel de solo lectura y demostrable cuyo gancho es convertir transferencias crudas en una columna de chismes que podés seguir de verdad.', 'crypto-web3', '6-12h', 6, 12, 'intermediate', '["on-chain-data","defi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Token Approval Spring-Cleaner that Revokes Stale Permissions', 'Limpiador de aprobaciones que revoca permisos viejos de tokens', 'Connect a wallet and see every contract you have ever approved to spend your tokens, ranked by how dangerous and how stale each one is. Tick the risky ones and revoke them all in a batch. A sharp safety utility with an obvious demo: a long scary list that you clean up in two clicks within a short sprint.', 'Conectá una wallet y mirá cada contrato al que alguna vez le diste permiso para gastar tus tokens, ordenados por peligrosidad y antigüedad. Tildá los riesgosos y revocalos todos en un lote. Una utilidad de seguridad clara con una demo obvia: una lista larga y aterradora que limpiás en dos clics dentro de un sprint corto.', 'crypto-web3', '3-6h', 3, 6, 'intermediate', '["wallets","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Sybil-Resistant Poll Where One Human Equals One Vote', 'Encuesta resistente a sybil donde un humano vale un voto', 'Create a quick poll that anyone can answer, but each vote requires a lightweight proof of unique personhood so a single user cannot stuff the ballot with fresh wallets. Results update live with a tally of verified voters. A demoable build whose hook is fair on-chain voting without collecting anyone''s real identity.', 'Creá una encuesta rápida que cualquiera puede responder, pero cada voto exige una prueba liviana de unicidad personal para que un mismo usuario no pueda llenar la urna con wallets nuevas. Los resultados se actualizan en vivo con un recuento de votantes verificados. Una construcción demostrable cuyo gancho es la votación on-chain justa sin recolectar la identidad real de nadie.', 'crypto-web3', '6-12h', 6, 12, 'advanced', '["identity","dao"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('DAO Proposal Digest that Summarizes the Week in One Card', 'Resumen de propuestas DAO que condensa la semana en una tarjeta', 'Point it at a DAO and get a weekly card: every open proposal in one line, the deadline, current vote split, and a plain-language take on what each one actually changes. Members can vote straight from the card. A focused build that fixes governance fatigue by turning a noisy forum into one scannable digest for a short sprint.', 'Apuntalo a una DAO y obtené una tarjeta semanal: cada propuesta abierta en una línea, su fecha límite, el reparto actual de votos y una explicación en lenguaje claro de qué cambia cada una. Los miembros pueden votar directo desde la tarjeta. Una construcción enfocada que combate la fatiga de gobernanza convirtiendo un foro ruidoso en un resumen escaneable para un sprint corto.', 'crypto-web3', '6-12h', 6, 12, 'intermediate', '["dao","on-chain-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Pooled Savings Circle that Runs an Honest Rotating Fund', 'Fondo de ahorro colectivo que corre una rueda honesta on-chain', 'A digital version of a rotating savings circle: a group deposits a fixed amount each round and a smart contract pays out the whole pot to one member in turn, with the order set transparently and no one able to vanish with the money. The demo runs a fast-forward circle so judges watch every payout settle. A meaningful build for a full day.', 'Una versión digital de una rueda de ahorro rotativa: un grupo deposita un monto fijo cada ronda y un contrato inteligente paga todo el pozo a un miembro por turno, con el orden definido de forma transparente y sin que nadie pueda desaparecer con el dinero. La demo corre una rueda acelerada para que los jueces vean cada pago liquidarse. Una construcción significativa para un día completo.', 'crypto-web3', '12-24h', 12, 24, 'intermediate', '["defi","smart-contracts","payments"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Cross-Chain Address Book that Pays the Right Network Automatically', 'Agenda multicadena que paga en la red correcta automáticamente', 'Save contacts by name once and the app remembers which chains each person accepts; when you send, it picks a working network and warns if you are about to pay on a chain the recipient cannot receive. A demoable wallet helper whose hook is killing the number-one way people lose funds: sending to the wrong network.', 'Guardá contactos por nombre una sola vez y la app recuerda qué cadenas acepta cada persona; al enviar, elige una red válida y te avisa si estás por pagar en una cadena que el destinatario no puede recibir. Un asistente de wallet demostrable cuyo gancho es eliminar la causa número uno de pérdida de fondos: enviar a la red equivocada.', 'crypto-web3', '12-24h', 12, 24, 'advanced', '["wallets","payments"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('NFT Mint That Reveals Art Only After the Holder Visits a Place', 'NFT cuyo arte se revela solo cuando el dueño visita un lugar', 'Mint a collectible that starts blank and unlocks new artwork layers each time the holder physically checks in at a tagged location, building a personal travel mosaic over time. The demo mints one, checks in at two spots, and watches the image evolve. A creative build whose hook ties an on-chain asset to real-world movement for a full day.', 'Acuñá un coleccionable que arranca en blanco y desbloquea nuevas capas de arte cada vez que el dueño se registra físicamente en un lugar etiquetado, armando un mosaico de viajes personal con el tiempo. La demo acuña uno, hace check-in en dos sitios y muestra la imagen evolucionar. Una construcción creativa cuyo gancho liga un activo on-chain al movimiento real para un día completo.', 'crypto-web3', '12-24h', 12, 24, 'intermediate', '["nfts","identity"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Rug-Pull Early-Warning Scanner for Brand-New Tokens', 'Escáner de alerta temprana de rug-pull para tokens nuevos', 'Paste a freshly launched token and get a checklist of red flags: liquidity that is not locked, an owner who can mint unlimited supply, a tiny number of holders, and trading functions that block selling. Each flag is scored and explained. A demoable safety tool that turns the chaos of new launches into one honest verdict for a short build.', 'Pegá un token recién lanzado y obtené una lista de banderas rojas: liquidez sin bloquear, un dueño que puede emitir suministro ilimitado, muy pocos holders y funciones de trading que bloquean la venta. Cada bandera se puntúa y se explica. Una herramienta de seguridad demostrable que convierte el caos de los lanzamientos nuevos en un veredicto honesto para una construcción corta.', 'crypto-web3', '6-12h', 6, 12, 'intermediate', '["on-chain-data","defi","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Pay-Per-Second Streaming Paywall for Articles and Videos', 'Muro de pago por segundo en streaming para artículos y videos', 'Readers unlock content by streaming micro-payments only for the seconds they actually spend, and the meter stops the instant they leave, so nobody pays for what they skip. Creators see live earnings tick up per active reader. A demoable build whose hook replaces clunky subscriptions with fair, granular pay-as-you-go access.', 'Los lectores desbloquean contenido transmitiendo micropagos solo por los segundos que realmente consumen, y el medidor se detiene apenas se van, así nadie paga lo que se saltea. Los creadores ven sus ganancias subir en vivo por cada lector activo. Una construcción demostrable cuyo gancho reemplaza las suscripciones torpes por un acceso justo y granular de pago por uso.', 'crypto-web3', '12-24h', 12, 24, 'advanced', '["payments","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Portfolio Sankey that Shows Where Your Crypto Actually Flowed', 'Sankey de cartera que muestra a dónde fluyó tu cripto de verdad', 'Connect a wallet and see a flowing diagram of your funds across time: which exchange they came from, which protocols they passed through, and where profits and losses landed. Hover any band to see the trades behind it. A visually striking read-only build that turns a confusing transaction history into one honest money map.', 'Conectá una wallet y mirá un diagrama fluido de tus fondos en el tiempo: de qué exchange vinieron, por qué protocolos pasaron y dónde quedaron ganancias y pérdidas. Pasá el cursor por cualquier banda para ver las operaciones detrás. Una construcción visual de solo lectura que convierte un historial confuso en un mapa honesto del dinero.', 'crypto-web3', '6-12h', 6, 12, 'intermediate', '["on-chain-data","wallets","defi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Conditional Escrow for Freelancers that Releases on Proof of Work', 'Custodia condicional para freelancers que libera con prueba de trabajo', 'A client locks payment in escrow and the funds release automatically when an agreed deliverable is confirmed, with a simple dispute path that splits the pot if both sides disagree. Both parties watch a clear status: locked, delivered, released. A meaningful full-day build that makes trustless freelance payments feel as simple as a status bar.', 'Un cliente bloquea el pago en custodia y los fondos se liberan automáticamente cuando se confirma un entregable acordado, con una vía simple de disputa que reparte el pozo si ambas partes no se ponen de acuerdo. Las dos partes ven un estado claro: bloqueado, entregado, liberado. Una construcción significativa de un día que hace que los pagos freelance sin confianza se sientan como una barra de estado.', 'crypto-web3', '12-24h', 12, 24, 'intermediate', '["payments","smart-contracts","identity"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Soulbound Skill Passport that Issuers Sign and Anyone Verifies', 'Pasaporte de habilidades soulbound que emisores firman y todos verifican', 'Schools, employers, or communities issue non-transferable credentials to a person''s wallet, and a public verifier page confirms each badge is genuine and who signed it, without a central database. The demo issues a course completion and then verifies it from a stranger''s browser. A useful identity build for a full day.', 'Escuelas, empleadores o comunidades emiten credenciales intransferibles a la wallet de una persona, y una página verificadora pública confirma que cada insignia es genuina y quién la firmó, sin una base de datos central. La demo emite la finalización de un curso y luego la verifica desde el navegador de un desconocido. Una construcción de identidad útil para un día completo.', 'crypto-web3', '12-24h', 12, 24, 'intermediate', '["identity","nfts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Prediction Market for Friend Bets that Settles Itself by Vote', 'Mercado de predicciones para apuestas entre amigos que se salda por voto', 'Friends post a yes/no bet, stake stablecoins on either side, and when the deadline hits the group votes on the outcome to release the pot to the winners. Built-in stakes discourage lying about results. A fun, demoable social build whose hook is settling ''wanna bet?'' moments fairly without a bookie, scoped for a full day.', 'Los amigos publican una apuesta de sí/no, ponen stablecoins en algún lado y, al llegar la fecha límite, el grupo vota el resultado para liberar el pozo a los ganadores. Las apuestas integradas desalientan mentir sobre los resultados. Una construcción social divertida y demostrable cuyo gancho es saldar los momentos de ''¿apostamos?'' de forma justa sin corredor, pensada para un día completo.', 'crypto-web3', '12-24h', 12, 24, 'intermediate', '["defi","dao","payments"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Impermanent-Loss Simulator that Plays Out Your LP Position', 'Simulador de pérdida impermanente que recrea tu posición LP', 'Pick a liquidity pool and a deposit amount, drag a slider of price moves, and watch the tool show your impermanent loss versus simply holding, fees earned, and the break-even point. A clear single-screen teaching tool whose hook is making an abstract DeFi risk finally click in a short, visual sprint.', 'Elegí un pool de liquidez y un monto de depósito, arrastrá un deslizador de movimientos de precio y mirá cómo la herramienta muestra tu pérdida impermanente frente a simplemente holdear, las comisiones ganadas y el punto de equilibrio. Una herramienta didáctica de una sola pantalla cuyo gancho es hacer que un riesgo abstracto de DeFi por fin se entienda en un sprint corto y visual.', 'crypto-web3', '3-6h', 3, 6, 'intermediate', '["defi","on-chain-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Wallet Birthday Card that Reads a Year of On-Chain Activity', 'Tarjeta de cumpleaños de wallet que lee un año de actividad on-chain', 'Enter any wallet and generate a shareable year-in-review card: total transactions, biggest swap, favorite protocol, gas burned, and a fun personality label drawn from the patterns. A delightful, demoable single-page build whose hook is turning dry on-chain history into a card people want to post, perfect for a short sprint.', 'Ingresá cualquier wallet y generá una tarjeta compartible de resumen anual: total de transacciones, el swap más grande, el protocolo favorito, el gas quemado y una etiqueta de personalidad divertida sacada de los patrones. Una construcción de una página, encantadora y demostrable, cuyo gancho es convertir un historial on-chain árido en una tarjeta que la gente quiere publicar, ideal para un sprint corto.', 'crypto-web3', '1-3h', 1, 3, 'beginner', '["on-chain-data","wallets"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('QR Checkout that Lets Any Shop Accept Stablecoins in Minutes', 'Checkout con QR que permite a cualquier comercio aceptar stablecoins', 'A merchant types a price, shows a QR, and the customer pays in stablecoins from any wallet; the shop sees an instant paid confirmation and a running daily total, with no hardware. The hook is dead-simple point-of-sale crypto that a corner store could set up before lunch. A clean, demoable build for a full day.', 'Un comerciante escribe un precio, muestra un QR y el cliente paga en stablecoins desde cualquier wallet; el local ve una confirmación de pago instantánea y un total diario en curso, sin hardware. El gancho es un punto de venta cripto súper simple que un kiosco podría configurar antes del almuerzo. Una construcción limpia y demostrable para un día completo.', 'crypto-web3', '12-24h', 12, 24, 'intermediate', '["payments","wallets"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Quadratic Funding Round for a Community in a Weekend', 'Ronda de financiamiento cuadrático para una comunidad en un fin de semana', 'Stand up a full grants round where a community funds projects and a matching pool amplifies many small donations over a few big ones, so popular support beats deep pockets. Organizers configure the round, contributors donate, and a live leaderboard shows matched totals. A substantial build with real governance depth for a hackathon weekend.', 'Montá una ronda completa de subvenciones donde una comunidad financia proyectos y un fondo de contrapartida amplifica muchas donaciones pequeñas por sobre pocas grandes, para que el apoyo popular le gane al bolsillo profundo. Los organizadores configuran la ronda, los aportantes donan y un ranking en vivo muestra los totales igualados. Una construcción sustancial con verdadera profundidad de gobernanza para un fin de semana de hackathon.', 'crypto-web3', '48h+', 48, 72, 'advanced', '["dao","defi","payments"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Inheritance Vault that Hands Over a Wallet If You Go Quiet', 'Bóveda de herencia que entrega una wallet si dejás de aparecer', 'Set up a dead-man''s-switch vault: if you do not check in for a chosen period, control of the assets passes to named heirs, with a grace window and one-tap cancel if you are simply on vacation. Heirs see a clear countdown. A meaningful, trust-heavy build that solves the real problem of crypto lost forever when someone dies.', 'Configurá una bóveda con interruptor de hombre muerto: si no te registrás durante un período elegido, el control de los activos pasa a herederos designados, con una ventana de gracia y cancelación de un toque por si solo estabas de vacaciones. Los herederos ven una cuenta regresiva clara. Una construcción significativa y de alta confianza que resuelve el problema real de la cripto perdida para siempre cuando alguien muere.', 'crypto-web3', '24-48h', 24, 48, 'advanced', '["wallets","smart-contracts","identity"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Onboarding Wallet that Hides Seed Phrases Behind Passkeys', 'Wallet de onboarding que esconde la frase semilla tras passkeys', 'A first-time wallet where new users sign in with a phone passkey and recover access through trusted contacts, never seeing a seed phrase, yet still hold real self-custody. The demo onboards a non-crypto friend in under a minute and recovers a lost device live. A polished, ambitious build that tackles web3''s biggest drop-off for a weekend.', 'Una wallet para principiantes donde los usuarios nuevos inician sesión con un passkey del teléfono y recuperan el acceso mediante contactos de confianza, sin ver nunca una frase semilla, pero conservando verdadera autocustodia. La demo registra a un amigo no cripto en menos de un minuto y recupera un dispositivo perdido en vivo. Una construcción pulida y ambiciosa que ataca el mayor abandono de web3 para un fin de semana.', 'crypto-web3', '24-48h', 24, 48, 'advanced', '["wallets","identity"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Anonymous Membership Pass that Proves You Belong Without Doxxing', 'Pase de membresía anónimo que prueba que pertenecés sin doxxearte', 'Holders of a group''s token can prove membership to gate a chat, an event, or a vote, using a zero-knowledge proof so they reveal that they qualify without revealing which wallet they are. The demo unlocks a private door from a clean browser while the address stays hidden. An advanced privacy build worth a full weekend.', 'Los poseedores del token de un grupo pueden probar su membresía para acceder a un chat, un evento o una votación, usando una prueba de conocimiento cero para revelar que califican sin revelar qué wallet son. La demo desbloquea una puerta privada desde un navegador limpio mientras la dirección permanece oculta. Una construcción avanzada de privacidad que vale un fin de semana completo.', 'crypto-web3', '48h+', 48, 72, 'advanced', '["identity","dao","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Charity Stream that Shows Donors Exactly Where Each Coin Went', 'Stream de caridad que muestra a los donantes a dónde fue cada moneda', 'Donate to a cause and follow your specific contribution on a live map of releases: funds sit in a transparent vault and only unlock when the charity posts proof of a milestone, like receipts or photos. Donors watch their coins move from pledged to spent. A trust-building full-day flow that makes giving feel accountable.', 'Doná a una causa y seguí tu aporte específico en un mapa en vivo de liberaciones: los fondos quedan en una bóveda transparente y solo se desbloquean cuando la organización publica prueba de un hito, como recibos o fotos. Los donantes ven sus monedas pasar de comprometidas a gastadas. Un flujo de un día que genera confianza y hace que donar se sienta rendido de cuentas.', 'crypto-web3', '12-24h', 12, 24, 'intermediate', '["payments","on-chain-data","dao"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Token-Gated Group Trip Fund with Shared Spending Rules', 'Fondo de viaje grupal token-gated con reglas de gasto compartidas', 'A travel crew pools money into a shared vault and sets rules together: any spend over a limit needs two approvals, and everyone sees the balance in real time. At the end, leftover funds split back automatically by what each person put in. A demoable group-finance build whose hook is friction-free shared spending for a full day.', 'Un grupo de viaje junta dinero en una bóveda compartida y fija reglas en conjunto: cualquier gasto sobre un límite necesita dos aprobaciones y todos ven el saldo en tiempo real. Al final, lo que sobra se reparte automáticamente según lo que aportó cada uno. Una construcción de finanzas grupales demostrable cuyo gancho es el gasto compartido sin fricción para un día completo.', 'crypto-web3', '12-24h', 12, 24, 'intermediate', '["wallets","payments","dao"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Address Reputation Lookup that Warns Before You Trade With a Stranger', 'Consulta de reputación de dirección que te avisa antes de operar con un desconocido', 'Paste a wallet address and get a quick reputation card: age, whether it has interacted with known scam contracts, how many people it has paid, and any reports against it. A focused read-only safety lookup whose hook is a one-screen gut check before sending money to someone you met online, scoped for a short sprint.', 'Pegá una dirección de wallet y obtené una tarjeta rápida de reputación: antigüedad, si interactuó con contratos de estafa conocidos, a cuánta gente le pagó y si tiene reportes en contra. Una consulta de seguridad de solo lectura y enfocada cuyo gancho es un chequeo de una pantalla antes de mandarle dinero a alguien que conociste en línea, pensada para un sprint corto.', 'crypto-web3', '3-6h', 3, 6, 'intermediate', '["on-chain-data","identity","wallets"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Instant Token Faucet Page for Testnet Workshops and Demos', 'Página de faucet instantánea para talleres y demos de testnet', 'Spin up a branded faucet page where workshop attendees paste an address and receive testnet tokens once each, with a simple rate limit so nobody drains it. Organizers watch a live log of claims. A tiny, genuinely useful build that any hackathon mentor would want, perfectly sized for a one-to-three hour sprint.', 'Levantá una página de faucet con marca donde los asistentes a un taller pegan una dirección y reciben tokens de testnet una vez cada uno, con un límite simple para que nadie la vacíe. Los organizadores miran un registro en vivo de reclamos. Una construcción diminuta y genuinamente útil que cualquier mentor de hackathon querría, del tamaño justo para un sprint de una a tres horas.', 'crypto-web3', '1-3h', 1, 3, 'beginner', '["smart-contracts","wallets"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Live Stablecoin Remittance That Beats the Wire on Fees', 'Remesa en stablecoins en vivo que le gana al giro bancario en comisiones', 'Send money home by converting to a stablecoin, moving it instantly, and letting the recipient cash out locally, with a side-by-side that shows the fee and time saved versus a traditional wire. The demo sends a remittance across regions and shows it land in seconds. A meaningful full-day build aimed at real cross-border pain.', 'Mandá dinero a casa convirtiendo a una stablecoin, moviéndola al instante y dejando que el destinatario la retire localmente, con una comparación lado a lado que muestra la comisión y el tiempo ahorrado frente a un giro tradicional. La demo envía una remesa entre regiones y la muestra llegar en segundos. Una construcción significativa de un día apuntada al dolor real de los pagos transfronterizos.', 'crypto-web3', '12-24h', 12, 24, 'intermediate', '["payments","defi","wallets"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Phishing Login Scanner that Reads a Screenshot', 'Escáner de logins de phishing que lee una captura', 'Paste a screenshot of any login page and the tool flags phishing tells: a favicon whose domain doesn''t match the brand, off-brand fonts, and form actions that post off-site. It returns a 0-100 risk score with each reason highlighted on the image. A sharp single-screen build that demos in seconds on a half-day sprint.', 'Pegá una captura de cualquier página de login y la herramienta marca señales de phishing: un favicon cuyo dominio no coincide con la marca, tipografías fuera de estilo y formularios que envían datos a otro sitio. Devuelve un puntaje de riesgo de 0 a 100 con cada motivo resaltado sobre la imagen. Una build de una sola pantalla que se demuestra en segundos.', 'cybersecurity', '3-6h', 3, 6, 'intermediate', '["web-security","privacy"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Password Strength Meter that Explains the Crack Time', 'Medidor de contraseñas que explica el tiempo de crackeo', 'A live meter that estimates how long a real attacker would take to crack the password you''re typing, naming the specific weakness: a leaked dictionary word, a predictable keyboard walk, or a date pattern. Instead of a vague color bar it shows the actual reasoning. A tight, visual one-feature build perfect for a short sprint.', 'Un medidor en vivo que estima cuánto tardaría un atacante real en crackear la contraseña que estás escribiendo, nombrando la debilidad exacta: una palabra de diccionario filtrada, un patrón de teclado predecible o una fecha. En lugar de una barra de color vaga, muestra el razonamiento real. Una build de una sola función, visual y compacta, ideal para un sprint corto.', 'cybersecurity', '1-3h', 1, 3, 'beginner', '["authentication","privacy"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Have-I-Been-Exposed Checker for a Whole Domain', 'Verificador de exposición de brechas para todo un dominio', 'Type a company domain and the tool cross-references public breach datasets to surface which employee email patterns have appeared in leaks, grouped by breach and year. It turns a scary abstract risk into a concrete list a small team can act on. A focused single-screen build that''s genuinely useful and quick to demo.', 'Escribí el dominio de una empresa y la herramienta cruza datasets públicos de brechas para mostrar qué patrones de correo de empleados aparecieron en filtraciones, agrupados por brecha y año. Convierte un riesgo abstracto y aterrador en una lista concreta sobre la que un equipo chico puede actuar. Una build enfocada de una sola pantalla, útil y rápida de demostrar.', 'cybersecurity', '3-6h', 3, 6, 'beginner', '["privacy","authentication"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Browser Extension that Warns Before You Reuse a Password', 'Extensión que avisa antes de reusar una contraseña', 'A browser extension that fingerprints each password you submit locally and warns the instant you reuse one across sites, without ever storing the password itself. It shows a simple map of which sites share credentials so you know your real blast radius. A privacy-first build with a satisfying live demo on real login forms.', 'Una extensión de navegador que toma una huella local de cada contraseña que enviás y te avisa apenas reusás una entre sitios, sin guardar nunca la contraseña en sí. Muestra un mapa simple de qué sitios comparten credenciales para que conozcas tu radio de exposición real. Una build centrada en privacidad con una demo en vivo satisfactoria sobre formularios reales.', 'cybersecurity', '6-12h', 6, 12, 'intermediate', '["authentication","privacy","web-security"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Visual Diff Tool for HTTP Security Headers', 'Herramienta de diff visual para cabeceras de seguridad HTTP', 'Enter two URLs and the tool fetches their HTTP responses and shows a side-by-side diff of security headers, grading each site and explaining what a missing CSP or HSTS header actually lets an attacker do. Great for comparing your staging site against production. A clean, demoable build that fits a short focused sprint.', 'Ingresá dos URLs y la herramienta obtiene sus respuestas HTTP y muestra un diff lado a lado de las cabeceras de seguridad, calificando cada sitio y explicando qué le permite a un atacante una CSP o HSTS faltante. Ideal para comparar tu sitio de staging contra producción. Una build limpia y demostrable que entra en un sprint corto y enfocado.', 'cybersecurity', '3-6h', 3, 6, 'intermediate', '["web-security","network"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('QR Code Safety Inspector that Unwraps the Real Link', 'Inspector de QR que revela el enlace real', 'Point your camera at a QR code and the tool decodes it, follows every redirect hop, and shows the final destination plus warning signs like a freshly registered domain or a look-alike of a known brand. It stops the ''scan and pray'' moment on posters and parking meters. A snappy single-feature build with an obvious live demo.', 'Apuntá la cámara a un código QR y la herramienta lo decodifica, sigue cada salto de redirección y muestra el destino final más señales de alerta como un dominio recién registrado o una imitación de una marca conocida. Frena el momento de ''escanear y rezar'' en carteles y parquímetros. Una build ágil de una sola función con una demo en vivo evidente.', 'cybersecurity', '3-6h', 3, 6, 'beginner', '["web-security","privacy"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Metadata Stripper that Shows What Your Photo Leaks', 'Limpiador de metadatos que muestra qué filtra tu foto', 'Drop in a photo and the tool maps its hidden EXIF metadata onto a real map and timeline: the GPS coordinates, the exact timestamp, even the device serial. Then it strips it all and hands back a clean file. The shock of seeing your home pinned on a map makes the privacy lesson land instantly. A tight short-sprint build.', 'Arrastrá una foto y la herramienta mapea sus metadatos EXIF ocultos sobre un mapa real y una línea de tiempo: las coordenadas GPS, la marca de tiempo exacta, hasta el número de serie del dispositivo. Después lo borra todo y te devuelve un archivo limpio. El impacto de ver tu casa marcada en un mapa hace que la lección de privacidad cale al instante. Una build compacta de sprint corto.', 'cybersecurity', '1-3h', 1, 3, 'beginner', '["privacy","forensics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Sandbox that Detonates a Suspicious File and Narrates It', 'Sandbox que detona un archivo sospechoso y lo narra', 'Upload a suspicious file into an isolated environment and watch a live timeline of what it tries to do: which files it touches, which domains it phones home to, which registry keys it edits. It turns opaque malware behavior into a readable story with a verdict at the end. An ambitious build with a dramatic, judge-friendly demo.', 'Subí un archivo sospechoso a un entorno aislado y mirá una línea de tiempo en vivo de lo que intenta hacer: qué archivos toca, a qué dominios llama a casa, qué claves del registro edita. Convierte el comportamiento opaco del malware en una historia legible con un veredicto al final. Una build ambiciosa con una demo dramática y atractiva para el jurado.', 'cybersecurity', '24-48h', 24, 48, 'advanced', '["malware-analysis","forensics","network"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Static Analyzer that Flags Hardcoded Secrets in a Repo', 'Analizador que detecta secretos hardcodeados en un repo', 'Point the tool at a Git repository and it scans the full commit history for leaked secrets: API keys, tokens, private keys, even ones deleted in a later commit but still living in the log. It ranks findings by how exploitable they are right now. A high-value build that demos beautifully against a planted test repo.', 'Apuntá la herramienta a un repositorio Git y escanea todo el historial de commits en busca de secretos filtrados: claves de API, tokens, llaves privadas, incluso las borradas en un commit posterior pero aún vivas en el log. Ordena los hallazgos por qué tan explotables son ahora mismo. Una build de alto valor que se demuestra muy bien contra un repo de prueba con secretos plantados.', 'cybersecurity', '6-12h', 6, 12, 'intermediate', '["web-security","cryptography"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Beginner CTF Arena with Auto-Graded Bite-Size Challenges', 'Arena CTF para principiantes con retos cortos autocalificados', 'A web arena that drops newcomers into tiny capture-the-flag challenges, one concept each, with instant flag checking and a hint ladder that costs points. It teaches web, crypto, and forensics basics through play instead of lectures. A fuller build with a leaderboard and progression that''s fun to watch a judge climb.', 'Una arena web que mete a los novatos en pequeños retos de capture-the-flag, un concepto cada uno, con verificación instantánea de la flag y una escalera de pistas que cuesta puntos. Enseña fundamentos de web, cripto y forense jugando en lugar de dar lecciones. Una build más completa con tabla de posiciones y progresión, divertida de ver a un jurado escalar.', 'cybersecurity', '12-24h', 12, 24, 'intermediate', '["ctf","web-security"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Cipher Playground that Animates Each Encryption Step', 'Laboratorio de cifrado que anima cada paso del cifrado', 'An interactive playground for classic and modern ciphers where you type a message and watch the algorithm transform it byte by byte, with each step narrated in plain language. It makes XOR, Caesar, and block-cipher rounds finally click for learners. A visual single-purpose build that''s genuinely useful for teaching crypto.', 'Un laboratorio interactivo de cifrados clásicos y modernos donde escribís un mensaje y mirás al algoritmo transformarlo byte por byte, con cada paso narrado en lenguaje claro. Hace que XOR, César y las rondas de un cifrado por bloques finalmente se entiendan. Una build visual de propósito único, realmente útil para enseñar criptografía.', 'cybersecurity', '3-6h', 3, 6, 'beginner', '["cryptography","ctf"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('End-to-End Encrypted Note that Burns After One Read', 'Nota cifrada de extremo a extremo que se borra tras leerse', 'Write a secret, get a one-time link, and the note self-destructs the moment it''s opened, with the decryption happening in the recipient''s browser so the server never sees plaintext. A read receipt tells the sender it''s gone. A clean build whose whole charm is the satisfying ''this message has burned'' moment in the demo.', 'Escribí un secreto, obtené un enlace de un solo uso y la nota se autodestruye en el instante en que se abre, con el descifrado ocurriendo en el navegador del destinatario para que el servidor nunca vea el texto plano. Un acuse de lectura le avisa al emisor que ya no existe. Una build limpia cuyo encanto es el momento satisfactorio de ''este mensaje se quemó'' en la demo.', 'cybersecurity', '6-12h', 6, 12, 'intermediate', '["cryptography","privacy"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Passkey Login Demo that Kills the Password Entirely', 'Demo de login con passkey que elimina la contraseña', 'A drop-in login flow that replaces passwords with device passkeys, letting a user register and sign in with a fingerprint or face, then showing the cryptographic challenge-response happening under the hood. It makes phishing-resistant auth tangible. A focused build with a clean before-and-after demo on a real phone.', 'Un flujo de login listo para integrar que reemplaza contraseñas por passkeys del dispositivo, dejando que un usuario se registre e inicie sesión con huella o rostro, y luego mostrando el desafío-respuesta criptográfico que ocurre por debajo. Hace tangible la autenticación resistente al phishing. Una build enfocada con una demo limpia de antes y después en un teléfono real.', 'cybersecurity', '6-12h', 6, 12, 'intermediate', '["authentication","web-security"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Wi-Fi Network Mapper that Spots Rogue Access Points', 'Mapeador de Wi-Fi que detecta puntos de acceso falsos', 'A tool that scans nearby Wi-Fi and visualizes every access point, flagging evil-twin networks that clone a trusted SSID but differ in signal pattern or MAC vendor. It helps you spot the fake café hotspot before you connect. An intermediate build with a vivid live demo of a planted rogue AP lighting up red on screen.', 'Una herramienta que escanea el Wi-Fi cercano y visualiza cada punto de acceso, marcando redes gemelas maliciosas que clonan un SSID confiable pero difieren en patrón de señal o fabricante de MAC. Te ayuda a detectar el hotspot falso del café antes de conectarte. Una build intermedia con una demo en vivo vívida de un AP falso plantado encendiéndose en rojo en pantalla.', 'cybersecurity', '6-12h', 6, 12, 'advanced', '["network","forensics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Live Log Tail that Surfaces Brute-Force Attacks in Real Time', 'Visor de logs en vivo que detecta ataques de fuerza bruta', 'A dashboard that tails server auth logs and lights up the instant it sees a brute-force pattern: a burst of failed logins from one IP, a credential-stuffing spread across accounts, or impossible-travel sign-ins. It turns a wall of log lines into a clear attack story. A demoable build you can trigger live with a scripted attack.', 'Un panel que sigue los logs de autenticación del servidor y se enciende apenas detecta un patrón de fuerza bruta: una ráfaga de logins fallidos desde una IP, un relleno de credenciales repartido entre cuentas o inicios de sesión de viaje imposible. Convierte un muro de líneas de log en una historia de ataque clara. Una build demostrable que podés disparar en vivo con un ataque scripteado.', 'cybersecurity', '6-12h', 6, 12, 'intermediate', '["network","forensics","authentication"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Phishing Email Triage that Highlights the Manipulation', 'Triaje de correos de phishing que resalta la manipulación', 'Forward a suspicious email and the tool dissects it: spoofed sender headers, urgency and fear language, mismatched link text versus real destination, and a confidence verdict. It annotates the message inline so a non-technical user sees exactly why it''s a trap. A focused build with an instantly readable, judge-friendly demo.', 'Reenviá un correo sospechoso y la herramienta lo disecciona: cabeceras de remitente falsificadas, lenguaje de urgencia y miedo, texto del enlace que no coincide con el destino real y un veredicto de confianza. Anota el mensaje en línea para que un usuario no técnico vea exactamente por qué es una trampa. Una build enfocada con una demo legible al instante y atractiva para el jurado.', 'cybersecurity', '6-12h', 6, 12, 'intermediate', '["web-security","privacy"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Disk Image Forensics Timeline from a Seized Drive Dump', 'Línea de tiempo forense desde un volcado de disco incautado', 'Feed in a disk image and the tool reconstructs a forensic timeline: recently deleted files, last-opened documents, browser history, and USB device plug-ins, all on one scrubbing timeline. It turns raw bytes into the story of what someone did and when. An ambitious weekend build with a compelling investigative demo.', 'Cargá una imagen de disco y la herramienta reconstruye una línea de tiempo forense: archivos borrados recientemente, documentos abiertos por última vez, historial del navegador y conexiones de dispositivos USB, todo en una única línea de tiempo navegable. Convierte bytes crudos en la historia de lo que alguien hizo y cuándo. Una build ambiciosa de fin de semana con una demo investigativa convincente.', 'cybersecurity', '24-48h', 24, 48, 'advanced', '["forensics","malware-analysis"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('API Fuzzer that Finds Broken Access Control by Swapping IDs', 'Fuzzer de API que halla fallas de acceso cambiando IDs', 'Point the tool at an API and a logged-in token, and it methodically swaps object IDs and tweaks parameters to find endpoints that leak other users'' data. It reports each broken-access-control hole with the exact request to reproduce it. A high-impact build that demos by pulling another account''s data live before fixing it.', 'Apuntá la herramienta a una API y a un token autenticado, y va intercambiando IDs de objetos y modificando parámetros de forma metódica para hallar endpoints que filtran datos de otros usuarios. Reporta cada falla de control de acceso con la petición exacta para reproducirla. Una build de alto impacto que se demuestra extrayendo datos de otra cuenta en vivo antes de corregirlo.', 'cybersecurity', '12-24h', 12, 24, 'advanced', '["web-security","network"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Steganography Studio that Hides and Reveals Files in Images', 'Estudio de esteganografía que oculta y revela archivos en fotos', 'A studio to embed a secret file inside an ordinary image and later extract it, with a visual heatmap that shows which pixels were altered and how much capacity remains. It also runs the reverse: scanning a suspect image for hidden payloads. A playful single-purpose build with a magic-trick reveal that wows in a demo.', 'Un estudio para incrustar un archivo secreto dentro de una imagen común y luego extraerlo, con un mapa de calor visual que muestra qué píxeles se alteraron y cuánta capacidad queda. También hace lo inverso: escanear una imagen sospechosa en busca de cargas ocultas. Una build lúdica de propósito único con una revelación tipo truco de magia que impacta en la demo.', 'cybersecurity', '3-6h', 3, 6, 'intermediate', '["cryptography","forensics","ctf"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Threat Model Generator from a Plain-English App Description', 'Generador de modelo de amenazas desde una descripción simple', 'Describe your app in plain English and the tool drafts a structured threat model: trust boundaries, likely attack vectors per component, and ranked mitigations using a known framework. It turns the intimidating blank-page step of security planning into a starting draft. A focused build that demos by threat-modeling the judge''s own idea.', 'Describí tu app en lenguaje natural y la herramienta redacta un modelo de amenazas estructurado: límites de confianza, vectores de ataque probables por componente y mitigaciones priorizadas usando un marco conocido. Convierte el intimidante paso de la página en blanco de la planificación de seguridad en un borrador inicial. Una build enfocada que se demuestra modelando la idea del propio jurado.', 'cybersecurity', '6-12h', 6, 12, 'intermediate', '["web-security","network"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Permission X-Ray for the Apps on Your Phone', 'Radiografía de permisos para las apps de tu teléfono', 'Import your installed-app list and the tool x-rays each app''s requested permissions, scoring how much each one over-asks for its category and flagging the riskiest combinations, like a flashlight that wants contacts and location. It turns a buried settings screen into a clear privacy report. A tidy build with a relatable, fast demo.', 'Importá tu lista de apps instaladas y la herramienta radiografía los permisos que pide cada una, puntuando cuánto pide de más para su categoría y marcando las combinaciones más riesgosas, como una linterna que quiere contactos y ubicación. Convierte una pantalla de ajustes enterrada en un informe de privacidad claro. Una build prolija con una demo cercana y rápida.', 'cybersecurity', '3-6h', 3, 6, 'beginner', '["privacy","authentication"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('TLS Certificate Inspector that Explains Why a Site Is Trusted', 'Inspector de certificados TLS que explica por qué se confía', 'Enter a domain and the tool walks the full certificate chain, naming the issuer, the expiry clock, weak algorithms, and any mismatch, all in plain language a beginner can follow. It demystifies the padlock icon and shows what ''secure'' actually means. A clean single-screen build that''s quick to ship in a short sprint.', 'Ingresá un dominio y la herramienta recorre toda la cadena de certificados, nombrando al emisor, el reloj de vencimiento, los algoritmos débiles y cualquier discordancia, todo en lenguaje claro que un principiante puede seguir. Desmitifica el ícono del candado y muestra qué significa realmente ''seguro''. Una build limpia de una sola pantalla, rápida de entregar en un sprint corto.', 'cybersecurity', '3-6h', 3, 6, 'beginner', '["cryptography","network","web-security"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Honeypot Login Page that Profiles Whoever Attacks It', 'Página de login señuelo que perfila a quien la ataca', 'Deploy a fake admin login that looks irresistible to bots, then watch a live dashboard profile every attacker: the credentials they try, their origin, and the tools they fingerprint as. It turns being attacked into useful threat intelligence. An intermediate build with a thrilling demo as real internet bots start poking it on stage.', 'Desplegá un login de admin falso que resulta irresistible para los bots, y luego mirá un panel en vivo perfilar a cada atacante: las credenciales que prueban, su origen y las herramientas que delatan. Convierte el ser atacado en inteligencia de amenazas útil. Una build intermedia con una demo emocionante cuando bots reales de internet empiezan a tantearla en el escenario.', 'cybersecurity', '12-24h', 12, 24, 'intermediate', '["network","forensics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Dependency Scanner that Ranks Bugs by Real Reachability', 'Escáner de dependencias que prioriza por alcance real', 'Point the tool at a project''s dependency manifest and it lists known vulnerabilities, but the twist is it checks whether your code actually calls the vulnerable function, pushing the real risks to the top and silencing the noise. It cuts through alert fatigue. A meaty build that demos by triaging a deliberately vulnerable repo.', 'Apuntá la herramienta al manifiesto de dependencias de un proyecto y lista las vulnerabilidades conocidas, pero el giro es que verifica si tu código realmente llama a la función vulnerable, empujando los riesgos reales arriba y silenciando el ruido. Corta con la fatiga de alertas. Una build sustanciosa que se demuestra triando un repo deliberadamente vulnerable.', 'cybersecurity', '12-24h', 12, 24, 'advanced', '["web-security","malware-analysis"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Voice Deepfake Detector for Suspicious Phone Calls', 'Detector de deepfakes de voz para llamadas sospechosas', 'Record a short clip of a caller and the tool scores how likely the voice is AI-generated, listening for the unnatural breathing, flat prosody, and spectral artifacts cloned voices leave behind. It targets the rising ''your boss is calling'' scam. A focused build with a punchy demo: play a real clip and a fake one and watch the meter split.', 'Grabá un clip corto de quien llama y la herramienta puntúa qué tan probable es que la voz sea generada por IA, escuchando la respiración antinatural, la prosodia plana y los artefactos espectrales que dejan las voces clonadas. Apunta a la creciente estafa del ''te llama tu jefe''. Una build enfocada con una demo contundente: reproducí un clip real y uno falso y mirá el medidor partirse.', 'cybersecurity', '12-24h', 12, 24, 'advanced', '["forensics","privacy"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Secret Splitter Using Real Threshold Cryptography', 'Divisor de secretos con criptografía de umbral real', 'Split a master secret into several shares so that any chosen subset, say three of five, can reconstruct it, but fewer reveal nothing at all. The tool generates printable shares and reassembles them live. It makes Shamir''s secret sharing tangible for inheritance keys or team vaults. A focused crypto build with a satisfying reconstruction demo.', 'Dividí un secreto maestro en varias partes de modo que cualquier subconjunto elegido, digamos tres de cinco, pueda reconstruirlo, pero menos no revelen nada en absoluto. La herramienta genera partes imprimibles y las reensambla en vivo. Hace tangible el reparto de secretos de Shamir para llaves de herencia o bóvedas de equipo. Una build de cripto enfocada con una demo de reconstrucción satisfactoria.', 'cybersecurity', '6-12h', 6, 12, 'advanced', '["cryptography","privacy"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Privacy Policy Translator that Tells You What You Agreed To', 'Traductor de políticas que te dice qué aceptaste', 'Paste a privacy policy or terms-of-service and the tool boils it down to plain language: what data they collect, who they sell it to, and the scariest clauses, each rated and quoted from the original. It turns a wall of legalese into a one-screen verdict. A focused build with a relatable demo on a real app''s policy.', 'Pegá una política de privacidad o términos de servicio y la herramienta los reduce a lenguaje claro: qué datos recopilan, a quién se los venden y las cláusulas más alarmantes, cada una calificada y citada del original. Convierte un muro de jerga legal en un veredicto de una sola pantalla. Una build enfocada con una demo cercana sobre la política de una app real.', 'cybersecurity', '3-6h', 3, 6, 'beginner', '["privacy","web-security"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Network Packet Replay that Reconstructs a Captured Session', 'Reproductor de paquetes que reconstruye una sesión capturada', 'Load a packet capture and the tool reconstructs the conversation: it reassembles transferred files, rebuilds visited web pages, and flags any credentials sent in the clear. It makes the danger of unencrypted traffic visceral by literally showing what a sniffer sees. An intermediate build with a striking, educational demo.', 'Cargá una captura de paquetes y la herramienta reconstruye la conversación: reensambla archivos transferidos, rearma páginas web visitadas y marca cualquier credencial enviada en texto plano. Hace visceral el peligro del tráfico sin cifrar mostrando literalmente lo que ve un sniffer. Una build intermedia con una demo llamativa y educativa.', 'cybersecurity', '12-24h', 12, 24, 'advanced', '["network","forensics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('One-Tap TOTP Generator with a Visual Clock-Drift Check', 'Generador de OTP por tiempo con chequeo visual de desfase', 'A clean authenticator that generates time-based one-time codes by scanning a setup QR, with a visual ring counting down each code and a clock-drift indicator that warns when your device time is off enough to break logins. It explains the math behind the rotating six digits. A compact, demoable build for a short sprint.', 'Un autenticador limpio que genera códigos de un solo uso basados en tiempo escaneando un QR de configuración, con un anillo visual que cuenta la cuenta regresiva de cada código y un indicador de desfase de reloj que avisa cuando la hora de tu dispositivo está lo bastante corrida como para romper los logins. Explica la matemática detrás de los seis dígitos rotativos. Una build compacta y demostrable para un sprint corto.', 'cybersecurity', '3-6h', 3, 6, 'intermediate', '["authentication","cryptography"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Ransomware Tripwire that Detects Mass File Encryption Early', 'Trampa de ransomware que detecta cifrado masivo a tiempo', 'A background watcher that seeds decoy files across folders and screams the instant something starts rapidly encrypting or renaming them, killing the offending process before it spreads. It buys precious minutes against ransomware. An ambitious build with a tense live demo as a simulated attack trips the wire and gets halted on stage.', 'Un vigilante en segundo plano que siembra archivos señuelo por las carpetas y grita en el instante en que algo empieza a cifrarlos o renombrarlos rápidamente, matando el proceso culpable antes de que se propague. Compra minutos preciosos frente al ransomware. Una build ambiciosa con una demo en vivo tensa cuando un ataque simulado activa la trampa y es detenido en el escenario.', 'cybersecurity', '24-48h', 24, 48, 'advanced', '["malware-analysis","forensics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Receipt Scanner that Estimates a Grocery Trip''s Footprint', 'Escaner de tickets que estima la huella de la compra', 'Snap a photo of any grocery receipt and the tool maps each line item to a food-emissions factor, then shows the trip''s carbon cost broken down by product. It highlights the three swaps that would cut the most CO2 — say, swapping beef for lentils — with the savings shown live. A tight single-screen build that turns an everyday object into an instant climate lesson.', 'Sacale una foto a cualquier ticket del supermercado y la herramienta asocia cada producto con su factor de emisiones, mostrando el costo de carbono del viaje desglosado por item. Resalta los tres cambios que mas reducirian el CO2 — por ejemplo, cambiar carne por lentejas — con el ahorro mostrado en vivo. Una construccion compacta de una sola pantalla que convierte un objeto cotidiano en una leccion climatica instantanea.', 'environment', '3-6h', 3, 6, 'intermediate', '["climate-data","waste"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Photo-to-Bin Sorter that Reads Your Local Recycling Rules', 'Clasificador foto-a-tacho que lee las reglas locales de reciclaje', 'Point your camera at a piece of trash and the app tells you exactly which bin it goes in — but keyed to your specific municipality''s rules, not a generic guess. It explains why, since the same yogurt cup is recyclable in one town and landfill in the next. The demo lets a judge enter a postcode and watch the answers change for the same object.', 'Apunta la camara a un residuo y la app te dice exactamente en que tacho va — pero segun las reglas de tu municipio especifico, no una suposicion generica. Te explica por que, ya que el mismo vaso de yogur es reciclable en un pueblo y basura en el siguiente. La demo permite a un juez ingresar un codigo postal y ver como cambian las respuestas para el mismo objeto.', 'environment', '6-12h', 6, 12, 'intermediate', '["waste"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Neighborhood Heat-Island Mapper from Open Thermal Tiles', 'Mapeador de islas de calor barriales con teselas termicas abiertas', 'Pull free thermal satellite tiles for any city, overlay them on a map, and surface the hottest blocks that also lack tree cover. It then ranks where planting a tree would cool the most people per tree, turning raw heat data into an action list. The demo lets a judge type their own city and watch the hot spots and planting priorities light up.', 'Trae teselas termicas satelitales gratuitas de cualquier ciudad, las superpone en un mapa y revela las cuadras mas calientes que ademas carecen de arboles. Luego clasifica donde plantar un arbol enfriaria a mas personas por arbol, convirtiendo datos crudos de calor en una lista de accion. La demo permite a un juez escribir su propia ciudad y ver encenderse los puntos calientes y las prioridades de plantacion.', 'environment', '12-24h', 12, 24, 'intermediate', '["climate-data","biodiversity"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Bird Song Logger that Maps Backyard Biodiversity Over Time', 'Registrador de cantos que mapea la biodiversidad del jardin', 'Leave a phone recording in a garden and the tool identifies bird species from their calls, then builds a running diversity index for that spot across days. It flags when a regular species goes quiet, an early warning of habitat stress. The demo plays a mixed dawn-chorus clip and watches the species list and diversity score assemble in real time.', 'Deja un telefono grabando en un jardin y la herramienta identifica especies de aves por sus cantos, construyendo un indice de diversidad continuo para ese lugar a lo largo de los dias. Avisa cuando una especie habitual se silencia, una alerta temprana de estres del habitat. La demo reproduce un coro del amanecer y ve armarse en tiempo real la lista de especies y el puntaje de diversidad.', 'environment', '12-24h', 12, 24, 'advanced', '["biodiversity"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Commute Comparator that Prices Trips in CO2, Time and Money', 'Comparador de viajes que tarifa en CO2, tiempo y dinero', 'Enter a start and end point and the tool lays out every realistic way to make the trip — drive, bus, bike, walk — side by side as carbon, minutes, and cost. The twist is a single slider that lets you weight what you care about and instantly re-rank the options. A focused build that makes the greener choice obvious for one daily decision.', 'Ingresa un origen y un destino y la herramienta despliega cada forma realista de hacer el viaje — auto, colectivo, bici, a pie — lado a lado en carbono, minutos y costo. El giro es un unico deslizador que te deja ponderar lo que te importa y reordenar las opciones al instante. Una construccion enfocada que vuelve obvia la opcion mas verde para una decision diaria.', 'environment', '6-12h', 6, 12, 'beginner', '["transport","climate-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Fridge-Photo Planner that Cooks Down Food About to Spoil', 'Planificador de heladera que cocina lo que esta por vencerse', 'Take one photo of your open fridge and the app spots what''s there and roughly how ripe it is, then proposes meals that use the items closest to spoiling first. It orders a three-day plan around rescuing food before you''d otherwise toss it. The demo shows a messy fridge becoming a prioritized cook-this-first list in seconds.', 'Sacale una foto a tu heladera abierta y la app detecta que hay y que tan maduro esta, proponiendo comidas que usen primero lo mas cercano a vencerse. Arma un plan de tres dias en torno a rescatar alimentos antes de que los tires. La demo muestra una heladera desordenada convirtiendose en una lista de cocinar-esto-primero en segundos.', 'environment', '6-12h', 6, 12, 'intermediate', '["waste","agriculture"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Rooftop Solar Estimator from a Single Map Pin', 'Estimador de solar en techo desde un pin en el mapa', 'Drop a pin on any rooftop and the tool estimates how many panels fit, the yearly generation given local sun and tilt, and the payback period at current tariffs. It accounts for nearby shading from taller buildings using the map geometry. The demo lets a judge pin their own roof and instantly see a sized, costed solar proposal.', 'Pone un pin sobre cualquier techo y la herramienta estima cuantos paneles entran, la generacion anual segun el sol y la inclinacion locales, y el periodo de repago a las tarifas actuales. Considera la sombra de edificios mas altos cercanos usando la geometria del mapa. La demo permite a un juez marcar su propio techo y ver al instante una propuesta solar dimensionada y costeada.', 'environment', '12-24h', 12, 24, 'intermediate', '["energy","climate-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Smart-Plug Coach that Shifts Devices to Cleaner Grid Hours', 'Coach de enchufes que mueve consumos a horas de red mas limpia', 'Connect a smart plug and the tool reads your grid''s live carbon intensity, then schedules flexible loads like the dishwasher or EV charger for the cleanest, cheapest hours. It shows the grams of CO2 and pesos saved versus running them now. A practical build whose demo runs a fake appliance and slides its start time onto a greener window.', 'Conecta un enchufe inteligente y la herramienta lee la intensidad de carbono en vivo de tu red, programando cargas flexibles como el lavavajillas o el cargador del auto en las horas mas limpias y baratas. Muestra los gramos de CO2 y los pesos ahorrados frente a usarlos ahora. Una construccion practica cuya demo corre un electrodomestico ficticio y desliza su arranque a una ventana mas verde.', 'environment', '12-24h', 12, 24, 'advanced', '["energy"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Leak Detective that Spots Water Waste from Meter Readings', 'Detective de fugas que detecta desperdicio de agua del medidor', 'Feed in a stream of home water-meter readings and the tool learns your normal pattern, then flags the tell-tale constant trickle of a hidden leak at 3am when nobody''s awake. It estimates the liters and money bleeding away per day. The demo replays a week of readings and watches the alert fire the moment a phantom flow appears.', 'Carga un flujo de lecturas del medidor de agua del hogar y la herramienta aprende tu patron normal, luego marca el goteo constante revelador de una fuga oculta a las 3am cuando nadie esta despierto. Estima los litros y el dinero que se pierden por dia. La demo reproduce una semana de lecturas y ve dispararse la alerta en el momento en que aparece un flujo fantasma.', 'environment', '6-12h', 6, 12, 'intermediate', '["water"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Crowd Air-Quality Wall from Cheap Sensor Submissions', 'Muro de calidad del aire colectivo con sensores baratos', 'Anyone with a low-cost particulate sensor submits readings and the tool stitches them into a live neighborhood air map that fills the gaps official stations miss. It calibrates noisy hobby sensors against the nearest reference station so the map stays honest. The demo drops a few simulated sensors onto a street and watches a smog plume take shape block by block.', 'Cualquiera con un sensor de particulas economico envia lecturas y la herramienta las une en un mapa de aire barrial en vivo que cubre los huecos que las estaciones oficiales no ven. Calibra los sensores caseros ruidosos contra la estacion de referencia mas cercana para que el mapa siga siendo honesto. La demo coloca sensores simulados en una calle y ve tomar forma una nube de smog cuadra por cuadra.', 'environment', '24-48h', 24, 48, 'advanced', '["air-quality","climate-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Asthma-Safe Route Planner that Routes Around Bad Air', 'Planificador de rutas que esquiva el aire contaminado', 'Enter where you''re walking or cycling and the planner picks the path with the least pollution exposure, not just the shortest distance, using live air-quality data. It''s built for people with asthma who feel the difference a few streets make. The demo compares the fastest route against the cleanest one side by side, with the exposure saved made plain.', 'Ingresa a donde caminas o pedaleas y el planificador elige el camino con menor exposicion a la contaminacion, no solo el mas corto, usando datos de calidad del aire en vivo. Esta pensado para personas con asma que sienten la diferencia de unas pocas calles. La demo compara la ruta mas rapida contra la mas limpia lado a lado, dejando clara la exposicion evitada.', 'environment', '6-12h', 6, 12, 'intermediate', '["air-quality","transport"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Barcode Greenwash Checker that Grades Product Eco-Claims', 'Verificador de greenwashing que califica afirmaciones eco', 'Scan a product barcode and the tool pulls its packaging eco-claims, then grades each one as substantiated, vague, or likely greenwashing against known certification standards. It explains the verdict so shoppers learn to read the labels themselves. A sharp build whose demo turns a glossy ''all-natural'' bottle into a transparent, evidence-backed score.', 'Escanea el codigo de barras de un producto y la herramienta extrae sus afirmaciones ecologicas de empaque, calificando cada una como respaldada, vaga o probable greenwashing frente a estandares de certificacion conocidos. Explica el veredicto para que el comprador aprenda a leer las etiquetas por si mismo. Una construccion aguda cuya demo convierte una botella ''100% natural'' en un puntaje transparente y respaldado por evidencia.', 'environment', '6-12h', 6, 12, 'intermediate', '["waste","climate-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Tree-Canopy Gap Finder for Where Shade Is Missing', 'Buscador de huecos de copa arborea donde falta sombra', 'Analyze aerial imagery for a district and the tool maps how much tree canopy each block has, then ranks the shadeless streets where pedestrians bake in summer. It estimates how many people would benefit from filling each gap so cities can prioritize. The demo lets a judge draw a boundary and instantly see the canopy haves and have-nots.', 'Analiza imagenes aereas de un distrito y la herramienta mapea cuanta copa arborea tiene cada cuadra, clasificando las calles sin sombra donde los peatones se asan en verano. Estima cuanta gente se beneficiaria al llenar cada hueco para que las ciudades prioricen. La demo permite a un juez dibujar un limite y ver al instante quienes tienen y quienes no tienen sombra.', 'environment', '12-24h', 12, 24, 'intermediate', '["biodiversity","climate-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Compost Coach that Diagnoses a Pile from One Photo', 'Coach de compost que diagnostica la pila con una foto', 'Photograph your compost pile and the tool reads visual cues — too wet, too dry, not enough browns — and gives one concrete fix to get it cooking again. It tracks the pile over weeks so beginners see the feedback loop instead of giving up. A friendly single-feature build whose demo turns a slimy failing heap into a clear next step.', 'Fotografia tu pila de compost y la herramienta lee pistas visuales — demasiado humeda, demasiado seca, faltan secos — y da un arreglo concreto para que vuelva a activarse. Sigue la pila durante semanas para que los principiantes vean el ciclo de retroalimentacion en vez de rendirse. Una construccion amigable de una sola funcion cuya demo convierte un monton viscoso y fallido en un proximo paso claro.', 'environment', '3-6h', 3, 6, 'beginner', '["waste","agriculture"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Flood-Risk Storyteller that Shows Your Street Under Water', 'Narrador de riesgo de inundacion que muestra tu calle bajo agua', 'Type an address and the tool overlays projected flood levels for different storm scenarios directly onto a map of that street, with a slider for sea-level-rise years. It pairs the visual with what it would mean for that specific home — basement, ground floor, escape routes. The demo makes an abstract climate stat suddenly personal and local.', 'Escribe una direccion y la herramienta superpone los niveles de inundacion proyectados para distintos escenarios de tormenta directamente sobre un mapa de esa calle, con un deslizador de anos de aumento del nivel del mar. Combina lo visual con lo que significaria para esa vivienda especifica — sotano, planta baja, rutas de escape. La demo vuelve de golpe personal y local una estadistica climatica abstracta.', 'environment', '12-24h', 12, 24, 'advanced', '["climate-data","water"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Repair-or-Toss Advisor that Scores Fixing an Appliance', 'Asesor de reparar o tirar que puntua arreglar un aparato', 'Describe a broken appliance and the tool weighs repair cost, expected extra lifespan, and the embodied carbon of a replacement to recommend fixing or replacing. It surfaces a nearby repair option or the spare part if fixing wins. A focused build whose demo takes a dying washing machine and gives a clear, carbon-aware verdict in one screen.', 'Describe un electrodomestico roto y la herramienta sopesa el costo de reparacion, la vida util extra esperada y el carbono incorporado de un reemplazo para recomendar arreglar o reemplazar. Muestra una opcion de reparacion cercana o el repuesto si conviene arreglar. Una construccion enfocada cuya demo toma un lavarropas moribundo y da un veredicto claro y consciente del carbono en una pantalla.', 'environment', '3-6h', 3, 6, 'beginner', '["waste"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Irrigation Planner that Waters Crops from the Forecast', 'Planificador de riego que riega segun el pronostico', 'Enter your crop and soil type and the planner builds a watering schedule that skips irrigation before forecast rain and doubles down during heat spikes. It estimates the liters saved versus a fixed timer, the way most people water now. The demo runs a season of real weather and shows the water saved climbing as the plan dodges rainy days.', 'Ingresa tu cultivo y tipo de suelo y el planificador arma un cronograma de riego que omite el agua antes de la lluvia pronosticada y refuerza durante las olas de calor. Estima los litros ahorrados frente a un temporizador fijo, como riega la mayoria hoy. La demo corre una temporada de clima real y muestra subir el agua ahorrada a medida que el plan esquiva los dias de lluvia.', 'environment', '6-12h', 6, 12, 'intermediate', '["agriculture","water"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Citizen Pollinator Census from Phone-Snapped Insects', 'Censo ciudadano de polinizadores con insectos fotografiados', 'Volunteers photograph bees and butterflies on flowers and the tool identifies the species and the plant, building a live map of pollinator activity across a region. It flags areas where pollinator visits are thinning, a cue for habitat planting. The demo accepts a handful of garden photos and assembles a pollinator-health snapshot for that patch.', 'Voluntarios fotografian abejas y mariposas sobre flores y la herramienta identifica la especie y la planta, construyendo un mapa en vivo de actividad polinizadora en una region. Marca zonas donde las visitas de polinizadores se reducen, una senal para plantar habitat. La demo acepta un punado de fotos de jardin y arma una instantanea de salud polinizadora para ese sector.', 'environment', '12-24h', 12, 24, 'intermediate', '["biodiversity","agriculture"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Plastic-Free Swap Finder for Items in Your Cart', 'Buscador de alternativas sin plastico para tu carrito', 'Paste an online shopping cart and the tool flags items with heavy single-use plastic, then suggests a concrete lower-waste alternative for each with the packaging difference shown. It tallies the plastic grams avoided across the whole order. A quick, satisfying build whose demo turns a plastic-heavy basket into a visibly lighter one.', 'Pega un carrito de compras online y la herramienta marca los productos con mucho plastico de un solo uso, sugiriendo para cada uno una alternativa concreta de menos residuos con la diferencia de empaque mostrada. Suma los gramos de plastico evitados en todo el pedido. Una construccion rapida y satisfactoria cuya demo convierte una canasta cargada de plastico en una visiblemente mas liviana.', 'environment', '3-6h', 3, 6, 'beginner', '["waste"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Deforestation Watcher that Pings on New Forest Loss', 'Vigilante de deforestacion que avisa de nueva perdida de bosque', 'Draw a polygon around a forest you care about and the tool compares recent satellite passes to detect fresh clearing, then sends an alert with before-and-after tiles. It''s aimed at local NGOs who can''t watch every hectare by hand. The demo draws a region, replays two satellite dates, and fires the moment a new clear-cut appears.', 'Dibuja un poligono alrededor de un bosque que te importa y la herramienta compara pasadas satelitales recientes para detectar talas nuevas, enviando una alerta con teselas de antes y despues. Apunta a ONGs locales que no pueden vigilar cada hectarea a mano. La demo dibuja una region, reproduce dos fechas satelitales y se dispara en el momento en que aparece un nuevo desmonte.', 'environment', '24-48h', 24, 48, 'advanced', '["biodiversity","climate-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Thrift-Outfit Builder that Scores Clothes by Reuse Impact', 'Armador de outfits de segunda mano por impacto de reuso', 'Upload your wardrobe and the tool suggests fresh outfits from what you already own, scoring each by the water and carbon a new purchase would have cost. It nudges you toward wearing more of your closet before buying. A playful build whose demo remixes a small wardrobe into a week of looks with the resources saved tallied alongside.', 'Sube tu guardarropa y la herramienta sugiere outfits nuevos con lo que ya tenes, puntuando cada uno por el agua y el carbono que habria costado una compra nueva. Te empuja a usar mas tu ropero antes de comprar. Una construccion divertida cuya demo remezcla un guardarropa pequeno en una semana de looks con los recursos ahorrados contabilizados al lado.', 'environment', '6-12h', 6, 12, 'beginner', '["waste","water"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Beach-Cleanup Logger that Turns Litter Photos into Data', 'Registrador de limpieza de playa que vuelve datos la basura', 'Snap photos of litter during a cleanup and the tool counts and classifies the trash, building an open dataset of what''s polluting each shoreline. It aggregates events into trends — more bottle caps here, more nets there — to guide policy. The demo turns a pile of cleanup photos into a labeled, chartable haul in front of the judges.', 'Saca fotos de la basura durante una limpieza y la herramienta cuenta y clasifica los residuos, construyendo un conjunto de datos abierto de que contamina cada costa. Agrega los eventos en tendencias — mas tapitas aca, mas redes alla — para guiar politicas. La demo convierte una pila de fotos de limpieza en un botin etiquetado y graficable frente a los jueces.', 'environment', '6-12h', 6, 12, 'intermediate', '["waste","water"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Carbon Budget Game where a City Hits Net Zero by 2040', 'Juego de presupuesto de carbono: una ciudad a cero neto en 2040', 'Players run a fictional city and pull policy levers — transit, retrofits, renewables — watching emissions and budgets respond on a live dashboard grounded in real abatement figures. The tension is hitting net zero without bankrupting or angering residents. A meaty build whose demo lets a judge take three turns and feel the trade-offs bite.', 'Los jugadores gestionan una ciudad ficticia y mueven palancas de politica — transporte, refacciones, renovables — viendo responder emisiones y presupuestos en un tablero en vivo basado en cifras reales de mitigacion. La tension es llegar a cero neto sin quebrar ni enojar a los habitantes. Una construccion robusta cuya demo deja a un juez jugar tres turnos y sentir morder las concesiones.', 'environment', '24-48h', 24, 48, 'intermediate', '["climate-data","energy"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Soil Moisture Probe Dashboard for a Single Raised Bed', 'Tablero de sonda de humedad de suelo para un cantero', 'Wire a cheap moisture probe into a microcontroller and the tool charts your garden bed''s soil over the day, then texts you only when it actually needs water. The whole point is replacing guesswork and overwatering with one honest signal. The demo dips the probe into dry then wet soil and watches the dashboard and the water-now alert react live.', 'Conecta una sonda de humedad economica a un microcontrolador y la herramienta grafica el suelo de tu cantero a lo largo del dia, avisandote por mensaje solo cuando de verdad necesita agua. El objetivo es reemplazar la adivinanza y el riego excesivo por una sola senal honesta. La demo mete la sonda en suelo seco y luego humedo y ve reaccionar en vivo el tablero y la alerta de regar.', 'environment', '12-24h', 12, 24, 'intermediate', '["agriculture","water"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Idle-Engine Spotter that Flags Wasted Fuel from Dashcam', 'Detector de motor al ralenti que marca combustible perdido', 'Feed dashcam or depot camera footage and the tool detects vehicles left idling, timing each event and estimating the fuel burned and CO2 emitted for nothing. It''s aimed at fleet managers who can''t eyeball every truck. The demo plays a clip of a yard, tags the idlers, and tallies the wasted liters as the timer runs.', 'Carga video de dashcam o de camara de deposito y la herramienta detecta vehiculos dejados al ralenti, cronometrando cada evento y estimando el combustible quemado y el CO2 emitido en vano. Apunta a gestores de flotas que no pueden vigilar cada camion. La demo reproduce un clip de un playon, etiqueta los que estan al ralenti y suma los litros desperdiciados mientras corre el cronometro.', 'environment', '12-24h', 12, 24, 'advanced', '["transport","air-quality"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Rainwater Harvest Sizer for Your Specific Roof and Rainfall', 'Dimensionador de cosecha de lluvia para tu techo y lluvia', 'Enter your roof area and location and the tool uses local rainfall records to size a rainwater tank that actually matches your supply and demand, not a generic number. It shows how many days of garden watering each tank size buys you across the dry season. A clean build whose demo turns a roof outline into a right-sized, costed tank recommendation.', 'Ingresa la superficie de tu techo y tu ubicacion y la herramienta usa registros locales de lluvia para dimensionar un tanque de agua de lluvia que de verdad coincida con tu oferta y demanda, no un numero generico. Muestra cuantos dias de riego de jardin te da cada tamano de tanque durante la temporada seca. Una construccion prolija cuya demo convierte el contorno de un techo en una recomendacion de tanque costeada y bien dimensionada.', 'environment', '3-6h', 3, 6, 'beginner', '["water"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Menu Footprint Badge that Ranks a Restaurant''s Dishes', 'Insignia de huella de menu que ordena los platos del local', 'Paste a restaurant menu and the tool estimates the carbon footprint of each dish from its likely ingredients, then adds a small badge ranking them from lightest to heaviest. It suggests one tweak per heavy dish that keeps the flavor but cuts the footprint. A fast build whose demo turns a plain menu into a climate-labeled one diners can actually read.', 'Pega el menu de un restaurante y la herramienta estima la huella de carbono de cada plato segun sus ingredientes probables, agregando una pequena insignia que los ordena del mas liviano al mas pesado. Sugiere un ajuste por plato pesado que conserva el sabor pero reduce la huella. Una construccion rapida cuya demo convierte un menu comun en uno con etiquetas climaticas que los comensales pueden leer.', 'environment', '3-6h', 3, 6, 'intermediate', '["climate-data","agriculture"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Bike-Lane Gap Mapper from Crowd Commute Traces', 'Mapeador de huecos de bicisenda con trazas de viajes colectivos', 'Cyclists share anonymized ride traces and the tool finds the busy stretches with no protected bike lane, ranking the gaps by how many riders brave them daily. It hands cities a ranked, evidence-backed wishlist instead of anecdotes. The demo loads sample traces over a city and lights up the most-pedaled unprotected corridors.', 'Los ciclistas comparten trazas anonimas de sus viajes y la herramienta encuentra los tramos transitados sin bicisenda protegida, ordenando los huecos por cuantos ciclistas los enfrentan a diario. Le entrega a las ciudades una lista priorizada y respaldada por evidencia en vez de anecdotas. La demo carga trazas de ejemplo sobre una ciudad y enciende los corredores mas pedaleados y desprotegidos.', 'environment', '6-12h', 6, 12, 'intermediate', '["transport"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Phenology Tracker that Watches a Tree Wake Up Each Spring', 'Rastreador de fenologia que observa despertar un arbol cada primavera', 'Adopt a tree and snap it weekly; the tool detects bud, leaf and bloom stages and logs the dates, building a multi-year record that reveals how the season is shifting earlier. Aggregated across users it becomes a grassroots climate signal. The demo feeds a sequence of tree photos and watches the phenology timeline and a warming trend emerge.', 'Adopta un arbol y fotografialo cada semana; la herramienta detecta etapas de brote, hoja y floracion y registra las fechas, construyendo un historial de varios anos que revela como la estacion se adelanta. Agregado entre usuarios se vuelve una senal climatica de base. La demo carga una secuencia de fotos del arbol y ve emerger la linea de tiempo fenologica y una tendencia de calentamiento.', 'environment', '12-24h', 12, 24, 'intermediate', '["biodiversity","climate-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Standby Power Sniffer that Names Your Vampire Devices', 'Rastreador de consumo en espera que delata aparatos vampiro', 'Plug a single energy monitor into the mains and the tool fingerprints the always-on draw of each device from its electrical signature, then ranks the worst standby offenders. It tells you which plugs to actually switch off at night to matter. A neat build whose demo toggles a couple of gadgets and watches the tool name and shame the vampire loads.', 'Enchufa un solo monitor de energia a la red y la herramienta identifica el consumo permanente de cada aparato por su firma electrica, clasificando los peores en modo espera. Te dice que enchufes apagar de noche para que realmente importe. Una construccion prolija cuya demo prende y apaga un par de aparatos y ve a la herramienta delatar las cargas vampiro.', 'environment', '24-48h', 24, 48, 'advanced', '["energy"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Drought-Tolerant Garden Designer for Your Local Climate', 'Disenador de jardin tolerante a sequia para tu clima local', 'Enter your location and sun exposure and the tool designs a garden bed using native, low-water plants suited to your climate, with a layout and a watering estimate. It shows the liters saved versus a typical thirsty lawn over a summer. A friendly build whose demo turns an empty plot into a planted, water-wise layout the judge can tweak.', 'Ingresa tu ubicacion y exposicion al sol y la herramienta disena un cantero con plantas nativas de bajo consumo de agua adecuadas a tu clima, con un diseno y una estimacion de riego. Muestra los litros ahorrados frente a un cesped sediento tipico durante un verano. Una construccion amigable cuya demo convierte un terreno vacio en un diseno plantado y eficiente en agua que el juez puede ajustar.', 'environment', '3-6h', 3, 6, 'beginner', '["water","biodiversity"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('One-Button Co-op Platformer over a Shared Link', 'Plataformas cooperativo de un botón por enlace compartido', 'A two-player platformer where each player controls only ONE action: one jumps, the other moves sideways. Levels are impossible to clear without talking, so the whole charm is the forced coordination. Join instantly by sharing a link, no install or accounts. A tight, hilarious build whose entire hook is the split control scheme.', 'Un plataformas para dos donde cada jugador controla solo UNA acción: uno salta, el otro se mueve de costado. Los niveles son imposibles sin hablar, así que el encanto está en la coordinación forzada. Te unís al instante compartiendo un enlace, sin instalar ni cuentas. Un proyecto ajustado y divertidísimo cuyo gancho es el control partido.', 'games-fun', '3-6h', 3, 6, 'intermediate', '["multiplayer","physics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Drawing Telephone Where an AI Judge Roasts Each Guess', 'Teléfono de dibujos donde una IA jueza se burla de cada respuesta', 'A party game in the Gartic Phone family: players alternate drawing and guessing down a chain, but after each round an AI judge narrates the chain out loud and roasts where it went off the rails. Everyone joins from their phone via a room code. The comedy comes from the AI commentary turning misfires into the highlight reel.', 'Un juego de fiesta al estilo Gartic Phone: los jugadores alternan dibujar y adivinar en cadena, pero al final de cada ronda una IA jueza narra la cadena en voz alta y se burla de dónde se descarriló. Todos entran desde el celular con un código de sala. La comedia surge de que el comentario de la IA convierte los errores en lo mejor de la partida.', 'games-fun', '6-12h', 6, 12, 'intermediate', '["party-games","multiplayer","ai-npc"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Rhythm Game That Builds Its Chart from Any Song You Drop In', 'Juego de ritmo que arma su mapa desde cualquier canción que sueltes', 'Drop in any audio file and the game analyzes its beats and energy to procedurally generate a playable note chart on the fly. Every song becomes a fresh level, and intensity ramps with the track''s loudness. The demo lets a judge bring their own song and immediately play it, which makes each run feel personal and unrepeatable.', 'Soltás cualquier archivo de audio y el juego analiza sus beats y energía para generar de forma procedural un mapa de notas jugable al instante. Cada canción se vuelve un nivel nuevo y la intensidad sube con el volumen del tema. La demo permite que un juez traiga su propia canción y la juegue al toque, lo que hace que cada partida sea personal e irrepetible.', 'games-fun', '6-12h', 6, 12, 'intermediate', '["music-game","procedural"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Typing Speed Duel Where Words Become Falling Hazards', 'Duelo de tipeo donde las palabras se vuelven obstáculos que caen', 'A head-to-head typing duel: each correct word you type drops a block of letters onto your opponent''s screen, Tetris-style, so fast accurate typing is also an attack. The faster you go, the more you bury them. Join a duel by sharing a link. A single sharp mechanic where typing skill and sabotage are the same action.', 'Un duelo de tipeo mano a mano: cada palabra que escribís bien suelta un bloque de letras en la pantalla del rival, al estilo Tetris, así que tipear rápido y preciso también es atacar. Cuanto más rápido vas, más lo enterrás. Te unís a un duelo compartiendo un enlace. Una mecánica afilada donde la habilidad de tipeo y el sabotaje son la misma acción.', 'games-fun', '3-6h', 3, 6, 'intermediate', '["multiplayer","retro"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Webcam Game Where Your Real Shadow Is the Controller', 'Juego con webcam donde tu sombra real es el control', 'Using only the webcam, the game tracks your body silhouette and projects it into the playfield so your real shadow swats falling objects or blocks enemies. No gamepad, no keyboard: you physically dodge and reach. The demo gets a judge out of their chair waving at the screen, which lands instantly with a crowd.', 'Usando solo la webcam, el juego detecta tu silueta y la proyecta en el campo de juego para que tu sombra real golpee objetos que caen o bloquee enemigos. Sin gamepad ni teclado: esquivás y estirás el cuerpo de verdad. La demo saca al juez de la silla a moverse frente a la pantalla, algo que pega al instante con público.', 'games-fun', '6-12h', 6, 12, 'advanced', '["ar-vr","physics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Trivia Night Where the AI Host Invents Questions About Your Group', 'Noche de trivia donde el anfitrión IA inventa preguntas sobre tu grupo', 'A party trivia game where each player drops in a few facts about themselves at the start, and an AI host weaves them into rounds of questions everyone answers from their phone. The fun is guessing which friend matches each clue. The host keeps score and ad-libs banter, turning a generic quiz into an inside-joke machine.', 'Un juego de trivia de fiesta donde cada jugador suelta al inicio unos datos sobre sí mismo y un anfitrión IA los entrelaza en rondas de preguntas que todos responden desde el celular. La gracia es adivinar qué amigo encaja con cada pista. El anfitrión lleva el puntaje e improvisa chistes, convirtiendo un quiz genérico en una máquina de chistes internos.', 'games-fun', '6-12h', 6, 12, 'intermediate', '["party-games","multiplayer","ai-npc"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Golf Game on a Course Generated from Any Map You Pick', 'Juego de golf en una cancha generada desde el mapa que elijas', 'Pick any spot on a real map and the game turns its streets, parks and rivers into a tiny mini-golf hole with physics-based putting. Buildings become walls, water becomes hazards. Each location plays differently, so your own neighborhood becomes a course. A demoable hook where geography drives level design with no hand-authoring.', 'Elegís cualquier punto en un mapa real y el juego convierte sus calles, plazas y ríos en un pequeño hoyo de minigolf con física de tiro. Los edificios son muros, el agua es obstáculo. Cada ubicación se juega distinto, así que tu propio barrio se vuelve cancha. Un gancho demostrable donde la geografía dirige el diseño de niveles sin diseñarlos a mano.', 'games-fun', '12-24h', 12, 24, 'intermediate', '["procedural","physics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Co-op Heist Where Two Phones Are Two Halves of One Vault', 'Atraco cooperativo donde dos celulares son dos mitades de una bóveda', 'An asymmetric co-op puzzle: one player sees the vault''s wiring, the other sees the keypad clues, and neither can solve it alone before the timer runs out. They must describe what they see to each other out loud. Two phones join the same room by code. The tension and frantic talking are the entire experience.', 'Un rompecabezas cooperativo asimétrico: un jugador ve el cableado de la bóveda, el otro ve las pistas del teclado, y ninguno puede resolverlo solo antes de que se acabe el tiempo. Tienen que describirse en voz alta lo que ven. Dos celulares entran a la misma sala por código. La tensión y el hablar a las apuradas son toda la experiencia.', 'games-fun', '12-24h', 12, 24, 'intermediate', '["multiplayer","party-games"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Idle Garden That Grows From the Songs You Listen To', 'Jardín idle que crece según las canciones que escuchás', 'A calm idle game where a procedural garden sprouts plants whose shapes and colors are seeded by the tempo and mood of music you play. Mellow tracks grow soft ferns, hard beats grow spiky blooms. It runs in the background and rewards revisiting. A relaxing, screenshot-friendly build with an unexpected music-to-flora mapping.', 'Un juego idle tranquilo donde un jardín procedural brota plantas cuyas formas y colores se generan según el tempo y el ánimo de la música que ponés. Los temas suaves dan helechos blandos, los beats fuertes dan flores con púas. Corre en segundo plano y premia volver. Un proyecto relajante y fotogénico con un mapeo inesperado de música a flora.', 'games-fun', '6-12h', 6, 12, 'intermediate', '["music-game","procedural"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Couch Fighting Game Where Both Players Share One Keyboard', 'Juego de pelea de sillón donde ambos comparten un teclado', 'A retro-styled 2D brawler built for two people elbowing over a single keyboard, with the left and right hand zones split between fighters. The cramped controls are the joke and the challenge. No netcode needed, just one laptop and a friend. A focused, instantly playable build perfect for a short, chaotic sprint.', 'Un juego de pelea 2D de estilo retro pensado para dos personas peleándose por un solo teclado, con las zonas de mano izquierda y derecha repartidas entre los luchadores. Los controles apretados son el chiste y el desafío. No hace falta netcode, solo una laptop y un amigo. Un proyecto enfocado y jugable al instante, ideal para un sprint corto y caótico.', 'games-fun', '1-3h', 1, 3, 'beginner', '["retro","multiplayer"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('AR Treasure Hunt That Hides Clues on Real Furniture', 'Búsqueda del tesoro en RA que esconde pistas en muebles reales', 'Point your phone around a room and the game anchors virtual clue tokens onto real surfaces: a table, a shelf, a doorframe. Players physically walk and scan to find the next token in sequence. The host writes the clue chain in seconds. A demoable AR build whose magic is objects appearing stuck to the actual room.', 'Apuntás el celular por la habitación y el juego ancla fichas de pistas virtuales en superficies reales: una mesa, un estante, el marco de una puerta. Los jugadores caminan y escanean para encontrar la siguiente ficha en orden. El anfitrión arma la cadena de pistas en segundos. Un proyecto de RA demostrable cuya magia es ver objetos pegados a la sala real.', 'games-fun', '12-24h', 12, 24, 'advanced', '["ar-vr","multiplayer"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Word Association Race Where the AI Plays as a Rival', 'Carrera de asociación de palabras donde la IA juega como rival', 'A fast word game: you and an AI rival take turns chaining associated words against a timer, and you score by being faster and weirder than it. The AI taunts, stalls, and occasionally plays a brilliant word to keep you on edge. A single-screen build where the personality of the AI opponent carries the whole demo.', 'Un juego de palabras veloz: vos y una IA rival se turnan encadenando palabras asociadas contra el reloj, y puntuás por ser más rápido y más raro que ella. La IA te provoca, demora y de vez en cuando juega una palabra brillante para mantenerte en vilo. Un proyecto de una sola pantalla donde la personalidad del rival IA sostiene toda la demo.', 'games-fun', '3-6h', 3, 6, 'intermediate', '["ai-npc","party-games"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Physics Sandbox Where You Doodle a Vehicle and It Drives', 'Caja de arena física donde dibujás un vehículo y arranca', 'Draw any shape with wheels on a canvas and the game instantly turns your doodle into a physics-driven vehicle that must cross a bumpy course. Wonky designs flip and flail hilariously. Players iterate by redrawing in seconds. A tight single-feature build where the joy is watching your terrible sketch try to climb a hill.', 'Dibujás cualquier forma con ruedas en un lienzo y el juego convierte al instante tu garabato en un vehículo con física que debe cruzar un terreno irregular. Los diseños torpes vuelcan y se sacuden de forma graciosa. Los jugadores iteran redibujando en segundos. Un proyecto de una sola función donde la gracia es ver tu boceto horrible intentar subir una colina.', 'games-fun', '3-6h', 3, 6, 'intermediate', '["physics","procedural"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Reaction Tester Disguised as a Cowboy Quick-Draw Duel', 'Medidor de reflejos disfrazado de duelo de pistoleros', 'A one-screen quick-draw duel: wait for the bell, then tap as fast as you can to outshoot your opponent, with a false start costing you the round. Pass-and-play on one device or duel over a shared link. A pure reaction-time mechanic dressed up with western flair, perfect for a one-hour build and instant laughs.', 'Un duelo de pistoleros en una pantalla: esperás la campana y tocás lo más rápido posible para disparar antes que el rival, donde adelantarse cuesta la ronda. Pasar y jugar en un dispositivo o duelo por enlace compartido. Una mecánica pura de tiempo de reacción vestida con onda western, ideal para un proyecto de una hora y risas inmediatas.', 'games-fun', '1-3h', 1, 3, 'beginner', '["retro","party-games"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Dungeon Crawler Where the AI Dungeon Master Narrates Live', 'Mazmorra donde el director de juego IA narra en vivo', 'A roguelike where rooms and loot are procedurally generated, but an AI dungeon master describes every room, reacts to your choices, and invents encounters that fit the run. The map is mechanical; the storytelling is alive. A fuller flow that earns the longer build, with a demo where a judge wanders and the AI improvises around them.', 'Un roguelike donde las salas y el botín se generan de forma procedural, pero un director de juego IA describe cada sala, reacciona a tus decisiones e inventa encuentros que encajan con la partida. El mapa es mecánico; la narración está viva. Un flujo más completo que justifica el proyecto largo, con una demo donde el juez explora y la IA improvisa a su alrededor.', 'games-fun', '24-48h', 24, 48, 'advanced', '["ai-npc","procedural"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Multiplayer Drawing Game Where You Guess by Sound, Not Sight', 'Juego de dibujo multijugador donde adivinás por sonido, no por vista', 'A twist on draw-and-guess: instead of drawing, the active player describes a secret word using only nonsense sounds and noises into the mic, and everyone races to guess. The host picks words, the room joins by code. A short, ridiculous build whose whole hook is communication stripped down to vocal sound effects.', 'Una vuelta de tuerca al dibujar y adivinar: en vez de dibujar, el jugador activo describe una palabra secreta usando solo sonidos y ruidos sin sentido por el micrófono, y todos corren a adivinar. El anfitrión elige las palabras, la sala entra por código. Un proyecto corto y ridículo cuyo gancho es la comunicación reducida a efectos de sonido vocales.', 'games-fun', '3-6h', 3, 6, 'intermediate', '["party-games","multiplayer","music-game"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Endless Runner Whose Level Is Built From Your Own Photo', 'Corredor infinito cuyo nivel se construye con tu propia foto', 'Snap or upload a photo and the game traces its edges and brightness into a side-scrolling runner course: skylines become jumps, shadows become pits. Every picture is a unique level. A demoable single-feature build where a judge photographs the room and immediately runs through it as a playable obstacle course.', 'Sacás o subís una foto y el juego traza sus bordes y brillo en un recorrido de corredor lateral: los horizontes se vuelven saltos, las sombras se vuelven pozos. Cada imagen es un nivel único. Un proyecto de una sola función demostrable donde el juez fotografía la sala y al instante corre por ella como pista de obstáculos jugable.', 'games-fun', '6-12h', 6, 12, 'intermediate', '["procedural","retro"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Tower Defense Where Enemies Spawn From Your Live Chat', 'Defensa de torres donde los enemigos salen de tu chat en vivo', 'A stream-friendly tower defense where viewers type commands in chat to spawn or buff enemies against the streamer, who frantically places towers. The audience becomes the boss. Spectators join through a link with no account. A lively build whose hook is turning a passive chat into the live antagonist of the match.', 'Una defensa de torres pensada para streams donde la audiencia escribe comandos en el chat para invocar o potenciar enemigos contra el streamer, que coloca torres a las apuradas. El público se vuelve el jefe. Los espectadores entran por un enlace sin cuenta. Un proyecto vivaz cuyo gancho es convertir un chat pasivo en el antagonista en vivo de la partida.', 'games-fun', '12-24h', 12, 24, 'intermediate', '["multiplayer","party-games"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Pixel Pet That Reacts to the Weather Outside Your Window', 'Mascota pixelada que reacciona al clima fuera de tu ventana', 'A tiny retro virtual pet whose mood and animations shift with your real local weather: it shivers in cold, naps in heat, dances in rain. It lives in a browser tab and surprises you across the day. A small, charming build where the hook is the pet quietly mirroring the actual sky outside.', 'Una pequeña mascota virtual retro cuyo ánimo y animaciones cambian con el clima real de tu zona: tirita con frío, duerme la siesta con calor, baila con lluvia. Vive en una pestaña del navegador y te sorprende a lo largo del día. Un proyecto chico y encantador cuyo gancho es la mascota reflejando en silencio el cielo de afuera.', 'games-fun', '3-6h', 3, 6, 'beginner', '["retro","procedural"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Karaoke Battle That Scores Your Pitch in Real Time', 'Batalla de karaoke que puntúa tu afinación en tiempo real', 'A two-player karaoke duel: pick a melody and the game listens through the mic, scoring how close each singer''s pitch tracks the target line live. A meter swings between the two as you sing. Join over a shared link. A demoable music build where the comedy and competition come from watching real voices fight for the lead.', 'Un duelo de karaoke para dos: elegís una melodía y el juego escucha por el micrófono, puntuando en vivo qué tan cerca sigue cada cantante la línea objetivo. Un medidor oscila entre los dos mientras cantan. Te unís por un enlace compartido. Un proyecto musical demostrable donde la comedia y la competencia surgen de ver voces reales pelear por la delantera.', 'games-fun', '6-12h', 6, 12, 'advanced', '["music-game","multiplayer"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Maze Game You Solve by Tilting Your Phone Like a Marble', 'Laberinto que resolvés inclinando el celular como una canica', 'A physics marble maze where tilting your phone rolls the ball through a procedurally generated labyrinth, dodging holes and racing the clock. Each refresh builds a brand-new maze, so it never repeats. A clean single-mechanic build using the device''s motion sensors, satisfying to demo with one quick tilt and a near-miss.', 'Un laberinto de canica con física donde inclinar el celular hace rodar la bola por un laberinto generado de forma procedural, esquivando agujeros y corriendo contra el reloj. Cada recarga arma un laberinto nuevo, así que nunca se repite. Un proyecto de una sola mecánica que usa los sensores de movimiento, satisfactorio de mostrar con una inclinación y un susto.', 'games-fun', '3-6h', 3, 6, 'intermediate', '["physics","procedural"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Bluffing Card Game With an AI Opponent That Reads Your Tells', 'Juego de cartas de farol con una IA que lee tus señales', 'A bluffing card game against an AI that adapts to how you bet and bluff, calling you out when your pattern gets predictable and taunting when it catches a lie. The hook is an opponent that feels like it''s reading you across a session. A focused build where the AI''s behavior, not the rules, is the star.', 'Un juego de cartas de farol contra una IA que se adapta a cómo apostás y mentís, delatándote cuando tu patrón se vuelve predecible y provocándote cuando atrapa una mentira. El gancho es un rival que parece leerte a lo largo de la partida. Un proyecto enfocado donde el comportamiento de la IA, no las reglas, es la estrella.', 'games-fun', '6-12h', 6, 12, 'intermediate', '["ai-npc","party-games"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Local Multiplayer Snake Where Everyone Shares One Arena', 'Snake multijugador local donde todos comparten una arena', 'A retro Snake reborn for a party: up to four players join one arena from their phones as controllers while the action shows on a shared big screen. Last snake slithering wins, and crashing into a friend is the whole drama. Quick to join by code. A nostalgic mechanic made social with phone-as-gamepad.', 'Un Snake retro renacido para la fiesta: hasta cuatro jugadores entran a una arena desde sus celulares como controles mientras la acción se ve en una pantalla grande compartida. Gana la última serpiente viva, y chocar contra un amigo es todo el drama. Rápido de unirse por código. Una mecánica nostálgica vuelta social con el celular como gamepad.', 'games-fun', '6-12h', 6, 12, 'intermediate', '["retro","multiplayer","party-games"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Escape Room in VR Built Procedurally So It Never Repeats', 'Sala de escape en RV generada para que nunca se repita', 'A single-player VR escape room where the puzzle layout, codes and hidden objects are procedurally generated each session, so even the builder can get stuck. Players physically reach, pull and inspect to escape before the timer ends. A fuller build that justifies the long bucket, with a strong wow-factor demo for anyone in the headset.', 'Una sala de escape en RV para un jugador donde la disposición de los acertijos, los códigos y los objetos ocultos se generan de forma procedural cada sesión, así que hasta quien la construyó puede trabarse. Los jugadores estiran, tiran e inspeccionan físicamente para escapar antes de que se acabe el tiempo. Un proyecto completo que justifica el bucket largo, con una demo de gran impacto.', 'games-fun', '24-48h', 24, 48, 'advanced', '["ar-vr","procedural"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Beat-Matching Game Where Two Players Drum on Their Phones', 'Juego de ritmo donde dos jugadores tamborilean en sus celulares', 'A co-op rhythm game where two players tap interlocking patterns on their own phones to build one combined beat, and the song only sounds right if both stay in sync. Drifting apart muddies the music as instant feedback. Join by link. A short, lively build whose hook is hearing your teamwork in the groove itself.', 'Un juego de ritmo cooperativo donde dos jugadores tocan patrones entrelazados en sus propios celulares para construir un beat combinado, y la canción solo suena bien si ambos van sincronizados. Desfasarse ensucia la música como feedback inmediato. Te unís por enlace. Un proyecto corto y vivaz cuyo gancho es escuchar tu trabajo en equipo en el groove mismo.', 'games-fun', '6-12h', 6, 12, 'intermediate', '["music-game","multiplayer"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Guess-the-Lie Party Game Where AI Writes the Fake Answers', 'Juego de fiesta de adivinar la mentira con respuestas falsas de IA', 'A bluff-and-vote party game: players answer an obscure question, an AI slips in convincing fake answers, and everyone votes on which is real while trying to fool the room with their own. The AI fakes raise the difficulty and the laughs. Join by room code from any phone. The blend of human and AI lies is the twist.', 'Un juego de fiesta de farol y voto: los jugadores responden una pregunta rara, una IA cuela respuestas falsas convincentes, y todos votan cuál es la verdadera mientras intentan engañar a la sala con la propia. Las falsas de la IA suben la dificultad y las risas. Se une por código desde cualquier celular. La mezcla de mentiras humanas y de IA es el giro.', 'games-fun', '12-24h', 12, 24, 'intermediate', '["party-games","multiplayer","ai-npc"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Gravity Painter Where You Sketch Planets and Watch Orbits', 'Pintor de gravedad donde dibujás planetas y mirás órbitas', 'A toy where you place planets and stars with a click and the game simulates their gravity in real time, letting you fling objects into stable orbits or beautiful collisions. There is no goal but discovery, and chaotic systems are the reward. A short, mesmerizing build that demos itself the moment two bodies start dancing.', 'Un juguete donde colocás planetas y estrellas con un clic y el juego simula su gravedad en tiempo real, dejándote lanzar objetos a órbitas estables o a choques hermosos. No hay meta más que descubrir, y los sistemas caóticos son la recompensa. Un proyecto corto e hipnótico que se demuestra solo apenas dos cuerpos empiezan a bailar.', 'games-fun', '3-6h', 3, 6, 'intermediate', '["physics","procedural"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Hot-Potato Quiz Where the Phone Is Passed Around a Circle', 'Quiz de papa caliente donde el celular gira por la ronda', 'A single-phone party game: a question pops up, you must answer or act it out fast, then physically pass the phone before a hidden timer buzzes, and whoever holds it when it buzzes loses the round. No setup beyond one device. A tiny, frantic build that turns one phone and a hidden countdown into a whole party.', 'Un juego de fiesta de un solo celular: aparece una pregunta, tenés que responder o actuarla rápido y luego pasar el celular antes de que suene un temporizador oculto, y quien lo tenga cuando suena pierde la ronda. Sin preparación más allá de un dispositivo. Un proyecto chiquito y frenético que convierte un celular y una cuenta regresiva oculta en toda una fiesta.', 'games-fun', '1-3h', 1, 3, 'beginner', '["party-games"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Co-op Roguelite Where Friends Drop In as the Monsters', 'Roguelite cooperativo donde tus amigos entran como los monstruos', 'An asymmetric roguelite with procedural dungeons: one player crawls for loot while friends join via link to possess the monsters and lay ambushes against them. The hero''s run is mechanical; the menace is human and unpredictable. A fuller build for a long sprint, with a demo where the room cheers as a friend pounces.', 'Un roguelite asimétrico con mazmorras procedurales: un jugador avanza por el botín mientras sus amigos entran por enlace para poseer a los monstruos y tenderle emboscadas. La partida del héroe es mecánica; la amenaza es humana e impredecible. Un proyecto completo para un sprint largo, con una demo donde la sala festeja cuando un amigo salta al ataque.', 'games-fun', '24-48h', 24, 48, 'advanced', '["multiplayer","procedural"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Clicker Game Where Your Cursor Speed Powers a Tiny Factory', 'Clicker donde la velocidad de tu cursor mueve una fábrica diminuta', 'An incremental game where instead of just clicking, the raw speed and travel of your mouse cursor turns gears in a tiny factory, so wild scribbling builds production fast. Upgrades change how motion maps to output. A short, oddly satisfying build whose hook is rewarding frantic cursor movement instead of dull repeated taps.', 'Un juego incremental donde, en vez de solo clickear, la velocidad y el recorrido del cursor mueven engranajes en una fábrica diminuta, así que mover el mouse como loco acelera la producción. Las mejoras cambian cómo el movimiento se traduce en producción. Un proyecto corto y curiosamente satisfactorio cuyo gancho es premiar el movimiento frenético del cursor en vez de toques repetidos.', 'games-fun', '1-3h', 1, 3, 'beginner', '["physics","retro"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Breathing Pacer that Reads Your Voice Tremor', 'Marcapasos de respiración que lee el temblor de tu voz', 'Speak a sentence into the mic and the tool estimates your stress level from voice jitter and pace, then launches a guided breathing animation tuned to calm you down. You re-record after the session and watch the tremor score drop. A sharp single-screen build perfect for a short sprint, with the detection heuristic left open.', 'Habla una frase al micrófono y la herramienta estima tu nivel de estrés a partir del temblor y el ritmo de la voz, y luego lanza una animación de respiración guiada para calmarte. Vuelves a grabar al terminar y ves bajar el puntaje de temblor. Una construcción nítida de una sola pantalla, ideal para un sprint corto, con la heurística de detección abierta.', 'health-medtech', '1-3h', 1, 3, 'beginner', '["mental-health","wearable-health"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Pill Bottle Label Decoder for Low-Vision Patients', 'Decodificador de etiquetas de medicamentos para baja visión', 'Point your camera at a prescription bottle and the app reads the drug name, dose, and timing aloud in large high-contrast text. It flags the next dose window so an elderly user never double-doses. A tight accessibility build for a few hours, leaving the OCR and text-to-speech pipeline open to the team.', 'Apunta la cámara a un frasco de receta y la app lee en voz alta el nombre del fármaco, la dosis y los horarios en texto grande de alto contraste. Marca la próxima ventana de toma para que una persona mayor nunca se duplique la dosis. Una construcción de accesibilidad compacta para unas pocas horas, dejando abierta la canalización de OCR y voz.', 'health-medtech', '1-3h', 1, 3, 'beginner', '["accessibility","med-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Hydration Nudge that Learns Your Sweat Rate', 'Recordatorio de hidratación que aprende tu tasa de sudor', 'Log your weight before and after a workout and the tool computes how much fluid you actually lost, then sets personalized drink reminders for your next session of the same length. The demo turns a single weigh-in into a concrete ounces-per-hour target. A small, demoable feature that fits a quick sprint.', 'Registra tu peso antes y después de entrenar y la herramienta calcula cuánto líquido perdiste, y luego programa recordatorios personalizados de bebida para tu próxima sesión de igual duración. La demo convierte un solo pesaje en un objetivo concreto de mililitros por hora. Una función pequeña y demostrable que cabe en un sprint rápido.', 'health-medtech', '1-3h', 1, 3, 'beginner', '["fitness","nutrition"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Symptom-to-Question Translator for Doctor Visits', 'Traductor de síntomas a preguntas para la consulta médica', 'Describe how you feel in plain words and the tool turns it into a tidy list of specific questions and details to bring to your appointment, so nothing gets forgotten in the room. It groups symptoms by timeline and severity. A focused single-screen build that makes a stressful visit feel prepared, with the wording logic open.', 'Describe cómo te sientes con tus propias palabras y la herramienta lo convierte en una lista ordenada de preguntas y detalles específicos para llevar a la consulta, para que nada se olvide. Agrupa los síntomas por cronología y gravedad. Una construcción enfocada de una sola pantalla que hace que una visita estresante se sienta preparada, con la lógica de redacción abierta.', 'health-medtech', '1-3h', 1, 3, 'beginner', '["telemedicine","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Posture Buzzer Using Your Laptop Webcam', 'Alerta de postura usando la webcam del portátil', 'The webcam watches your neck and shoulder line while you work and gently buzzes a sound when you slump past a threshold you set by sitting up straight once. It logs how long you held good posture each hour. A tight, visible build for a short sprint, leaving the pose detection approach open.', 'La webcam observa la línea de tu cuello y hombros mientras trabajas y emite un sonido suave cuando te encorvas más allá del umbral que fijas sentándote derecho una vez. Registra cuánto tiempo mantuviste buena postura cada hora. Una construcción compacta y visible para un sprint corto, con el método de detección de postura abierto.', 'health-medtech', '1-3h', 1, 3, 'beginner', '["fitness","wearable-health"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Mood Check-In that Maps Feelings to a Color Wheel', 'Registro de ánimo que mapea emociones a una rueda de color', 'Tap where you are on a color-and-emotion wheel each day and the app builds a calm visual ribbon of your week, surfacing patterns like which days dip. It nudges you with one tiny suggestion when a low streak appears. A demoable, single-feature build that fits a quick session, with the pattern logic open.', 'Toca dónde estás en una rueda de color y emoción cada día y la app arma una cinta visual serena de tu semana, revelando patrones como qué días bajan. Te sugiere una pequeña acción cuando aparece una racha baja. Una construcción demostrable de una sola función que cabe en una sesión rápida, con la lógica de patrones abierta.', 'health-medtech', '1-3h', 1, 3, 'beginner', '["mental-health"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Skin Mole Tracker that Compares Photos Over Time', 'Seguidor de lunares que compara fotos a lo largo del tiempo', 'Snap the same mole each month and the app aligns the photos, overlays them, and highlights changes in size, border, or color so you know when to see a dermatologist. It builds a side-by-side timeline per spot. A focused half-day build with a clear visual demo, leaving alignment and change-scoring open.', 'Fotografía el mismo lunar cada mes y la app alinea las fotos, las superpone y resalta cambios de tamaño, borde o color para saber cuándo ver a un dermatólogo. Construye una línea de tiempo lado a lado por cada mancha. Una construcción enfocada de medio día con una demo visual clara, dejando abierto el alineado y la medición de cambios.', 'health-medtech', '3-6h', 3, 6, 'intermediate', '["diagnostics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Cough Sound Classifier that Flags Wet vs Dry', 'Clasificador de tos que distingue húmeda de seca', 'Record a few coughs and the tool labels each as wet, dry, or wheezy and tracks the mix across days so a patient sees if a cold is turning chesty. The demo plays a clip and lights up the prediction live. A half-day audio build with a satisfying visual, leaving the feature extraction open.', 'Graba unas toses y la herramienta etiqueta cada una como húmeda, seca o con sibilancia y rastrea la mezcla por días para que el paciente vea si un resfriado se vuelve de pecho. La demo reproduce un clip y enciende la predicción en vivo. Una construcción de audio de medio día con un resultado vistoso, dejando abierta la extracción de características.', 'health-medtech', '3-6h', 3, 6, 'intermediate', '["diagnostics","wearable-health"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Plate Photo Estimator for Portion and Macros', 'Estimador por foto del plato para porciones y macros', 'Photograph your meal and the app segments the plate, estimates portion sizes against a reference object, and returns a rough macro breakdown you can correct with a tap. It logs the day''s running totals. A demoable half-day build that turns a snapshot into numbers, leaving the vision and estimation approach open.', 'Fotografía tu comida y la app segmenta el plato, estima las porciones contra un objeto de referencia y devuelve un desglose aproximado de macros que puedes corregir con un toque. Registra los totales del día. Una construcción demostrable de medio día que convierte una foto en números, dejando abierto el método de visión y estimación.', 'health-medtech', '3-6h', 3, 6, 'intermediate', '["nutrition","diagnostics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Sign-Language Intake Form for Deaf Clinic Visits', 'Formulario de admisión en lengua de señas para pacientes sordos', 'A clinic kiosk that plays each intake question as a sign-language video and lets a Deaf patient answer by selecting signed options, then prints a clean summary for the nurse. It removes the need for a written-English form at check-in. A half-day accessibility build with a clear demo, leaving the video and matching layer open.', 'Un quiosco de clínica que reproduce cada pregunta de admisión como video en lengua de señas y deja que un paciente sordo responda eligiendo opciones señadas, e imprime un resumen limpio para enfermería. Elimina la necesidad de un formulario escrito en el check-in. Una construcción de accesibilidad de medio día con demo clara, dejando abierta la capa de video y emparejamiento.', 'health-medtech', '3-6h', 3, 6, 'intermediate', '["accessibility","telemedicine"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Panic Attack Companion with a Grounding Countdown', 'Compañero de ataques de pánico con cuenta regresiva de anclaje', 'One tap launches a full-screen grounding flow that walks you through the five-senses technique with timed prompts and a slowing pulse animation, then logs the episode''s length and triggers. It learns which exercise calmed you fastest. A focused half-day build with an emotional, demoable core, leaving personalization open.', 'Un toque lanza un flujo de anclaje a pantalla completa que te guía por la técnica de los cinco sentidos con avisos cronometrados y una animación de pulso que se desacelera, y luego registra la duración y los detonantes del episodio. Aprende qué ejercicio te calmó más rápido. Una construcción enfocada de medio día con un núcleo emotivo y demostrable, dejando la personalización abierta.', 'health-medtech', '3-6h', 3, 6, 'intermediate', '["mental-health"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Gait Wobble Detector from a Phone in Your Pocket', 'Detector de inestabilidad al caminar desde el bolsillo', 'Walk a hallway with your phone in your pocket and the app reads the accelerometer to score balance and stride symmetry, flagging fall risk for an older adult over time. The demo shows a live wobble meter as someone walks. A half-day sensor build with a clear visual, leaving the signal processing open.', 'Camina un pasillo con el teléfono en el bolsillo y la app lee el acelerómetro para puntuar el equilibrio y la simetría del paso, marcando riesgo de caídas en un adulto mayor con el tiempo. La demo muestra un medidor de inestabilidad en vivo al caminar. Una construcción de sensores de medio día con un resultado visual claro, dejando abierto el procesamiento de señal.', 'health-medtech', '3-6h', 3, 6, 'intermediate', '["wearable-health","diagnostics","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Medication Conflict Checker for a Caregiver''s List', 'Verificador de conflictos para la lista de un cuidador', 'Type the medications a relative takes and the tool flags risky pairs, duplicate ingredients, and timing clashes in plain language a non-clinician understands. It builds a simple daily schedule grid to print. A demoable half-day build that turns a messy pill list into clarity, leaving the interaction data source open.', 'Escribe los medicamentos que toma un familiar y la herramienta marca combinaciones riesgosas, ingredientes duplicados y choques de horario en un lenguaje que entiende un no clínico. Arma una grilla simple de horario diario para imprimir. Una construcción demostrable de medio día que convierte una lista caótica de pastillas en claridad, dejando abierta la fuente de datos de interacciones.', 'health-medtech', '3-6h', 3, 6, 'intermediate', '["med-data","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Lab Result Explainer that Turns Numbers into Plain Words', 'Explicador de análisis que convierte números en lenguaje claro', 'Upload a blood test PDF and the tool extracts each value, marks which are out of range, and explains in plain language what each marker means and what tends to move it. It links related markers so trends make sense. A focused half-day build with an immediate before-and-after demo, leaving parsing and explanation open.', 'Sube el PDF de un análisis de sangre y la herramienta extrae cada valor, marca cuáles están fuera de rango y explica en lenguaje claro qué significa cada marcador y qué suele alterarlo. Vincula marcadores relacionados para que las tendencias tengan sentido. Una construcción enfocada de medio día con una demo inmediata de antes y después, dejando abierto el parseo y la explicación.', 'health-medtech', '3-6h', 3, 6, 'intermediate', '["med-data","diagnostics","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Sleep Story Generator that Adapts to Your Wind-Down', 'Generador de cuentos para dormir que se adapta a tu calma', 'Set a bedtime mood and the app narrates a slow, branching story whose pace and length shrink as your taps slow down, easing you toward sleep without a hard stop. It remembers which themes settled you fastest. A demoable half-day audio build with a soothing core, leaving narration and adaptation logic open.', 'Elige un estado para acostarte y la app narra un cuento lento y ramificado cuyo ritmo y duración se reducen a medida que tus toques se desaceleran, llevándote al sueño sin un corte brusco. Recuerda qué temas te calmaron más rápido. Una construcción de audio de medio día demostrable con un núcleo relajante, dejando abierta la narración y la lógica de adaptación.', 'health-medtech', '3-6h', 3, 6, 'intermediate', '["mental-health","wearable-health"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Physical-Therapy Rep Counter with Form Correction', 'Contador de repeticiones de fisioterapia con corrección de postura', 'The webcam watches a prescribed exercise, counts clean reps, and calls out when your range of motion is too shallow or your knee caves in, so home recovery stays on track. It emails a progress sheet to the therapist. A meaty build for most of a day, leaving the pose model and rule thresholds open.', 'La webcam observa un ejercicio prescrito, cuenta las repeticiones correctas y avisa cuando tu rango de movimiento es escaso o la rodilla se mete hacia adentro, para que la recuperación en casa siga su curso. Envía una hoja de progreso al fisioterapeuta. Una construcción sólida para casi un día, dejando abierto el modelo de postura y los umbrales de las reglas.', 'health-medtech', '6-12h', 6, 12, 'intermediate', '["fitness","diagnostics","telemedicine"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Triage Chat that Routes a Patient to the Right Care Level', 'Chat de triaje que dirige al paciente al nivel de atención correcto', 'A guided intake chat asks about symptoms, red flags, and history, then recommends self-care, a clinic, or the emergency room with the reasoning shown so the patient trusts it. It hands a structured summary to whoever sees them next. A full-day build with a clear demo, leaving the question tree and safety rules open.', 'Un chat de admisión guiado pregunta por síntomas, señales de alarma e historial, y luego recomienda autocuidado, clínica o urgencias mostrando el razonamiento para que el paciente confíe. Entrega un resumen estructurado a quien lo atienda después. Una construcción de un día con una demo clara, dejando abierto el árbol de preguntas y las reglas de seguridad.', 'health-medtech', '6-12h', 6, 12, 'intermediate', '["telemedicine","diagnostics","med-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Glucose Trend Coach that Pairs Spikes with Meals', 'Coach de glucosa que asocia picos con comidas', 'Import a day of glucose readings and log meals by photo; the app lines up each spike with what you ate and surfaces the foods that hit you hardest. It suggests swaps to flatten tomorrow''s curve. A full-day build with a compelling overlay chart, leaving the data import and matching approach open.', 'Importa un día de lecturas de glucosa y registra comidas por foto; la app alinea cada pico con lo que comiste y revela los alimentos que más te impactan. Sugiere reemplazos para aplanar la curva de mañana. Una construcción de un día con un gráfico superpuesto convincente, dejando abierto el método de importación y emparejamiento de datos.', 'health-medtech', '6-12h', 6, 12, 'intermediate', '["nutrition","wearable-health","diagnostics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Voice Journal that Flags Depression Risk Phrases Over Time', 'Diario de voz que detecta frases de riesgo depresivo en el tiempo', 'Speak a daily journal entry and the app transcribes it, tracking shifts in tone, energy words, and sleep mentions to draw a gentle wellbeing trend line. It suggests reaching out when several signals dip together. A full-day build with a meaningful demo arc, leaving the language signals and thresholds open.', 'Graba una entrada de diario hablada y la app la transcribe, siguiendo cambios de tono, palabras de energía y menciones de sueño para trazar una suave línea de bienestar. Sugiere pedir ayuda cuando varias señales bajan juntas. Una construcción de un día con un arco de demo significativo, dejando abiertas las señales del lenguaje y los umbrales.', 'health-medtech', '6-12h', 6, 12, 'advanced', '["mental-health","diagnostics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Wound Photo Tracker that Measures Healing Progress', 'Seguidor por foto de heridas que mide el progreso de cicatrización', 'A nurse photographs a wound with a coin for scale and the app measures its area, tracks color and edge changes across visits, and flags when healing stalls. It generates a clean report for the chart. A full-day build with a clear measurement demo, leaving the segmentation and scaling method open.', 'Una enfermera fotografía una herida con una moneda como escala y la app mide su área, rastrea cambios de color y bordes entre visitas y avisa cuando la cicatrización se detiene. Genera un informe limpio para la historia clínica. Una construcción de un día con una demo de medición clara, dejando abierto el método de segmentación y escalado.', 'health-medtech', '6-12h', 6, 12, 'intermediate', '["diagnostics","telemedicine","med-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Eye-Tracking Communicator for Patients Who Cannot Speak', 'Comunicador con seguimiento ocular para pacientes sin habla', 'Using only a webcam, the app lets an ICU patient who cannot speak select letters and common phrases by holding their gaze, building sentences read aloud to caregivers. It offers quick tiles for pain, water, and family. A full-day accessibility build with a moving demo, leaving the gaze calibration approach open.', 'Usando solo una webcam, la app permite a un paciente en UCI que no puede hablar seleccionar letras y frases comunes manteniendo la mirada, formando oraciones que se leen en voz alta a los cuidadores. Ofrece casillas rápidas para dolor, agua y familia. Una construcción de accesibilidad de un día con una demo conmovedora, dejando abierto el método de calibración de la mirada.', 'health-medtech', '6-12h', 6, 12, 'advanced', '["accessibility","telemedicine"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Anonymized Patient Data Sandbox for Safe Demos', 'Entorno de datos de pacientes anonimizados para demos seguras', 'Feed in a messy clinical spreadsheet and the tool strips identifiers, shifts dates consistently, and generates realistic synthetic rows so teams can build and demo without touching real patients. It reports what it scrubbed. A full-day data build with a clear before-and-after view, leaving the de-identification rules open.', 'Carga una planilla clínica desordenada y la herramienta quita identificadores, desplaza fechas de forma consistente y genera filas sintéticas realistas para que los equipos construyan y demuestren sin tocar pacientes reales. Informa qué eliminó. Una construcción de datos de un día con una vista clara de antes y después, dejando abiertas las reglas de desidentificación.', 'health-medtech', '6-12h', 6, 12, 'advanced', '["med-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Remote Vitals Dashboard from a Patient''s Phone Camera', 'Panel de signos vitales remotos desde la cámara del paciente', 'During a telehealth call the patient holds a fingertip to the camera and the app estimates heart rate and breathing from subtle color changes, streaming them to the clinician''s dashboard live. It logs a trend across visits. A day-plus build with a striking real-time demo, leaving the signal extraction and call layer open.', 'Durante una videoconsulta el paciente apoya la yema del dedo en la cámara y la app estima la frecuencia cardíaca y respiratoria a partir de sutiles cambios de color, transmitiéndolas en vivo al panel del médico. Registra una tendencia entre visitas. Una construcción de más de un día con una demo en tiempo real impactante, dejando abierta la extracción de señal y la capa de llamada.', 'health-medtech', '12-24h', 12, 24, 'advanced', '["telemedicine","wearable-health","diagnostics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Med Adherence Loop with Smart Reminders and Caregiver Alerts', 'Ciclo de adherencia con recordatorios inteligentes y alertas al cuidador', 'Patients confirm each dose with a tap or photo of the pill in hand; missed doses escalate to a caregiver and the system learns the times a person actually takes meds to schedule smarter. A shared view shows the week at a glance. A day-plus build with a full loop to demo, leaving confirmation and escalation logic open.', 'Los pacientes confirman cada dosis con un toque o una foto de la pastilla en la mano; las dosis omitidas escalan a un cuidador y el sistema aprende los horarios reales de toma para programar mejor. Una vista compartida muestra la semana de un vistazo. Una construcción de más de un día con un ciclo completo para demostrar, dejando abierta la lógica de confirmación y escalado.', 'health-medtech', '12-24h', 12, 24, 'intermediate', '["med-data","telemedicine","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Peer Support Room that Matches by Symptom and Stage', 'Sala de apoyo entre pares que empareja por síntoma y etapa', 'People living with a chronic condition join moderated micro-rooms matched by their specific symptom and treatment stage, with prompts that keep talk supportive and a quiet safety net for crisis language. A facilitator view tracks room health. A day-plus build with a real flow to demo, leaving the matching and moderation rules open.', 'Personas con una condición crónica se unen a micro-salas moderadas emparejadas por su síntoma específico y etapa de tratamiento, con consignas que mantienen el tono de apoyo y una red de seguridad silenciosa para lenguaje de crisis. Una vista de facilitador sigue la salud de la sala. Una construcción de más de un día con un flujo real para demostrar, dejando abiertas las reglas de emparejamiento y moderación.', 'health-medtech', '12-24h', 12, 24, 'intermediate', '["mental-health","telemedicine"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Retinal Photo Screener that Flags Diabetic Eye Changes', 'Cribado de fotos de retina que detecta cambios oculares por diabetes', 'Upload a smartphone-captured retinal image and the tool highlights regions consistent with diabetic retinopathy, returns a referral-or-watch suggestion, and stacks images to show progression. The demo loads a sample eye and lights up the findings. A day-plus build for a focused team, leaving the model and overlay approach open.', 'Sube una imagen de retina capturada con el celular y la herramienta resalta regiones compatibles con retinopatía diabética, devuelve una sugerencia de derivar o vigilar y apila imágenes para mostrar progresión. La demo carga un ojo de muestra y enciende los hallazgos. Una construcción de más de un día para un equipo enfocado, dejando abierto el modelo y el método de superposición.', 'health-medtech', '12-24h', 12, 24, 'advanced', '["diagnostics","med-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Recovery Companion that Plans the Week After Surgery', 'Compañero de recuperación que planea la semana post cirugía', 'Enter a procedure and the app builds a day-by-day recovery plan with med timing, gentle activity goals, and warning signs to watch, adapting as the patient logs pain and mobility. It nudges a call when reported symptoms cross a line. A day-plus build with a complete journey to demo, leaving the plan templates open.', 'Ingresa un procedimiento y la app arma un plan de recuperación día a día con horarios de medicación, metas de actividad suave y señales de alarma, adaptándose a medida que el paciente registra dolor y movilidad. Sugiere una llamada cuando los síntomas cruzan un límite. Una construcción de más de un día con un recorrido completo para demostrar, dejando abiertas las plantillas del plan.', 'health-medtech', '12-24h', 12, 24, 'intermediate', '["telemedicine","med-data","fitness"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('ECG Anomaly Watch from a Wearable''s Raw Signal', 'Vigilancia de anomalías de ECG desde la señal cruda del wearable', 'Stream raw heart-rhythm data from a wrist sensor and the system flags irregular beats like possible atrial fibrillation, marks the clips for review, and builds a doctor-ready strip. The demo replays a recording and the alert fires on the abnormal stretch. A weekend build for a serious team, leaving the detection model open.', 'Transmite datos crudos del ritmo cardíaco desde un sensor de muñeca y el sistema marca latidos irregulares como posible fibrilación auricular, señala los clips para revisión y arma una tira lista para el médico. La demo reproduce una grabación y la alerta se dispara en el tramo anormal. Una construcción de fin de semana para un equipo serio, dejando abierto el modelo de detección.', 'health-medtech', '24-48h', 24, 48, 'advanced', '["wearable-health","diagnostics","med-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Clinic-in-a-Box Offline App for Low-Connectivity Areas', 'App de clínica en una caja sin conexión para zonas remotas', 'A health worker in a remote village runs a phone app that records visits, screens common conditions with simple decision flows, and syncs everything once back in signal range. It works fully offline and queues referrals. A weekend build with a realistic field demo, leaving the offline sync and screening flows open.', 'Un agente de salud en una aldea remota usa una app de teléfono que registra visitas, criba condiciones comunes con flujos de decisión simples y sincroniza todo al recuperar señal. Funciona totalmente sin conexión y encola derivaciones. Una construcción de fin de semana con una demo de campo realista, dejando abierta la sincronización offline y los flujos de cribado.', 'health-medtech', '24-48h', 24, 48, 'advanced', '["telemedicine","diagnostics","med-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Personal Health Timeline that Unifies Scattered Records', 'Línea de tiempo de salud que unifica registros dispersos', 'Drop in PDFs, lab files, and visit notes from different clinics and the app merges them into one searchable timeline, deduplicating tests and surfacing gaps in care. A patient finally sees their whole history in one place to share with a new doctor. A weekend build with a rich demo, leaving the parsing and merge logic open.', 'Carga PDFs, archivos de laboratorio y notas de visitas de distintas clínicas y la app los fusiona en una sola línea de tiempo buscable, eliminando estudios duplicados y revelando vacíos en la atención. El paciente por fin ve todo su historial en un lugar para compartir con un nuevo médico. Una construcción de fin de semana con una demo rica, dejando abierta la lógica de parseo y fusión.', 'health-medtech', '24-48h', 24, 48, 'advanced', '["med-data","accessibility","telemedicine"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Knock-Pattern Door Unlock with a Piezo Sensor', 'Apertura de Puerta por Patron de Golpes con Sensor Piezo', 'A door lock that opens when you tap a secret rhythm on the frame. A piezo sensor reads the vibration pattern, matches the timing against your saved knock, and triggers a servo or relay when it lines up. The demo is irresistible: knock the wrong rhythm and nothing happens, knock the right one and the bolt slides open. A sharp single-sensor build for a short sprint.', 'Una cerradura que se abre cuando golpeas un ritmo secreto en el marco. Un sensor piezo lee el patron de vibracion, compara los tiempos contra tu golpe guardado y dispara un servo o rele cuando coincide. La demo es irresistible: golpea mal y no pasa nada, golpea bien y el pestillo se abre. Una construccion afilada de un solo sensor para un sprint corto.', 'iot-hardware', '3-6h', 3, 6, 'beginner', '["sensors","arduino-rpi","home-automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Posture Coach Wearable that Buzzes When You Slouch', 'Wearable Entrenador de Postura que Vibra al Encorvarte', 'A clip-on wearable that lives on your collar or back and gently buzzes the moment your spine curls forward. An accelerometer learns your upright baseline in a quick calibration, then watches the tilt angle and fires a haptic nudge after a few seconds of slouching. The demo: wear it, slump, feel the buzz. A tight single-feature build for a half-day sprint.', 'Un wearable de clip que vive en tu cuello o espalda y vibra suavemente apenas tu columna se curva hacia adelante. Un acelerometro aprende tu linea base erguida en una calibracion rapida, luego vigila el angulo de inclinacion y dispara un aviso haptico tras unos segundos encorvado. La demo: usalo, encorvate, senti la vibracion. Una construccion compacta de un solo feature para medio dia.', 'iot-hardware', '3-6h', 3, 6, 'beginner', '["wearables","sensors"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Plant That Texts You When Its Soil Goes Dry', 'Planta que te Escribe Cuando su Tierra se Seca', 'A potted plant that sends you a message in its own voice when it needs water. A capacitive soil-moisture probe reads the dirt, and when it drops below a threshold the device pings your phone with a cheeky line. The demo: dry the sensor with a hair dryer and watch the notification arrive live. A clean, demoable build that fits a short sprint.', 'Una planta en maceta que te manda un mensaje con su propia voz cuando necesita agua. Una sonda capacitiva de humedad lee la tierra y, cuando baja del umbral, el dispositivo te avisa al telefono con una frase picara. La demo: seca el sensor con un secador y mira llegar la notificacion en vivo. Una construccion limpia y mostrable para un sprint corto.', 'iot-hardware', '3-6h', 3, 6, 'beginner', '["sensors","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Reaction-Time Arcade with Light-Up Buttons', 'Arcade de Tiempo de Reaccion con Botones Luminosos', 'A whack-a-mole style reflex game built from a grid of arcade buttons with embedded LEDs. A button lights up at random and you must slap it before it goes dark, with the pace ramping as your score climbs. A small screen or LED bar shows the live score. The demo plays itself: hand a judge the panel and watch them get hooked. A punchy build for a short sprint.', 'Un juego de reflejos estilo topo a topo hecho con una grilla de botones arcade con LEDs integrados. Un boton se enciende al azar y debes golpearlo antes de que se apague, con el ritmo acelerando a medida que sube tu puntaje. Una pantallita o barra LED muestra el puntaje en vivo. La demo se juega sola: pasale el panel a un juez y miralo engancharse. Construccion contundente para un sprint corto.', 'iot-hardware', '3-6h', 3, 6, 'beginner', '["lights","arduino-rpi","sensors"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Gesture-Controlled Lights from a Wave of Your Hand', 'Luces Controladas por Gestos con un Movimiento de Mano', 'A light switch you operate by waving in the air, no contact needed. A time-of-flight or gesture sensor reads swipes and holds, mapping a left wave to off, a right wave to on, and a hover to dim. Perfect for a kitchen with messy hands. The demo: wave once and the room responds. A satisfying single-sensor build that fits a half-day sprint.', 'Un interruptor de luz que operas agitando la mano en el aire, sin contacto. Un sensor de tiempo de vuelo o de gestos lee deslizamientos y pausas, mapeando un movimiento a la izquierda como apagar, a la derecha como encender y mantener como atenuar. Ideal para una cocina con manos sucias. La demo: agita una vez y el ambiente responde. Construccion satisfactoria de un sensor para medio dia.', 'iot-hardware', '3-6h', 3, 6, 'intermediate', '["lights","sensors","home-automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Mailbox Sentry that Pings You When Mail Arrives', 'Centinela de Buzon que te Avisa al Llegar el Correo', 'A battery sensor that drops in your mailbox and notifies your phone the instant the lid opens or a letter blocks the light. A tiny photodiode or reed switch detects the event, then a low-power radio sends the alert so you skip pointless trips to the curb. The demo: open the lid and watch the ping land. A focused low-power build for a short sprint.', 'Un sensor a pilas que pones en tu buzon y notifica a tu telefono apenas se abre la tapa o una carta bloquea la luz. Un fotodiodo o switch reed detecta el evento y luego una radio de bajo consumo envia la alerta para que evites viajes inutiles a la vereda. La demo: abri la tapa y mira llegar el aviso. Construccion enfocada de bajo consumo para un sprint corto.', 'iot-hardware', '3-6h', 3, 6, 'beginner', '["sensors","home-automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Ambient Lamp that Glows with Your Crypto or Stock', 'Lampara Ambiental que Brilla con tu Cripto o Accion', 'A desk lamp that turns your portfolio into mood lighting. It pulls a price feed and shifts an LED strip from deep green when an asset climbs to angry red when it dips, breathing faster the bigger the swing. Glance up instead of refreshing an app. The demo: mock a price drop and watch the room turn red. A clean feed-to-light build for a short sprint.', 'Una lampara de escritorio que convierte tu portafolio en iluminacion de ambiente. Toma un feed de precios y mueve una tira LED de verde profundo cuando un activo sube a rojo furioso cuando cae, respirando mas rapido cuanto mayor es el movimiento. Mira hacia arriba en vez de refrescar una app. La demo: simula una caida y mira la sala ponerse roja. Construccion limpia de feed a luz para un sprint corto.', 'iot-hardware', '3-6h', 3, 6, 'intermediate', '["lights","home-automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Standing-Desk Nudge that Watches Your Sit Time', 'Aviso de Escritorio que Vigila tu Tiempo Sentado', 'A small sensor under your chair that tracks how long you have been sitting and nudges you to stand. A pressure pad detects occupancy, a timer counts continuous sit minutes, and an LED ring shifts from green to red as the hour fills. The demo: sit down, fast-forward the timer, and watch the ring scold you. A tidy single-input build for a short sprint.', 'Un pequeno sensor bajo tu silla que registra cuanto llevas sentado y te empuja a pararte. Una almohadilla de presion detecta ocupacion, un temporizador cuenta los minutos continuos sentado y un anillo LED pasa de verde a rojo a medida que se llena la hora. La demo: sentate, adelanta el temporizador y mira el anillo retarte. Construccion prolija de una entrada para un sprint corto.', 'iot-hardware', '3-6h', 3, 6, 'beginner', '["sensors","lights","wearables"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Self-Balancing Two-Wheel Robot from a Gyro Loop', 'Robot de Dos Ruedas Autoequilibrado con Lazo Giroscopico', 'A pocket robot that stays upright on two wheels like a tiny Segway. An IMU feeds tilt data into a control loop that drives the motors to catch every fall before it happens, holding balance even when you poke it. The demo writes itself: nudge the bot and watch it fight back to vertical. A meaty control-systems build that suits a full-day sprint.', 'Un robot de bolsillo que se mantiene erguido sobre dos ruedas como un mini Segway. Una IMU alimenta datos de inclinacion a un lazo de control que mueve los motores para atrapar cada caida antes de que ocurra, sosteniendo el equilibrio aun cuando lo empujas. La demo se escribe sola: empuja el bot y miralo volver a la vertical. Construccion sustanciosa de sistemas de control ideal para un dia completo.', 'iot-hardware', '6-12h', 6, 12, 'advanced', '["robotics","sensors","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Whole-Home Energy Sniffer that Names Each Appliance', 'Olfateador de Energia Domestica que Nombra Cada Aparato', 'A clamp on your main power line that learns the electrical signature of each appliance and tells you what just turned on. A current sensor samples the load, and a fingerprinting step distinguishes the kettle from the dryer by their startup spikes. The demo: switch on a device and watch its name pop up on a live dashboard. A rich signal-processing build for a full day.', 'Una pinza en tu linea principal que aprende la firma electrica de cada aparato y te dice cual acaba de encenderse. Un sensor de corriente muestrea la carga y un paso de identificacion distingue la pava de la secadora por sus picos de arranque. La demo: encende un dispositivo y mira aparecer su nombre en un tablero en vivo. Construccion rica en procesamiento de senal para un dia completo.', 'iot-hardware', '6-12h', 6, 12, 'advanced', '["energy-monitor","sensors","home-automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Line-Following Delivery Cart for a Crowded Office', 'Carrito Seguidor de Linea para una Oficina Llena', 'A small wheeled robot that follows a taped path to ferry snacks or mail between desks. Infrared sensors track the line, an ultrasonic sensor halts it when someone steps in front, and a button at each stop sends it onward. The demo: load it up, press go, and watch it weave to the next desk and pause for an obstacle. A solid robotics build for a full-day sprint.', 'Un pequeno robot con ruedas que sigue un camino de cinta para llevar snacks o correo entre escritorios. Sensores infrarrojos rastrean la linea, un sensor ultrasonico lo detiene cuando alguien se cruza y un boton en cada parada lo manda a seguir. La demo: cargalo, presiona arrancar y miralo serpentear al siguiente escritorio y frenar ante un obstaculo. Construccion solida de robotica para un dia completo.', 'iot-hardware', '6-12h', 6, 12, 'intermediate', '["robotics","sensors","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Sleep-Stage Night Light that Dims as You Drift Off', 'Luz Nocturna por Etapas que se Atenua al Dormirte', 'A bedside lamp that reads your movement and slowly fades to black as you fall asleep. A motion sensor or wrist accelerometer tracks restlessness, and the light eases down over minutes once stillness sets in, then snaps to a soft glow if you stir at night. The demo: lie still and watch the lamp breathe down. A cozy sensing-and-lighting build for a full day.', 'Una lampara de mesa de luz que lee tu movimiento y se desvanece lentamente al dormirte. Un sensor de movimiento o acelerometro de muneca rastrea la inquietud y la luz baja gradualmente cuando llega la quietud, luego salta a un brillo suave si te moves de noche. La demo: quedate quieto y mira la lampara apagarse de a poco. Construccion acogedora de sensado e iluminacion para un dia completo.', 'iot-hardware', '6-12h', 6, 12, 'intermediate', '["lights","sensors","wearables"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Bin That Sorts Recyclables with a Camera and Flap', 'Tacho que Separa Reciclables con Camara y Compuerta', 'A trash bin that recognizes what you drop in and steers it to the right compartment. A small camera classifies the item as plastic, paper, or trash, then a servo flap tilts to guide it into the matching bay. The demo: drop a bottle and a crumpled page and watch them land in different sides. A satisfying vision-plus-actuator build for a full-day sprint.', 'Un tacho de basura que reconoce lo que arrojas y lo dirige al compartimento correcto. Una camarita clasifica el objeto como plastico, papel o basura, luego una compuerta con servo se inclina para guiarlo al casillero adecuado. La demo: arroja una botella y un papel arrugado y miralos caer en lados distintos. Construccion satisfactoria de vision mas actuador para un dia completo.', 'iot-hardware', '6-12h', 6, 12, 'intermediate', '["robotics","sensors","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Fall-Alert Wearable for Grandparents Living Alone', 'Wearable de Alerta de Caidas para Abuelos que Viven Solos', 'A wristband that detects a hard fall and calls for help if its wearer does not respond. An accelerometer spots the impact-then-stillness pattern, starts a countdown with a buzzer, and sends an alert to a family member if no button is pressed in time. The demo: drop it, ignore the buzzer, and watch the alert fire. A meaningful sensing build for a full-day sprint.', 'Una pulsera que detecta una caida fuerte y pide ayuda si quien la usa no responde. Un acelerometro detecta el patron de impacto y quietud, inicia una cuenta regresiva con zumbador y envia una alerta a un familiar si no se presiona el boton a tiempo. La demo: dejala caer, ignora el zumbador y mira dispararse la alerta. Construccion significativa de sensado para un dia completo.', 'iot-hardware', '6-12h', 6, 12, 'intermediate', '["wearables","sensors"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Voice-Free Sign Glove that Speaks Hand Signs Aloud', 'Guante de Senas sin Voz que Habla los Gestos en Voz Alta', 'A glove that turns hand signs into spoken words for someone who cannot speak. Flex sensors on each finger and an IMU read the gesture, a small library maps each shape to a phrase, and a speaker says it aloud. The demo: form a sign and hear the glove voice it. A heartfelt sensor-fusion build with room for five teams to map gestures differently in a full day.', 'Un guante que convierte senas en palabras habladas para alguien que no puede hablar. Sensores de flexion en cada dedo y una IMU leen el gesto, una libreria pequena mapea cada forma a una frase y un parlante la dice en voz alta. La demo: forma una sena y escucha al guante pronunciarla. Construccion conmovedora de fusion de sensores con espacio para que cinco equipos mapeen gestos distinto en un dia.', 'iot-hardware', '6-12h', 6, 12, 'intermediate', '["wearables","sensors","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Solar Tracker Panel that Chases the Sun All Day', 'Panel Seguidor Solar que Persigue al Sol Todo el Dia', 'A miniature solar panel on a motorized mount that pivots to face the brightest light. Four light sensors compare brightness across quadrants, and two servos rotate the panel until they balance, squeezing extra watts from the same cell. The demo: move a lamp around the rig and watch the panel turn to follow it. A tidy closed-loop build for a full-day sprint.', 'Un panel solar en miniatura sobre una base motorizada que gira para enfrentar la luz mas intensa. Cuatro sensores de luz comparan el brillo entre cuadrantes y dos servos rotan el panel hasta equilibrarlos, exprimiendo vatios extra de la misma celda. La demo: move una lampara alrededor del equipo y mira al panel girar para seguirla. Construccion prolija de lazo cerrado para un dia completo.', 'iot-hardware', '6-12h', 6, 12, 'intermediate', '["energy-monitor","sensors","robotics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Pill Box that Lights the Right Slot and Logs Doses', 'Pastillero que Ilumina el Compartimento y Registra Dosis', 'A weekly pill organizer that glows on the next slot due and records when you actually take it. An LED marks the correct compartment by schedule, a sensor confirms the lid opened, and a missed dose triggers a reminder. The demo: the box lights up, you open the wrong slot, and it gently corrects you. A caring scheduling-and-sensing build for a full-day sprint.', 'Un organizador semanal de pastillas que se ilumina en el proximo compartimento y registra cuando realmente lo tomas. Un LED marca el casillero correcto segun el horario, un sensor confirma que se abrio la tapa y una dosis omitida dispara un recordatorio. La demo: la caja se ilumina, abres el casillero equivocado y te corrige con suavidad. Construccion cuidadosa de agenda y sensado para un dia completo.', 'iot-hardware', '6-12h', 6, 12, 'intermediate', '["lights","sensors","home-automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Air-Quality Beacon that Maps Your Commute Pollution', 'Baliza de Calidad del Aire que Mapea la Polucion del Viaje', 'A pocket sensor that logs the air you breathe on your way to work and paints a pollution map of your route. A particulate and gas sensor samples as you move, pairing each reading with location so the worst stretches stand out. The demo: walk a loop and watch the route color from green to red on a map. A satisfying mobile-sensing build for a full-day sprint.', 'Un sensor de bolsillo que registra el aire que respiras camino al trabajo y pinta un mapa de polucion de tu ruta. Un sensor de particulas y gases muestrea mientras te moves, asociando cada lectura con la ubicacion para que los peores tramos resalten. La demo: camina un circuito y mira la ruta colorearse de verde a rojo en un mapa. Construccion satisfactoria de sensado movil para un dia completo.', 'iot-hardware', '6-12h', 6, 12, 'intermediate', '["sensors","wearables","energy-monitor"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Robot Arm that Plays Tic-Tac-Toe Against You', 'Brazo Robotico que Juega al Ta-Te-Ti Contra Vos', 'A desktop robot arm that watches the board, plans its move, and physically places its piece. A camera reads the grid, a simple solver picks the optimal square, and the arm lowers a marker into place. The demo is a crowd-pleaser: a judge plays a round against the arm and tries not to lose. A rich vision-plus-motion build that fills a full-day sprint nicely.', 'Un brazo robotico de escritorio que observa el tablero, planea su jugada y coloca fisicamente su ficha. Una camara lee la grilla, un solucionador simple elige la mejor casilla y el brazo baja una ficha a su lugar. La demo encanta al publico: un juez juega una ronda contra el brazo e intenta no perder. Construccion rica de vision mas movimiento que llena bien un dia completo.', 'iot-hardware', '6-12h', 6, 12, 'advanced', '["robotics","sensors","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Bike Turn-Signal Jacket You Trigger from the Bars', 'Campera con Senalizadores de Bici que Disparas del Manubrio', 'A cycling jacket with LED arrows on the back that flash your turns, triggered by buttons on the handlebars. A tiny wireless link fires the left or right panel, and a brake-detecting accelerometer can flash a stop pattern automatically. The demo: press a bar button and watch the arrow sweep across the back. A wearable safety build that fits a full-day sprint.', 'Una campera de ciclismo con flechas LED en la espalda que senalizan tus giros, disparadas por botones en el manubrio. Un enlace inalambrico activa el panel izquierdo o derecho y un acelerometro que detecta frenadas puede destellar un patron de alto automaticamente. La demo: presiona un boton del manubrio y mira la flecha barrer la espalda. Construccion wearable de seguridad para un dia completo.', 'iot-hardware', '6-12h', 6, 12, 'intermediate', '["wearables","lights","sensors"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Pet Feeder that Dispenses on a Camera Headcount', 'Comedero que Sirve Segun el Conteo de la Camara', 'An automatic pet feeder that only drops food when it sees the right pet, not the neighbor''s cat. A camera identifies your animal, a portion-controlled auger releases a measured serving, and every meal is logged with a timestamp. The demo: show your pet to the lens and watch the kibble drop, then show another face and see it refuse. A neat vision-actuator build for a full day.', 'Un comedero automatico que solo libera comida cuando ve a la mascota correcta, no al gato del vecino. Una camara identifica a tu animal, un tornillo dosificador libera una porcion medida y cada comida queda registrada con marca de tiempo. La demo: mostra tu mascota al lente y mira caer el alimento, luego mostra otra cara y velo negarse. Construccion prolija de vision y actuador para un dia.', 'iot-hardware', '6-12h', 6, 12, 'intermediate', '["robotics","sensors","home-automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Greenhouse Brain that Waters and Vents on Its Own', 'Cerebro de Invernadero que Riega y Ventila Solo', 'A controller that runs a small greenhouse end to end, balancing water, heat, and air without you. Soil, temperature, and humidity sensors feed rules that open a vent, run a fan, or trigger a pump, and a dashboard shows the climate over time. The demo: heat the box with a lamp and watch the fan kick in and the vent crack open. A fuller multi-sensor build for a long sprint.', 'Un controlador que maneja un pequeno invernadero de punta a punta, equilibrando agua, calor y aire sin vos. Sensores de tierra, temperatura y humedad alimentan reglas que abren una rejilla, encienden un ventilador o disparan una bomba, y un tablero muestra el clima en el tiempo. La demo: calenta la caja con una lampara y mira arrancar el ventilador y abrirse la rejilla. Construccion amplia multisensor para un sprint largo.', 'iot-hardware', '12-24h', 12, 24, 'intermediate', '["sensors","home-automation","energy-monitor","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Indoor Maze Rover that Maps a Room and Finds the Exit', 'Rover de Laberinto que Mapea una Sala y Halla la Salida', 'A small rover that explores an unknown indoor space, builds a rough map, and drives to the way out. Distance sensors feel the walls, an odometry estimate tracks position, and a path planner picks the next move while a live map fills in on screen. The demo: drop it in a taped maze and watch it discover a route. A meaty autonomy build for a long sprint.', 'Un pequeno rover que explora un espacio interior desconocido, arma un mapa aproximado y conduce hacia la salida. Sensores de distancia palpan las paredes, una estimacion de odometria rastrea la posicion y un planificador elige el siguiente movimiento mientras un mapa en vivo se llena en pantalla. La demo: ponlo en un laberinto de cinta y miralo descubrir una ruta. Construccion sustanciosa de autonomia para un sprint largo.', 'iot-hardware', '12-24h', 12, 24, 'advanced', '["robotics","sensors","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Smart Mirror that Greets You with Your Day Ahead', 'Espejo Inteligente que te Saluda con tu Dia por Delante', 'A bathroom mirror with a display behind the glass that shows your calendar, weather, and commute as you brush your teeth. A presence sensor wakes it when you walk up, and voice or a tap cycles through panels so you never touch a phone. The demo: step in front and watch the glass come alive with your morning. A polished ambient build for a long sprint.', 'Un espejo de bano con una pantalla detras del vidrio que muestra tu agenda, el clima y el trafico mientras te cepillas los dientes. Un sensor de presencia lo despierta cuando te acercas y la voz o un toque cambia los paneles para que nunca toques el telefono. La demo: parate enfrente y mira el vidrio cobrar vida con tu manana. Construccion pulida de ambiente para un sprint largo.', 'iot-hardware', '12-24h', 12, 24, 'intermediate', '["home-automation","sensors","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Drone that Auto-Patrols a Yard on a Saved Route', 'Dron que Patrulla un Patio Solo en una Ruta Guardada', 'A small drone that flies a memorized perimeter loop and streams a check of the yard back to your phone. You walk waypoints once, it stores the path, and on command it lifts off, follows the route, and lands itself. The demo: tap patrol and watch it trace the loop and return home. A demanding flight-and-autonomy build for a long sprint with serious safety care.', 'Un pequeno dron que vuela un circuito de perimetro memorizado y transmite un chequeo del patio a tu telefono. Caminas los puntos una vez, guarda la ruta y, a la orden, despega, sigue el camino y aterriza solo. La demo: toca patrullar y miralo trazar el circuito y volver a casa. Construccion exigente de vuelo y autonomia para un sprint largo con seria atencion a la seguridad.', 'iot-hardware', '12-24h', 12, 24, 'advanced', '["drones","sensors","robotics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Sleep Apnea Pre-Screener from an Overnight Mat Sensor', 'Pre-Detector de Apnea con un Sensor de Colchon Nocturno', 'A thin under-mattress sensor strip that watches your breathing through the night and flags pauses worth asking a doctor about. A pressure or piezo film tracks chest movement, an overnight log marks suspected apnea events, and a morning report summarizes the night. The demo: hold your breath over the strip and watch the event register. A careful health-sensing build for a long sprint.', 'Una tira sensora delgada bajo el colchon que vigila tu respiracion toda la noche y marca pausas que vale consultar con un medico. Una pelicula de presion o piezo rastrea el movimiento del pecho, un registro nocturno marca eventos sospechosos de apnea y un reporte matinal resume la noche. La demo: contene la respiracion sobre la tira y mira registrarse el evento. Construccion cuidadosa de sensado de salud para un sprint largo.', 'iot-hardware', '12-24h', 12, 24, 'advanced', '["sensors","wearables"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Leak Guardian that Shuts Your Water Main on a Drip', 'Guardian de Fugas que Corta el Agua ante una Gotera', 'A whole-home water guard that detects an unexpected leak and slams the main valve shut before damage spreads. Floor sensors and a flow meter notice water where there should be none, a motorized valve closes the line, and your phone gets an alarm. The demo: drip water on a sensor and watch the valve crank shut in seconds. A robust safety automation build for a long sprint.', 'Un guardian de agua para toda la casa que detecta una fuga inesperada y cierra de golpe la valvula principal antes de que el dano se extienda. Sensores de piso y un caudalimetro notan agua donde no deberia haber, una valvula motorizada cierra la linea y tu telefono recibe una alarma. La demo: gotea agua sobre un sensor y mira la valvula cerrarse en segundos. Construccion robusta de automatizacion de seguridad para un sprint largo.', 'iot-hardware', '12-24h', 12, 24, 'intermediate', '["sensors","home-automation","energy-monitor"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Gesture-Steered Robot Hand that Mirrors Your Glove', 'Mano Robotica Guiada por Gestos que Imita tu Guante', 'A robotic hand that copies your finger movements in real time from a sensor glove. Flex sensors on each finger stream their bend over a wireless link, and servos in the robot hand mirror the motion so it grips when you grip. The demo: close your fist and watch the robot hand close with you. A satisfying teleoperation build with rich room to extend over a long sprint.', 'Una mano robotica que copia los movimientos de tus dedos en tiempo real desde un guante sensor. Sensores de flexion en cada dedo transmiten su curvatura por un enlace inalambrico y los servos de la mano robotica imitan el movimiento, de modo que aprieta cuando vos apretas. La demo: cerra el puno y mira la mano robotica cerrarse contigo. Construccion satisfactoria de teleoperacion con amplio margen para un sprint largo.', 'iot-hardware', '12-24h', 12, 24, 'advanced', '["robotics","wearables","sensors","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Off-Grid Mesh Pagers for When the Cell Network Dies', 'Buscapersonas Mesh sin Red para Cuando Cae la Celular', 'A set of pocket devices that pass short text messages to each other over long-range radio when there is no internet or cell coverage. Each node relays for its neighbors so a message hops across a campus or trail, and an e-ink screen shows the thread. The demo: walk two units out of WiFi range and trade messages through a relay. A deep mesh-networking build for a long sprint.', 'Un conjunto de dispositivos de bolsillo que se pasan mensajes de texto cortos por radio de largo alcance cuando no hay internet ni cobertura celular. Cada nodo retransmite para sus vecinos, asi un mensaje salta por un campus o sendero, y una pantalla de tinta electronica muestra el hilo. La demo: aleja dos unidades del WiFi e intercambia mensajes a traves de un relevo. Construccion profunda de redes mesh para un sprint largo.', 'iot-hardware', '12-24h', 12, 24, 'advanced', '["sensors","arduino-rpi","wearables"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Garden Network of Sensor Stakes that Self-Heals', 'Red de Estacas Sensoras de Jardin que se Autorrepara', 'A spread of solar sensor stakes across a garden that report soil and light wirelessly and reroute around any dead node. Each stake samples its patch, relays through neighbors to a base, and the map shows which zones need water. The demo: pull one stake offline and watch the network reroute and keep reporting. A fuller resilient-sensing build for a multi-day sprint.', 'Un despliegue de estacas sensoras solares por un jardin que reportan tierra y luz de forma inalambrica y redirigen alrededor de cualquier nodo caido. Cada estaca muestrea su zona, retransmite por sus vecinos hasta una base y el mapa muestra que sectores necesitan agua. La demo: saca una estaca de linea y mira la red redirigir y seguir reportando. Construccion amplia de sensado resiliente para varios dias.', 'iot-hardware', '24-48h', 24, 48, 'advanced', '["sensors","energy-monitor","arduino-rpi","home-automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Calendar-Aware Focus Lamp that Guards Your Deep Work', 'Lampara de Foco con Agenda que Cuida tu Trabajo Profundo', 'An ambient lamp wired to your calendar that signals the room when you are about to be busy. It breathes calm green during free blocks, shifts amber as a meeting nears, and turns hard red five minutes before so housemates know not to interrupt. The demo: add a meeting and watch the lamp ramp toward red. A polished feed-driven ambient build for a multi-day sprint.', 'Una lampara de ambiente conectada a tu agenda que avisa a la sala cuando estas por estar ocupado. Respira un verde calmo en bloques libres, pasa a ambar al acercarse una reunion y se pone rojo intenso cinco minutos antes para que los demas no interrumpan. La demo: agrega una reunion y mira la lampara avanzar hacia el rojo. Construccion pulida de ambiente guiada por feed para varios dias.', 'iot-hardware', '24-48h', 24, 48, 'intermediate', '["lights","home-automation","sensors"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Home Energy Coach that Schedules Loads to Cut Bills', 'Coach de Energia del Hogar que Agenda Cargas y Baja Cuentas', 'A hub that watches your home''s power draw and nudges big appliances to run when electricity is cheapest. Current sensors track usage, a tariff feed marks low-price windows, and smart plugs delay the dishwasher or charger until the rate drops. The demo: simulate a price dip and watch a queued load fire automatically. A fuller optimization-and-control build for a multi-day sprint.', 'Un concentrador que vigila el consumo electrico del hogar y empuja a los electrodomesticos grandes a funcionar cuando la electricidad es mas barata. Sensores de corriente rastrean el uso, un feed de tarifas marca las ventanas de bajo precio y enchufes inteligentes demoran el lavavajillas o el cargador hasta que baja la tarifa. La demo: simula una caida de precio y mira dispararse una carga en cola. Construccion amplia de optimizacion y control para varios dias.', 'iot-hardware', '24-48h', 24, 48, 'advanced', '["energy-monitor","home-automation","sensors"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Search-and-Rescue Drone that Spots People by Heat', 'Dron de Busqueda y Rescate que Detecta Personas por Calor', 'A drone that sweeps a field on a grid and flags warm human-shaped blobs from a thermal camera to speed up a search. It flies an autonomous lawnmower pattern, marks heat hits on a live map, and drops a pin where a person likely is. The demo: hide a heat source in a room and watch the drone tag its location. A demanding autonomy-and-vision build for a multi-day sprint.', 'Un dron que barre un campo en grilla y marca manchas calidas con forma humana desde una camara termica para acelerar una busqueda. Vuela un patron autonomo de cortadora de cesped, marca los aciertos de calor en un mapa en vivo y deja un pin donde probablemente este una persona. La demo: esconde una fuente de calor en una sala y mira al dron etiquetar su ubicacion. Construccion exigente de autonomia y vision para varios dias.', 'iot-hardware', '24-48h', 24, 48, 'advanced', '["drones","sensors","robotics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Quadruped Walker that Learns to Cross Rough Ground', 'Caminante Cuadrupedo que Aprende a Cruzar Terreno Dificil', 'A four-legged robot that learns a stable gait and keeps walking even when the floor is uneven. Servo legs and an IMU close a balance loop, and a tuning routine adapts the stride when it stumbles on a ramp or obstacle. The demo: set it on a tilted board and watch it adjust its steps to stay upright. A heavy robotics-and-control build that earns a full multi-day sprint.', 'Un robot de cuatro patas que aprende un andar estable y sigue caminando aunque el piso sea irregular. Patas con servos y una IMU cierran un lazo de equilibrio, y una rutina de ajuste adapta la zancada cuando tropieza en una rampa u obstaculo. La demo: ponlo en una tabla inclinada y miralo ajustar sus pasos para mantenerse erguido. Construccion pesada de robotica y control que merece varios dias.', 'iot-hardware', '24-48h', 24, 48, 'advanced', '["robotics","sensors","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Sensor Vest that Maps a Workshop''s Noise and Fumes', 'Chaleco Sensor que Mapea Ruido y Gases del Taller', 'A wearable vest for shop workers that logs noise, gas, and temperature exposure across a shift and warns before limits are crossed. Onboard sensors sample continuously, a buzzer fires when a threshold nears, and the day''s exposure becomes a heatmap of the floor. The demo: walk past a loud or smoky spot and feel the warning, then see it on the map. A rich wearable-sensing build for a multi-day sprint.', 'Un chaleco wearable para operarios que registra exposicion a ruido, gases y temperatura durante un turno y avisa antes de cruzar los limites. Sensores a bordo muestrean de forma continua, un zumbador suena al acercarse un umbral y la exposicion del dia se vuelve un mapa de calor del taller. La demo: pasa junto a un punto ruidoso o con humo, senti la alerta y luego velo en el mapa. Construccion rica de sensado wearable para varios dias.', 'iot-hardware', '24-48h', 24, 48, 'advanced', '["wearables","sensors","energy-monitor"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Cron Expression Explainer with a Live Next-Runs Timeline', 'Explicador de expresiones cron con línea de próximas ejecuciones', 'Paste any cron expression and watch it decode into plain language plus a live timeline of the next ten fire times in your timezone. Tweak a field and the timeline reshuffles instantly so you can feel what ''*/15'' really means. A tight, visual single-screen build that saves everyone from second-guessing their scheduler syntax.', 'Pegá cualquier expresión cron y vela decodificarse en lenguaje claro junto a una línea de tiempo en vivo con las próximas diez ejecuciones en tu zona horaria. Cambiá un campo y la línea se reordena al instante para que sientas qué significa realmente ''*/15''. Una construcción visual de una sola pantalla que evita las dudas sobre la sintaxis del programador.', 'productivity-devtools', '1-3h', 1, 3, 'beginner', '["cli-tools","time-mgmt"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Git Branch Cleaner that Ranks Stale Branches by Risk', 'Limpiador de ramas Git que ordena ramas viejas por riesgo', 'A CLI that scans a repo''s branches and ranks them for safe deletion by combining last-commit age, whether they''re merged, and how far behind main they sit. It marks each one keep, archive, or delete with a one-line reason, then deletes in bulk on confirm. Perfect for the end-of-sprint cleanup nobody wants to do by hand.', 'Una CLI que escanea las ramas de un repo y las ordena para borrado seguro combinando la antigüedad del último commit, si están fusionadas y cuánto se atrasaron respecto de main. Marca cada una como conservar, archivar o borrar con un motivo de una línea, y borra en lote al confirmar. Ideal para la limpieza de fin de sprint que nadie quiere hacer a mano.', 'productivity-devtools', '3-6h', 3, 6, 'intermediate', '["cli-tools","automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Curl-to-Code Converter that Speaks Five Languages', 'Conversor de curl a código que habla cinco lenguajes', 'Paste a raw curl command and instantly get the equivalent request in Python, JavaScript, Go, Ruby, and PHP, with headers, auth, and body faithfully mapped. Toggle between fetch, requests, or net/http styles per language. A sharp single-feature tool that turns the copy-paste-from-docs ritual into one click.', 'Pegá un comando curl crudo y obtené al instante la petición equivalente en Python, JavaScript, Go, Ruby y PHP, con cabeceras, autenticación y cuerpo mapeados con fidelidad. Alterná entre estilos fetch, requests o net/http según el lenguaje. Una herramienta nítida de un solo objetivo que convierte el copiar-pegar de la documentación en un clic.', 'productivity-devtools', '3-6h', 3, 6, 'intermediate', '["api-tools","cli-tools"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Meeting-Cost Ticker that Bills the Room in Real Time', 'Contador de costo de reunión que factura a la sala en tiempo real', 'Drop in the attendees and their rough hourly rates, hit start, and a live ticker climbs by the second to show what the meeting is costing right now. When it crosses a budget line it flashes and nudges you to wrap up. A playful but pointed productivity tool that makes wasted time impossible to ignore.', 'Cargá a los asistentes y sus tarifas por hora aproximadas, dale a iniciar y un contador en vivo sube por segundo para mostrar cuánto cuesta la reunión ahora mismo. Cuando cruza un límite de presupuesto parpadea y te invita a cerrar. Una herramienta de productividad lúdica pero contundente que hace imposible ignorar el tiempo perdido.', 'productivity-devtools', '1-3h', 1, 3, 'beginner', '["time-mgmt","collaboration"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Regex Builder that Learns the Pattern from Examples', 'Constructor de regex que aprende el patrón desde ejemplos', 'Give a few strings that should match and a few that shouldn''t, and the tool synthesizes a regex that satisfies all of them, showing its work as it narrows down. Edit any example and the pattern re-derives live. It flips the painful direction of regex authoring: you describe the goal, not the syntax.', 'Dale unas cadenas que deberían coincidir y otras que no, y la herramienta sintetiza un regex que las satisface todas, mostrando su razonamiento mientras lo acota. Editá cualquier ejemplo y el patrón se vuelve a derivar en vivo. Invierte la dirección dolorosa de escribir regex: describís el objetivo, no la sintaxis.', 'productivity-devtools', '6-12h', 6, 12, 'advanced', '["cli-tools","testing"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Standup Generator that Drafts Your Update from Git and PRs', 'Generador de standup que redacta tu update desde Git y PRs', 'It reads yesterday''s commits, merged PRs, and closed issues across your repos, then drafts a clean yesterday/today/blockers standup in seconds. Reorder or trim with a keystroke before posting to Slack. A focused tool that kills the daily five minutes of staring blankly before standup.', 'Lee los commits de ayer, los PRs fusionados y los issues cerrados en tus repos, y luego redacta en segundos un standup limpio de ayer/hoy/bloqueos. Reordená o recortá con una tecla antes de publicarlo en Slack. Una herramienta enfocada que elimina los cinco minutos diarios de mirar la pantalla en blanco antes del standup.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["automation","collaboration","time-mgmt"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Mock API Server that Boots from a Pasted JSON Response', 'Servidor de API mock que arranca desde un JSON pegado', 'Paste an example JSON response and the tool spins up a live mock endpoint that serves it, infers query-param filtering, and fakes pagination automatically. Add latency or error rates with a slider to test how your frontend behaves. A demoable build that gets a frontend unblocked while the real backend is still cooking.', 'Pegá una respuesta JSON de ejemplo y la herramienta levanta un endpoint mock en vivo que la sirve, infiere el filtrado por query-params y simula paginación automáticamente. Agregá latencia o tasa de errores con un control deslizante para probar cómo se comporta tu frontend. Una construcción demostrable que desbloquea al frontend mientras el backend real aún se cocina.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["api-tools","testing"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Clipboard Manager that Auto-Tags Snippets by Type', 'Gestor de portapapeles que autoetiqueta fragmentos por tipo', 'A clipboard history that recognizes what you copied — a URL, a hex color, a code block, a tracking number — and files it under the right tag automatically. Search by type, pin favorites, and paste the third-to-last thing without breaking flow. A small daily-driver tool with a smart twist on a tired category.', 'Un historial de portapapeles que reconoce qué copiaste — una URL, un color hex, un bloque de código, un número de seguimiento — y lo archiva bajo la etiqueta correcta automáticamente. Buscá por tipo, fijá favoritos y pegá lo antepenúltimo sin romper tu flujo. Una pequeña herramienta de uso diario con un giro inteligente sobre una categoría agotada.', 'productivity-devtools', '3-6h', 3, 6, 'intermediate', '["automation","knowledge-mgmt"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Dotfiles Diff Viewer that Explains What Each Change Does', 'Visor de diffs de dotfiles que explica qué hace cada cambio', 'Point it at two versions of your shell or editor config and it shows a side-by-side diff annotated with plain-language notes on what each changed line actually does. Spot the alias you forgot you added or the risky option you toggled. A useful tool for anyone who migrates machines and fears their own config.', 'Apuntalo a dos versiones de tu config de shell o editor y muestra un diff lado a lado anotado con notas en lenguaje claro sobre qué hace realmente cada línea cambiada. Detectá el alias que olvidaste agregar o la opción riesgosa que activaste. Una herramienta útil para quien migra de máquina y le teme a su propia configuración.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["cli-tools","knowledge-mgmt"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Visual Pipeline Builder that Exports a Real GitHub Action', 'Constructor visual de pipelines que exporta un GitHub Action real', 'Drag steps onto a canvas — checkout, build, test, deploy — wire them together, set conditions, and the tool emits a valid, runnable GitHub Actions YAML. It validates as you go and flags steps that need secrets. A no-code front door to CI that produces real, editable config instead of a black box.', 'Arrastrá pasos a un lienzo — checkout, build, test, deploy — conectalos, definí condiciones y la herramienta genera un YAML de GitHub Actions válido y ejecutable. Valida sobre la marcha y marca los pasos que necesitan secretos. Una puerta de entrada no-code a CI que produce config real y editable en lugar de una caja negra.', 'productivity-devtools', '12-24h', 12, 24, 'advanced', '["no-code","automation","api-tools"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Focus Timer that Mutes Notifications Based on Calendar', 'Temporizador de foco que silencia notificaciones según tu agenda', 'A focus timer that reads your calendar and automatically protects free blocks: it enters do-not-disturb, silences chat, and reopens the moment a meeting starts. A live bar shows how much deep-work time you actually protected this week. A practical time-management tool that acts instead of just nagging.', 'Un temporizador de foco que lee tu agenda y protege automáticamente los bloques libres: entra en no molestar, silencia el chat y se reabre justo cuando empieza una reunión. Una barra en vivo muestra cuánto tiempo de trabajo profundo protegiste esta semana. Una herramienta práctica de gestión del tiempo que actúa en lugar de solo insistir.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["time-mgmt","automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('JSON-to-Type Generator for Five Typed Languages at Once', 'Generador de tipos desde JSON para cinco lenguajes a la vez', 'Paste a JSON blob and get clean type definitions for TypeScript, Go, Rust, Kotlin, and Python side by side, with sensible names inferred for nested objects and optional fields detected from nulls. Tweak a key and all five regenerate live. A tight tool that erases the tedium of hand-typing models from sample payloads.', 'Pegá un JSON y obtené definiciones de tipos limpias para TypeScript, Go, Rust, Kotlin y Python lado a lado, con nombres sensatos inferidos para objetos anidados y campos opcionales detectados a partir de nulls. Cambiá una clave y los cinco se regeneran en vivo. Una herramienta nítida que borra el tedio de escribir modelos a mano desde payloads de ejemplo.', 'productivity-devtools', '3-6h', 3, 6, 'intermediate', '["api-tools","cli-tools"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Commit Message Linter that Suggests the Conventional Type', 'Linter de mensajes de commit que sugiere el tipo convencional', 'A pre-commit hook that reads your staged diff and proposes a Conventional Commits message — guessing feat, fix, or refactor from what actually changed and drafting the summary line. Accept, edit, or override. A small automation that quietly keeps a whole team''s history clean and changelog-ready.', 'Un hook de pre-commit que lee tu diff en stage y propone un mensaje de Conventional Commits — adivinando feat, fix o refactor según lo que realmente cambió y redactando la línea de resumen. Aceptá, editá o anulá. Una pequeña automatización que mantiene en silencio el historial de todo un equipo limpio y listo para el changelog.', 'productivity-devtools', '3-6h', 3, 6, 'intermediate', '["automation","cli-tools"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Shared Scratchpad that Turns Pasted Errors into Tickets', 'Bloc compartido que convierte errores pegados en tickets', 'A team scratchpad where anyone pastes a stack trace and it auto-extracts the error type, file, and line, then offers a one-click button to file a deduplicated ticket. It links repeats together so the same crash never becomes five issues. A collaboration tool that captures the bug while it''s fresh.', 'Un bloc de equipo donde cualquiera pega un stack trace y se autoextrae el tipo de error, archivo y línea, y luego ofrece un botón de un clic para crear un ticket sin duplicados. Vincula las repeticiones para que el mismo crash nunca se convierta en cinco issues. Una herramienta de colaboración que captura el bug mientras está fresco.', 'productivity-devtools', '12-24h', 12, 24, 'intermediate', '["collaboration","knowledge-mgmt","automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Env-File Auditor that Flags Leaks Before You Commit', 'Auditor de archivos env que detecta fugas antes del commit', 'A CLI that scans your .env and staged files for real secrets — API keys, tokens, private URLs — using entropy and known patterns, and warns before anything risky lands in git. It suggests a sanitized .env.example automatically. A sharp safety tool that fits a short sprint and saves real embarrassment.', 'Una CLI que escanea tu .env y los archivos en stage en busca de secretos reales — claves de API, tokens, URLs privadas — usando entropía y patrones conocidos, y avisa antes de que algo riesgoso llegue a git. Sugiere un .env.example saneado automáticamente. Una herramienta de seguridad nítida que entra en un sprint corto y evita papelones reales.', 'productivity-devtools', '3-6h', 3, 6, 'intermediate', '["cli-tools","automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Keyboard-Shortcut Coach that Watches How You Actually Work', 'Coach de atajos de teclado que observa cómo trabajás de verdad', 'It watches the menu actions and mouse moves you repeat, then surfaces the exact keyboard shortcut that would have saved each one, ranked by how often you do it. A weekly card shows your top time-wasters and the keys to fix them. A productivity tool that teaches the shortcuts you''d never look up.', 'Observa las acciones de menú y los movimientos de mouse que repetís, y luego revela el atajo de teclado exacto que habría ahorrado cada uno, ordenados por frecuencia. Una tarjeta semanal muestra tus mayores fugas de tiempo y las teclas para resolverlas. Una herramienta de productividad que enseña los atajos que nunca buscarías.', 'productivity-devtools', '12-24h', 12, 24, 'intermediate', '["time-mgmt","automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('API Response Differ that Catches Breaking Changes', 'Comparador de respuestas de API que detecta cambios rompedores', 'Hit an endpoint on two environments, or before and after a deploy, and the tool diffs the JSON structurally — flagging removed fields, changed types, and new required keys as breaking, additive, or cosmetic. It produces a shareable report. A practical testing tool that catches the contract break before your clients do.', 'Pegale a un endpoint en dos entornos, o antes y después de un deploy, y la herramienta compara el JSON estructuralmente — marcando campos eliminados, tipos cambiados y nuevas claves requeridas como rompedores, aditivos o cosméticos. Genera un reporte para compartir. Una herramienta de testing práctica que atrapa la ruptura de contrato antes que tus clientes.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["api-tools","testing"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Readme Generator that Interviews Your Repo, Not You', 'Generador de readme que entrevista a tu repo, no a vos', 'Point it at a project and it inspects the package manifest, scripts, env vars, and folder layout to draft a real README — install steps, usage, and config table — without asking you a single question. Edit inline before it writes the file. A focused tool that makes the worst chore of shipping painless.', 'Apuntalo a un proyecto e inspecciona el manifiesto del paquete, los scripts, las variables de entorno y la estructura de carpetas para redactar un README real — pasos de instalación, uso y tabla de config — sin hacerte una sola pregunta. Editá en línea antes de que escriba el archivo. Una herramienta enfocada que vuelve indolora la peor tarea de publicar.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["knowledge-mgmt","automation","cli-tools"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Color-Contrast Picker that Locks Choices to Accessible Pairs', 'Selector de contraste de color que fija pares accesibles', 'A palette picker that only lets you choose foreground and background combos that pass WCAG contrast, nudging each swatch to the nearest compliant shade as you drag. It exports CSS variables and a preview card. A tight design-dev tool that bakes accessibility in instead of bolting it on later.', 'Un selector de paletas que solo te deja elegir combinaciones de texto y fondo que pasan el contraste WCAG, empujando cada muestra al tono compatible más cercano mientras arrastrás. Exporta variables CSS y una tarjeta de vista previa. Una herramienta de diseño-desarrollo nítida que integra la accesibilidad en vez de agregarla después.', 'productivity-devtools', '3-6h', 3, 6, 'beginner', '["no-code","cli-tools"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Time-Zone Meeting Finder that Shades Everyone''s Sleep Hours', 'Buscador de horarios entre zonas que sombrea las horas de sueño', 'Add teammates by city and a grid shades each person''s night, lunch, and core hours, then highlights the windows where everyone is comfortably awake. Drag a proposed slot and watch who it inconveniences light up. A clean scheduling tool that ends the painful timezone math for distributed teams.', 'Agregá compañeros por ciudad y una grilla sombrea la noche, el almuerzo y las horas centrales de cada persona, y luego resalta las ventanas en que todos están cómodamente despiertos. Arrastrá un horario propuesto y mirá iluminarse a quién incomoda. Una herramienta de agenda limpia que termina con la dolorosa matemática de zonas horarias para equipos distribuidos.', 'productivity-devtools', '3-6h', 3, 6, 'beginner', '["time-mgmt","collaboration"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Log Tail Viewer that Collapses Repeating Lines into Counts', 'Visor de logs que colapsa líneas repetidas en conteos', 'A live log viewer that folds bursts of near-identical lines into a single row with a running count and a sparkline, so a flood of the same warning stops drowning the signal. Click to expand, filter by level, and pin the rare error you care about. A focused tool that makes noisy logs readable.', 'Un visor de logs en vivo que pliega ráfagas de líneas casi idénticas en una sola fila con un conteo en curso y un sparkline, para que una inundación de la misma advertencia deje de ahogar la señal. Hacé clic para expandir, filtrá por nivel y fijá el error raro que te importa. Una herramienta enfocada que vuelve legibles los logs ruidosos.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["cli-tools","testing"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Browser-Tab Bankruptcy Tool that Groups Tabs by Task', 'Herramienta de quiebra de pestañas que las agrupa por tarea', 'When your tabs spiral out of control, this clusters them by topic from titles and domains, names each group, and lets you save a cluster as a session to reopen later — then closes the rest in one move. A satisfying single-feature tool for the chaos every researcher and developer lives in.', 'Cuando tus pestañas se descontrolan, esto las agrupa por tema a partir de títulos y dominios, nombra cada grupo y te deja guardar un grupo como sesión para reabrirlo después — y cierra el resto de un solo movimiento. Una herramienta de un solo objetivo y muy satisfactoria para el caos en que vive todo investigador y desarrollador.', 'productivity-devtools', '3-6h', 3, 6, 'intermediate', '["automation","knowledge-mgmt","time-mgmt"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('SQL Query Explainer that Draws the Joins as a Diagram', 'Explicador de consultas SQL que dibuja los joins como diagrama', 'Paste a gnarly SQL query and the tool draws the tables, joins, and filters as a clear diagram, then narrates what each clause contributes to the result. Hover a join to see which keys connect. A learning-and-debugging tool that makes an inherited 200-line query suddenly make sense.', 'Pegá una consulta SQL enredada y la herramienta dibuja las tablas, joins y filtros como un diagrama claro, y luego narra qué aporta cada cláusula al resultado. Pasá el cursor sobre un join para ver qué claves conectan. Una herramienta de aprendizaje y depuración que hace que una consulta heredada de 200 líneas de pronto tenga sentido.', 'productivity-devtools', '6-12h', 6, 12, 'advanced', '["cli-tools","knowledge-mgmt"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Webhook Inspector that Replays Captured Payloads on Demand', 'Inspector de webhooks que reenvía payloads capturados a demanda', 'Give a third-party service a temporary URL and the tool captures every incoming webhook with full headers and body, pretty-printed and searchable. Replay any captured payload to your local server with one click to debug without re-triggering the source. A practical API tool that tames the worst part of integration work.', 'Dale a un servicio externo una URL temporal y la herramienta captura cada webhook entrante con cabeceras y cuerpo completos, formateados y buscables. Reenviá cualquier payload capturado a tu servidor local con un clic para depurar sin volver a disparar la fuente. Una herramienta de API práctica que domina la peor parte del trabajo de integración.', 'productivity-devtools', '12-24h', 12, 24, 'intermediate', '["api-tools","testing","automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Task Estimator that Calibrates Against Your Past Guesses', 'Estimador de tareas que se calibra con tus pronósticos pasados', 'Log a task estimate and its actual time, and the tool learns your personal bias — say you always underestimate UI work by 40% — then adjusts your future guesses automatically. A chart shows your accuracy trending over time. A quietly powerful time-management tool that fixes estimation by confronting the data.', 'Registrá la estimación de una tarea y su tiempo real, y la herramienta aprende tu sesgo personal — por ejemplo, que siempre subestimás el trabajo de UI un 40% — y luego ajusta tus futuros pronósticos automáticamente. Un gráfico muestra tu precisión mejorando con el tiempo. Una herramienta de gestión del tiempo discreta y potente que arregla la estimación confrontando los datos.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["time-mgmt","automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Diff-Aware Test Picker that Runs Only What Your Change Touches', 'Selector de tests por diff que corre solo lo que tu cambio toca', 'It maps which tests exercise which source files, then on each change runs only the tests that could possibly break — turning a ten-minute suite into a ten-second check. A fallback runs everything before merge. A serious devtool that makes the inner loop fast without sacrificing the safety net.', 'Mapea qué tests ejercitan qué archivos fuente, y luego en cada cambio corre solo los tests que podrían romperse — convirtiendo una suite de diez minutos en una verificación de diez segundos. Un respaldo corre todo antes del merge. Un devtool serio que acelera el ciclo interno sin sacrificar la red de seguridad.', 'productivity-devtools', '24-48h', 24, 48, 'advanced', '["testing","automation","cli-tools"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Markdown Table Editor that Keeps Columns Aligned as You Type', 'Editor de tablas markdown que mantiene columnas alineadas al tipear', 'Editing markdown tables by hand is misery; this gives you a spreadsheet-style grid that re-renders perfectly aligned markdown live as you type, with tab-to-next-cell and paste-from-Excel support. Copy the clean source out when done. A small, sharp tool that removes a daily papercut for anyone who writes docs.', 'Editar tablas markdown a mano es una tortura; esto te da una grilla estilo planilla que regenera markdown perfectamente alineado en vivo mientras tipeás, con tab-a-siguiente-celda y pegado desde Excel. Copiá el código limpio al terminar. Una herramienta pequeña y nítida que elimina una molestia diaria para todo el que escribe documentación.', 'productivity-devtools', '1-3h', 1, 3, 'beginner', '["knowledge-mgmt","no-code"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('PR Review Router that Assigns Reviewers by Code Ownership', 'Enrutador de revisiones que asigna revisores por dominio del código', 'When a PR opens, it looks at which files changed and who has the deepest git history in them, then suggests the best-matched reviewers and warns when only one person knows that area. A heatmap reveals bus-factor risks across the repo. A collaboration tool that gets reviews to the right eyes faster.', 'Cuando se abre un PR, mira qué archivos cambiaron y quién tiene el historial de git más profundo en ellos, y luego sugiere los revisores mejor calzados y avisa cuando solo una persona conoce esa área. Un mapa de calor revela riesgos de bus-factor en todo el repo. Una herramienta de colaboración que lleva las revisiones a los ojos correctos más rápido.', 'productivity-devtools', '12-24h', 12, 24, 'advanced', '["collaboration","automation","api-tools"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Snippet Runner that Executes Code Blocks Inside Your Notes', 'Ejecutor de fragmentos que corre bloques de código en tus notas', 'A notebook where any fenced code block in your markdown notes becomes runnable in place, showing output beneath it and remembering variables across blocks. Great for runbooks where the commands should actually work. A knowledge-management tool that keeps your docs honest by making them executable.', 'Un cuaderno donde cualquier bloque de código en tus notas markdown se vuelve ejecutable en el lugar, mostrando la salida debajo y recordando variables entre bloques. Ideal para runbooks donde los comandos deberían funcionar de verdad. Una herramienta de gestión del conocimiento que mantiene honesta tu documentación al volverla ejecutable.', 'productivity-devtools', '12-24h', 12, 24, 'advanced', '["knowledge-mgmt","cli-tools","automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Flaky-Test Detective that Quarantines Unreliable Tests', 'Detective de tests inestables que pone en cuarentena los poco fiables', 'It reruns your test suite across seeds and orders to surface tests that pass and fail nondeterministically, ranks them by flakiness, and auto-quarantines the worst so CI stops lying to you. A report links each flaky test to the likely shared-state culprit. A serious testing tool that restores trust in your green checks.', 'Reejecuta tu suite con distintas semillas y órdenes para revelar tests que pasan y fallan de forma no determinista, los ordena por inestabilidad y pone en cuarentena los peores para que CI deje de mentirte. Un reporte vincula cada test inestable con el probable culpable de estado compartido. Una herramienta de testing seria que restaura la confianza en tus chequeos verdes.', 'productivity-devtools', '24-48h', 24, 48, 'advanced', '["testing","automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Inbox Triage Sorter that Drafts Replies by Intent', 'Clasificador de bandeja que redacta respuestas según la intención', 'It reads unread mail, buckets each message by what it wants from you — decision, FYI, scheduling, or ask — and drafts a fitting reply you can send or tweak. A morning digest shows only what truly needs you. A practical productivity tool that turns inbox dread into a five-minute pass.', 'Lee el correo no leído, clasifica cada mensaje según lo que quiere de vos — decisión, informativo, agenda o pedido — y redacta una respuesta acorde que podés enviar o ajustar. Un resumen matutino muestra solo lo que realmente te necesita. Una herramienta de productividad práctica que convierte el temor a la bandeja en una pasada de cinco minutos.', 'productivity-devtools', '12-24h', 12, 24, 'intermediate', '["automation","time-mgmt"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Photo Menu Reader that Speaks Dishes for Blind Diners', 'Lector de menús por foto que dicta los platos a comensales ciegos', 'Point a phone at any printed restaurant menu and the tool reads each section aloud, lets you swipe between dishes, and announces prices and allergen hints. It reflows the cramped layout into a clean spoken order so a blind diner can choose without help. A single-screen build whose demo is snapping a real menu and hearing it come alive.', 'Apunta el teléfono a cualquier menú impreso y la herramienta lee cada sección en voz alta, permite deslizar entre platos y anuncia precios y alérgenos. Reorganiza el diseño apretado en un orden hablado claro para que una persona ciega elija sin ayuda. Una construcción de una pantalla cuya demo es fotografiar un menú real y oírlo cobrar vida.', 'social-impact', '3-6h', 3, 6, 'intermediate', '["accessibility","nonprofit"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Plain-Language Rewriter for Dense Government Letters', 'Reescritor en lenguaje sencillo para cartas oficiales densas', 'Paste an intimidating bureaucratic letter and get back a plain-language version, a deadline highlighted in red, and a checklist of exactly which documents you must bring. It works in the reader''s own language so newcomers stop missing benefits over jargon. The demo takes a real tax or immigration notice and makes it suddenly understandable on one screen.', 'Pega una carta burocrática intimidante y recibe una versión en lenguaje sencillo, la fecha límite resaltada en rojo y una lista de qué documentos llevar. Funciona en el idioma del lector para que los recién llegados dejen de perder beneficios por la jerga. La demo toma un aviso fiscal o migratorio real y lo vuelve comprensible en una pantalla.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["civic-tech","accessibility","language"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Caption Overlay that Floats on Top of Any Video Call', 'Subtítulos flotantes que se superponen a cualquier videollamada', 'A small always-on-top window that captions whatever audio plays on screen, so a deaf user gets live subtitles on any meeting tool without plugins. It tags who is speaking and keeps a scrollback so you can catch a line you missed. The demo runs it beside a real call and shows captions tracking the conversation word by word.', 'Una pequeña ventana siempre visible que subtitula el audio que suene en pantalla, dando a un usuario sordo subtítulos en vivo en cualquier herramienta de reunión sin complementos. Etiqueta quién habla y guarda un historial para recuperar una frase perdida. La demo lo corre junto a una llamada real y muestra los subtítulos siguiendo la conversación palabra por palabra.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["accessibility","language"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('SMS Quiz Bot that Teaches Literacy on a Basic Phone', 'Bot de quiz por SMS que enseña alfabetización en un teléfono básico', 'A learning service that runs entirely over text messages, sending one short reading or math question a day and grading the reply, so people without smartphones or data can keep studying. It adapts difficulty based on past answers and works on the cheapest feature phone. The demo texts a question to a real number and shows the lesson advancing.', 'Un servicio de aprendizaje que funciona solo por mensajes de texto: envía una pregunta corta de lectura o matemática al día y corrige la respuesta, para que quienes no tienen smartphone ni datos sigan estudiando. Ajusta la dificultad según respuestas previas y corre en el celular más básico. La demo envía una pregunta a un número real y muestra la lección avanzando.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["education","finance-inclusion"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Disaster Shelter Map that Works Fully Offline', 'Mapa de refugios ante desastres que funciona sin conexión', 'An app that caches nearby shelters, water points, and clinics so it stays useful when the network drops during a flood or quake. It shows walking routes, capacity status, and a one-tap SOS that queues until signal returns. The demo flips the phone to airplane mode and proves the map still guides you to the closest open shelter.', 'Una app que guarda en caché refugios, puntos de agua y clínicas cercanas para seguir siendo útil cuando la red cae durante una inundación o sismo. Muestra rutas a pie, estado de capacidad y un SOS de un toque que se encola hasta recuperar señal. La demo pone el teléfono en modo avión y prueba que el mapa aún te guía al refugio abierto más cercano.', 'social-impact', '12-24h', 12, 24, 'intermediate', '["disaster-response","civic-tech"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Pothole and Hazard Reporter that Routes to the Right Office', 'Reportador de baches y peligros que llega a la oficina correcta', 'Snap a photo of a broken streetlight or pothole and the tool geotags it, classifies the issue, and drafts a formal report pre-addressed to the responsible city department. Residents track status and see clusters of unfixed problems on a public map. The demo photographs a hazard and produces a ready-to-send complaint in seconds.', 'Fotografía una luminaria rota o un bache y la herramienta lo geolocaliza, clasifica el problema y redacta un reporte formal dirigido al departamento municipal responsable. Los vecinos siguen el estado y ven cúmulos de problemas sin resolver en un mapa público. La demo fotografía un peligro y genera una queja lista para enviar en segundos.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["civic-tech","disaster-response"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Voice-First Banking Coach for First-Time Account Holders', 'Guía bancaria por voz para quienes abren su primera cuenta', 'A spoken assistant that walks unbanked users through opening and using an account, explaining fees, interest, and scams in everyday words and their local language. It role-plays an ATM or transfer so people practice before doing it for real. The demo has a judge ask a money question by voice and hear a clear, jargon-free answer.', 'Un asistente hablado que guía a personas no bancarizadas para abrir y usar una cuenta, explicando comisiones, intereses y estafas en palabras cotidianas y su idioma local. Simula un cajero o una transferencia para practicar antes de hacerlo en serio. La demo deja que un juez haga una pregunta de dinero por voz y oiga una respuesta clara y sin jerga.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["finance-inclusion","accessibility","language"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Daily Check-In Caller that Alerts Family if Grandma Misses It', 'Llamada de chequeo diario que avisa a la familia si la abuela falta', 'An automated friendly call rings an elderly relative each day; one button press marks them safe, and if they miss it the system escalates to family with the last-known status. No app to learn, just a phone call they already understand. The demo simulates a missed check-in and shows the alert reaching a caregiver minutes later.', 'Una llamada amable automática suena a un familiar mayor cada día; un botón los marca a salvo y, si no responden, el sistema escala a la familia con el último estado conocido. Sin app que aprender, solo una llamada que ya entienden. La demo simula un chequeo perdido y muestra la alerta llegando a un cuidador minutos después.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["elderly","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Sign-Language Alphabet Tutor with Live Webcam Scoring', 'Tutor del alfabeto en lengua de señas con puntuación por webcam', 'A webcam tutor for finger-spelling that detects your hand shape, scores it against the target letter, and runs drills that speed up as you improve. It turns learning sign language into a quick daily game with instant feedback. The demo has you spell a short word on camera and watch the accuracy meter react in real time.', 'Un tutor por webcam para el deletreo manual que detecta la forma de tu mano, la puntúa contra la letra objetivo y propone ejercicios que aceleran a medida que mejorás. Convierte aprender lengua de señas en un juego diario rápido con retroalimentación instantánea. La demo te hace deletrear una palabra corta en cámara y ver el medidor de precisión reaccionar en vivo.', 'social-impact', '6-12h', 6, 12, 'advanced', '["accessibility","education","language"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Color-Blind Mode that Recolors Any Chart in the Browser', 'Modo daltónico que recolorea cualquier gráfico en el navegador', 'A browser extension that detects charts and maps on a page and recolors them into a palette safe for the user''s specific color-blindness, adding patterns and labels where hues collide. It fixes graphs nobody designed for them. The demo loads a real dashboard and toggles it into a fully legible version on the spot.', 'Una extensión de navegador que detecta gráficos y mapas en una página y los recolorea a una paleta segura para el tipo de daltonismo del usuario, agregando patrones y etiquetas donde los tonos chocan. Arregla gráficos que nadie diseñó para ellos. La demo carga un panel real y lo convierte en una versión totalmente legible al instante.', 'social-impact', '3-6h', 3, 6, 'intermediate', '["accessibility","civic-tech"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Know-Your-Rights Card Generator for a Police Stop', 'Generador de tarjetas de derechos para un control policial', 'Pick your country and situation and the tool prints a wallet card and a lock-screen image listing your rights and the exact phrases to say, in two languages side by side. It works offline so it is there when you need it most. The demo selects a scenario and produces a clear, shareable rights card in seconds.', 'Elegí tu país y situación y la herramienta genera una tarjeta de billetera y una imagen de pantalla de bloqueo con tus derechos y las frases exactas que decir, en dos idiomas lado a lado. Funciona sin conexión para estar ahí cuando más lo necesitás. La demo elige un escenario y produce una tarjeta de derechos clara y compartible en segundos.', 'social-impact', '3-6h', 3, 6, 'beginner', '["civic-tech","language"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Food-Bank Matchmaker that Pairs Surplus Stores with Pantries', 'Conector de bancos de alimentos entre comercios con excedente y despensas', 'A service where a bakery or grocer posts soon-to-expire food and nearby pantries claim it, with pickup windows and route hints to cut waste and feed people fast. It ranks matches by distance and quantity so the most food moves with the least driving. The demo posts a surplus batch and watches a pantry claim it live.', 'Un servicio donde una panadería o tienda publica comida por vencer y las despensas cercanas la reclaman, con ventanas de retiro y rutas sugeridas para reducir el desperdicio y alimentar gente rápido. Ordena las coincidencias por distancia y cantidad para mover más comida con menos viajes. La demo publica un excedente y ve a una despensa reclamarlo en vivo.', 'social-impact', '12-24h', 12, 24, 'intermediate', '["nonprofit","civic-tech"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Image-to-Description Reader for Blind Web Browsing', 'Lector de imagen a descripción para navegar la web sin visión', 'A browser tool that narrates the meaningful images on any page in natural language, describing charts, photos, and buttons that ship with no alt text. A blind user finally hears what a page actually shows, not just its links. The demo lands on an image-heavy news site and reads its visuals aloud in a clear, ordered pass.', 'Una herramienta de navegador que narra en lenguaje natural las imágenes relevantes de cualquier página, describiendo gráficos, fotos y botones que vienen sin texto alternativo. Un usuario ciego al fin oye lo que la página realmente muestra, no solo sus enlaces. La demo entra a un sitio de noticias lleno de imágenes y lee sus visuales en voz alta de forma ordenada.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["accessibility","language"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Crowd-Mapped Wheelchair Accessibility Layer for Streets', 'Capa colaborativa de accesibilidad en silla de ruedas para calles', 'An app where users tag curb cuts, step-free entrances, and broken ramps, building a map that routes wheelchair users around obstacles a normal map ignores. Each report adds a photo and a confidence score so the data stays trustworthy. The demo plans a route across town that avoids stairs and shows why each detour exists.', 'Una app donde los usuarios marcan rebajes de cordón, entradas sin escalones y rampas rotas, armando un mapa que guía a usuarios de silla de ruedas evitando obstáculos que un mapa común ignora. Cada reporte suma una foto y un puntaje de confianza para que el dato sea fiable. La demo planea una ruta por la ciudad que evita escaleras y explica cada desvío.', 'social-impact', '12-24h', 12, 24, 'intermediate', '["accessibility","civic-tech"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Bill Explainer that Turns Local Legislation into a Summary', 'Explicador de proyectos de ley que resume la legislación local', 'Feed it a pending bill or council agenda and it returns a neutral plain-language summary, who it helps or hurts, and how to submit a public comment before the vote. It surfaces the items buried in hundred-page PDFs that actually affect your block. The demo loads a real ordinance and shows the digestible version beside the original.', 'Cargale un proyecto de ley o agenda del concejo y devuelve un resumen neutral en lenguaje sencillo, a quién beneficia o perjudica y cómo enviar un comentario público antes de la votación. Saca a la luz los puntos enterrados en PDFs de cien páginas que de verdad afectan tu barrio. La demo carga una ordenanza real y muestra la versión digerible junto al original.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["civic-tech","education"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Picture-Based Symptom Translator for the ER Language Gap', 'Traductor de síntomas por imágenes para la barrera idiomática en urgencias', 'A tap-the-picture board that lets a patient who shares no language with staff point to body parts, pain levels, and timing, then prints a structured summary for the doctor. It bridges the dangerous gap when no interpreter is available. The demo plays a patient with no shared language and produces a clear clinical handoff in under a minute.', 'Un tablero de tocar imágenes que permite a un paciente sin idioma común con el personal señalar partes del cuerpo, niveles de dolor y tiempos, y luego imprime un resumen estructurado para el médico. Cierra la peligrosa brecha cuando no hay intérprete. La demo simula un paciente sin idioma compartido y genera un parte clínico claro en menos de un minuto.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["language","accessibility","nonprofit"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Big-Button Video Caller Built for Tech-Shy Elders', 'Videollamadas de botones grandes pensadas para mayores poco tecnológicos', 'A stripped-down calling app showing only large photos of loved ones; one tap starts a video call with no menus, accounts, or app-switching to get lost in. Family configures it remotely so the elder never touches settings. The demo hands a judge the simplest possible screen and connects a call in a single tap.', 'Una app de llamadas minimalista que muestra solo fotos grandes de los seres queridos; un toque inicia una videollamada sin menús, cuentas ni cambios de app donde perderse. La familia la configura de forma remota para que el mayor nunca toque los ajustes. La demo entrega al juez la pantalla más simple posible y conecta una llamada con un solo toque.', 'social-impact', '6-12h', 6, 12, 'beginner', '["elderly","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Volunteer Shift Matcher that Slots Skills to Nonprofit Gaps', 'Asignador de turnos de voluntariado que cruza talentos con vacíos de ONGs', 'Volunteers list skills and free hours; nonprofits post needs, and the tool auto-matches and fills the schedule so coordinators stop juggling spreadsheets. It flags coverage gaps and sends reminders to cut no-shows. The demo posts an urgent need and watches qualified volunteers get matched and confirmed within the same screen.', 'Los voluntarios listan habilidades y horas libres; las ONGs publican necesidades y la herramienta empareja y completa el cronograma para que los coordinadores dejen las planillas. Marca vacíos de cobertura y envía recordatorios para reducir ausencias. La demo publica una necesidad urgente y ve a voluntarios calificados emparejados y confirmados en la misma pantalla.', 'social-impact', '12-24h', 12, 24, 'intermediate', '["nonprofit","civic-tech"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Family-Reunification Board for People Separated in a Crisis', 'Tablero de reunificación familiar para personas separadas en una crisis', 'A lightweight registry where displaced people post I am safe and others search by name, photo, or last location to reconnect after a disaster. It dedupes entries and works on slow connections in a shelter. The demo registers a missing person and shows a match surfacing as a relative searches from another device.', 'Un registro liviano donde personas desplazadas publican estoy a salvo y otros buscan por nombre, foto o última ubicación para reconectarse tras un desastre. Deduplica entradas y funciona en conexiones lentas dentro de un refugio. La demo registra a una persona perdida y muestra una coincidencia apareciendo mientras un familiar busca desde otro dispositivo.', 'social-impact', '12-24h', 12, 24, 'intermediate', '["disaster-response","nonprofit"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Reading-Buddy App that Listens to a Kid and Coaches Aloud', 'App compañera de lectura que escucha a un niño y lo guía en voz alta', 'A child reads a story aloud and the app follows along, gently catching stumbles, sounding out hard words, and cheering progress, giving every kid a patient tutor at home. It tracks which words trip them up over time. The demo has someone read a passage and watch the app highlight and help on the exact words missed.', 'Un niño lee un cuento en voz alta y la app lo sigue, detectando tropiezos con suavidad, pronunciando palabras difíciles y celebrando los avances, dando a cada chico un tutor paciente en casa. Registra qué palabras le cuestan con el tiempo. La demo hace que alguien lea un pasaje y ve a la app resaltar y ayudar en las palabras exactas que falló.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["education","accessibility","language"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Benefits Finder that Checks Which Aid Programs You Qualify For', 'Buscador de beneficios que detecta para qué ayudas calificás', 'Answer a few plain questions and the tool screens you against local aid, food, and housing programs, then lists what you likely qualify for with the steps to apply. It cuts through scattered government sites that hide real help. The demo fills a short profile and instantly returns a ranked list of programs worth pursuing.', 'Respondé unas preguntas simples y la herramienta te evalúa contra programas locales de ayuda, alimentos y vivienda, y luego lista para cuáles probablemente calificás con los pasos para postularte. Atraviesa los sitios oficiales dispersos que esconden la ayuda real. La demo completa un perfil corto y devuelve al instante una lista ordenada de programas que vale la pena seguir.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["finance-inclusion","civic-tech"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Scam-SMS Detector that Warns Elders Before They Tap a Link', 'Detector de SMS estafa que avisa a mayores antes de tocar un enlace', 'A simple filter that reads incoming texts, flags likely scams in big friendly type, and explains the red flags in one line an elder can trust. It learns from reports so new scam patterns spread fast across users. The demo feeds a real phishing text and shows a clear warning before any link gets tapped.', 'Un filtro simple que lee los textos entrantes, marca probables estafas en letra grande y amable y explica las señales de alerta en una línea que un mayor pueda confiar. Aprende de los reportes para que los nuevos patrones de estafa se difundan rápido entre usuarios. La demo introduce un texto de phishing real y muestra una advertencia clara antes de tocar ningún enlace.', 'social-impact', '3-6h', 3, 6, 'intermediate', '["elderly","finance-inclusion"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Donation Transparency Tracker that Shows Where Each Dollar Goes', 'Rastreador de transparencia que muestra a dónde va cada peso donado', 'A widget a nonprofit embeds so donors follow their gift from received to spent, with categorized milestones and photos instead of a vague thank-you. It rebuilds trust by making impact visible per donation. The demo follows a sample gift through its journey and shows exactly what it funded.', 'Un widget que una ONG incrusta para que los donantes sigan su aporte desde recibido hasta gastado, con hitos categorizados y fotos en vez de un agradecimiento vago. Reconstruye la confianza haciendo visible el impacto por donación. La demo sigue un aporte de ejemplo a través de su recorrido y muestra exactamente qué financió.', 'social-impact', '12-24h', 12, 24, 'intermediate', '["nonprofit","civic-tech","finance-inclusion"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('One-Page Resume Builder that Speaks the Local Job Market', 'Armador de currículum de una página que habla el mercado laboral local', 'A guided builder for first-time or returning job seekers that turns answers into a clean one-page resume and rewrites it for each posting using the keywords local employers actually scan. It removes the blank-page paralysis. The demo answers a handful of prompts and exports a polished, role-tailored resume in minutes.', 'Un armador guiado para quienes buscan su primer empleo o reingresan que convierte respuestas en un currículum limpio de una página y lo reescribe por aviso usando las palabras clave que los empleadores locales realmente buscan. Elimina la parálisis de la hoja en blanco. La demo responde unas pocas preguntas y exporta un currículum pulido y adaptado al puesto en minutos.', 'social-impact', '3-6h', 3, 6, 'beginner', '["finance-inclusion","education"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Easy-Read Rewriter for People with Cognitive Disabilities', 'Reescritor de lectura fácil para personas con discapacidad cognitiva', 'Paste any article and get an easy-read version with short sentences, defined hard words, and a supporting icon per idea, following plain-language standards for cognitive accessibility. It opens dense content to readers usually left out. The demo transforms a complicated notice into a calm, illustrated page anyone can follow.', 'Pega cualquier artículo y obtené una versión de lectura fácil con frases cortas, palabras difíciles definidas y un ícono de apoyo por idea, siguiendo estándares de lenguaje sencillo para accesibilidad cognitiva. Abre el contenido denso a lectores normalmente excluidos. La demo transforma un aviso complicado en una página tranquila e ilustrada que cualquiera puede seguir.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["accessibility","education","language"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Mesh Chat that Keeps a Neighborhood Talking When Towers Fail', 'Chat en malla que mantiene al barrio comunicado si caen las antenas', 'A phone-to-phone messaging app that hops messages device to device over local radio, so a neighborhood can coordinate during an outage with no cell network. It relays SOS and resource notes across the mesh until one phone reaches the internet. The demo turns off all networks and passes a message across several phones in the room.', 'Una app de mensajería de teléfono a teléfono que salta mensajes de dispositivo en dispositivo por radio local, para que un barrio se coordine durante un corte sin red celular. Retransmite SOS y notas de recursos por la malla hasta que un teléfono alcanza internet. La demo apaga todas las redes y pasa un mensaje entre varios teléfonos de la sala.', 'social-impact', '24-48h', 24, 48, 'advanced', '["disaster-response","civic-tech"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Live Captions on Smart Glasses for Conversations in Noise', 'Subtítulos en vivo en gafas inteligentes para charlas en entornos ruidosos', 'A wearable display that captions whoever you are facing in real time, so a hard-of-hearing person follows a noisy group chat without staring at a phone. It separates speakers and keeps text in your line of sight. The demo holds a conversation in a loud room and shows captions floating in the glasses keeping pace.', 'Una pantalla vestible que subtitula en tiempo real a quien tenés enfrente, para que una persona con baja audición siga una charla grupal ruidosa sin mirar el teléfono. Separa hablantes y mantiene el texto en tu línea de visión. La demo sostiene una conversación en una sala ruidosa y muestra los subtítulos flotando en las gafas siguiendo el ritmo.', 'social-impact', '24-48h', 24, 48, 'advanced', '["accessibility","language"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Quick Petition Maker that Verifies and Counts Real Signatures', 'Creador rápido de peticiones que verifica y cuenta firmas reales', 'Spin up a local petition in minutes with a shareable link, light verification to block bots, and a live counter residents and officials can both trust. It turns a kitchen-table concern into organized pressure fast. The demo creates a cause, signs it from a phone, and watches the verified tally tick up in real time.', 'Creá una petición local en minutos con un enlace compartible, verificación liviana para frenar bots y un contador en vivo que tanto vecinos como funcionarios puedan confiar. Convierte una preocupación de sobremesa en presión organizada rápido. La demo crea una causa, la firma desde un teléfono y ve el conteo verificado subir en tiempo real.', 'social-impact', '3-6h', 3, 6, 'beginner', '["civic-tech","nonprofit"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Microloan Circle App for Communities Without Bank Access', 'App de ronda de microcréditos para comunidades sin acceso bancario', 'Digitizes the rotating savings circle: members pool a fixed amount each cycle and take turns receiving the pot, with transparent rules and reminders that build credit history. It formalizes a trusted tradition so it scales beyond a single village. The demo runs a small circle through a cycle and shows the payout and ledger update.', 'Digitaliza la ronda de ahorro rotativa: los miembros aportan un monto fijo cada ciclo y por turnos reciben el pozo, con reglas transparentes y recordatorios que construyen historial crediticio. Formaliza una tradición de confianza para que escale más allá de un solo pueblo. La demo corre una ronda pequeña por un ciclo y muestra el pago y la actualización del registro.', 'social-impact', '12-24h', 12, 24, 'intermediate', '["finance-inclusion","nonprofit"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Endangered-Language Phrasebook Recorded by Native Speakers', 'Frasario de lengua en peligro grabado por hablantes nativos', 'A community tool where elders record words and phrases in a threatened language, tagged by meaning and context, building a living phrasebook learners can browse and repeat. It preserves pronunciation that text alone loses. The demo records a phrase from a speaker and shows it instantly searchable with audio for a learner to practice.', 'Una herramienta comunitaria donde los mayores graban palabras y frases en una lengua amenazada, etiquetadas por significado y contexto, armando un frasario vivo que los aprendices recorren y repiten. Preserva la pronunciación que el texto solo pierde. La demo graba una frase de un hablante y la muestra al instante buscable con audio para que un aprendiz practique.', 'social-impact', '12-24h', 12, 24, 'intermediate', '["language","education","nonprofit"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Tap-to-Speak Communication Board for Nonverbal Users', 'Tablero de comunicación de tocar para hablar para personas no verbales', 'A customizable board of symbols a nonverbal child or adult taps to build spoken sentences, with quick phrases caregivers can add for daily routines. It gives a voice without costly dedicated devices. The demo builds a sentence by tapping icons and hears it spoken aloud in a natural voice on a plain tablet.', 'Un tablero personalizable de símbolos que un niño o adulto no verbal toca para construir frases habladas, con frases rápidas que los cuidadores agregan para rutinas diarias. Da una voz sin dispositivos dedicados costosos. La demo arma una frase tocando íconos y la oye pronunciada en voz natural en una tablet común.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["accessibility","language","elderly"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Scrollytelling Builder that Turns a CSV into a Story', 'Constructor de scrollytelling que convierte un CSV en una historia', 'Drop in a CSV and the tool generates a scroll-driven data story where each chart animates and annotates itself as the reader scrolls past it. You pick the column to highlight and a narrative beat snaps into place. A single-screen build that nails the wow factor of scrollytelling without a full pipeline. The demo scrolls through a finished story live.', 'Sueltas un CSV y la herramienta genera una historia de datos guiada por scroll donde cada gráfico se anima y se anota a sí mismo a medida que el lector lo recorre. Eliges la columna a destacar y un momento narrativo encaja en su lugar. Una construcción de una sola pantalla que logra el efecto sorpresa del scrollytelling sin un pipeline completo. La demo recorre una historia terminada en vivo.', 'web-frontend', '3-6h', 3, 6, 'intermediate', '["dataviz","animation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Browser Extension that Reading-Levels Any Article Inline', 'Extensión que mide el nivel de lectura de cualquier artículo en línea', 'A browser extension that highlights each paragraph of an article by reading difficulty, painting hard sentences red and easy ones green right on the page. Hover a flagged sentence to see a plainer rewrite suggestion. A tight single-feature hack that makes dense writing visible at a glance. The demo toggles the overlay on a real news page.', 'Una extensión de navegador que resalta cada párrafo de un artículo según su dificultad de lectura, pintando de rojo las frases difíciles y de verde las fáciles directamente en la página. Pasas el cursor sobre una frase marcada para ver una reescritura más simple. Un hack de una sola función que hace visible la escritura densa de un vistazo. La demo activa la superposición en una página de noticias real.', 'web-frontend', '3-6h', 3, 6, 'intermediate', '["browser-extension","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Live Cursor Party Layer You Drop into Any Web Page', 'Capa de cursores en vivo que agregas a cualquier página web', 'A tiny script that adds shared, named cursors to any page over a link, so visitors see each other move and click in real time. Add a quick reaction emoji that floats up where you click. The whole charm is turning a static page into a shared room with one snippet. The demo opens two browsers and watches cursors chase each other.', 'Un script diminuto que agrega cursores compartidos y con nombre a cualquier página mediante un enlace, para que los visitantes se vean moverse y hacer clic en tiempo real. Agrega un emoji de reacción que flota donde haces clic. Todo el encanto está en convertir una página estática en una sala compartida con un solo fragmento. La demo abre dos navegadores y mira los cursores perseguirse.', 'web-frontend', '3-6h', 3, 6, 'intermediate', '["real-time","animation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Color Palette Extractor that Grades Contrast as You Go', 'Extractor de paletas que califica el contraste sobre la marcha', 'Upload an image or paste a screenshot and the tool pulls a palette, then live-grades every text-on-background pairing against accessibility contrast thresholds. Swap a color and watch the failing pairs flip to pass. A sharp single-screen utility designers actually want. The demo drags a swatch and shows the contrast badges update instantly.', 'Subes una imagen o pegas una captura y la herramienta extrae una paleta, luego califica en vivo cada combinación de texto sobre fondo según los umbrales de contraste de accesibilidad. Cambias un color y ves cómo los pares que fallan pasan a aprobar. Una utilidad de una sola pantalla que los diseñadores realmente quieren. La demo arrastra una muestra y muestra las insignias de contraste actualizándose al instante.', 'web-frontend', '1-3h', 1, 3, 'beginner', '["ui-tooling","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Keyboard-Only Heatmap that Audits a Page for Focus Traps', 'Mapa de calor de teclado que audita una página por trampas de foco', 'A tool that tab-walks a live page and draws the focus order as a numbered path, flagging skipped elements, focus traps, and invisible outlines. Replay the walk step by step to see where a keyboard user gets stuck. A demoable accessibility audit that turns an abstract problem into a visible map. The demo runs it on a messy real site.', 'Una herramienta que recorre una página en vivo con la tecla Tab y dibuja el orden de foco como un camino numerado, marcando elementos omitidos, trampas de foco y contornos invisibles. Reproduces el recorrido paso a paso para ver dónde se atasca un usuario de teclado. Una auditoría de accesibilidad demostrable que convierte un problema abstracto en un mapa visible. La demo lo ejecuta en un sitio real desordenado.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["accessibility","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Offline-First PWA that Caches a Whole Recipe Site for Trips', 'PWA offline que guarda un sitio de recetas entero para viajes', 'A PWA that lets you save any set of pages for full offline use, stripping them to readable text and images and syncing your highlights when you reconnect. Built for kitchens, trains, and dead zones where the network drops. The hook is reliable offline reading with a real sync story. The demo flips to airplane mode and the saved content still works.', 'Una PWA que te permite guardar cualquier conjunto de páginas para uso completo sin conexión, reduciéndolas a texto e imágenes legibles y sincronizando tus resaltados al reconectarte. Hecha para cocinas, trenes y zonas sin señal donde la red se cae. El gancho es una lectura offline confiable con una verdadera historia de sincronización. La demo activa el modo avión y el contenido guardado sigue funcionando.', 'web-frontend', '12-24h', 12, 24, 'intermediate', '["pwa","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('CSS Animation Playground that Exports Production Keyframes', 'Patio de animación CSS que exporta keyframes listos para producción', 'A visual editor where you drag an element along a timeline, tweak easing curves by feel, and the tool writes clean, copy-paste CSS keyframes behind you. Scrub the timeline to preview at any frame. A focused UI tool that removes the guesswork from hand-writing animations. The demo builds a bouncing card and pastes the exported CSS into a fresh page.', 'Un editor visual donde arrastras un elemento por una línea de tiempo, ajustas curvas de aceleración por intuición y la herramienta escribe keyframes CSS limpios y listos para copiar detrás de ti. Recorres la línea de tiempo para previsualizar en cualquier fotograma. Una herramienta de UI enfocada que elimina la adivinanza de escribir animaciones a mano. La demo crea una tarjeta que rebota y pega el CSS exportado en una página nueva.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["animation","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Real-Time Poll Overlay that Reacts to a Live Stream Chat', 'Superposición de encuestas en tiempo real que reacciona al chat de un stream', 'A browser overlay for streamers that spins up an instant poll, then animates a live bar chart as viewers vote through a shared link. Results pulse and reorder the moment votes land, with a winner reveal animation. A real-time dataviz piece with obvious stage appeal. The demo runs a poll and votes from a phone to watch the bars move.', 'Una superposición de navegador para streamers que crea una encuesta instantánea y luego anima un gráfico de barras en vivo mientras los espectadores votan a través de un enlace compartido. Los resultados laten y se reordenan en el momento en que llegan los votos, con una animación de revelación del ganador. Una pieza de visualización de datos en tiempo real con evidente atractivo escénico. La demo lanza una encuesta y vota desde un teléfono para ver moverse las barras.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["real-time","dataviz","animation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Extension that Rewrites Cookie Banners into One Honest Choice', 'Extensión que reescribe los banners de cookies en una sola decisión honesta', 'A browser extension that detects consent banners and replaces their dark patterns with a single plain Accept-or-Reject card, defaulting to the privacy-protecting choice. It logs which sites tried to trick you. The hook is reclaiming the page from manipulative UI. The demo hits a notoriously sneaky banner and shows the clean replacement pop in.', 'Una extensión de navegador que detecta banners de consentimiento y reemplaza sus patrones oscuros con una sola tarjeta clara de Aceptar o Rechazar, con la opción que protege la privacidad por defecto. Registra qué sitios intentaron engañarte. El gancho es recuperar la página de una UI manipuladora. La demo entra a un banner notoriamente tramposo y muestra el reemplazo limpio apareciendo.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["browser-extension","accessibility","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Drag-to-Build Dashboard that Wires Charts to a Pasted API', 'Dashboard de arrastrar que conecta gráficos a una API pegada', 'Paste a JSON API URL, drag chart blocks onto a grid, and map fields to axes with no code, getting a shareable live dashboard. Each tile auto-refreshes on an interval you set. A fuller flow that earns its time with a real no-code builder. The demo points at a public API and assembles a working dashboard from scratch.', 'Pegas la URL de una API JSON, arrastras bloques de gráficos a una cuadrícula y mapeas campos a ejes sin código, obteniendo un dashboard en vivo para compartir. Cada mosaico se actualiza solo en el intervalo que definas. Un flujo más completo que justifica su tiempo con un verdadero constructor no-code. La demo apunta a una API pública y arma un dashboard funcional desde cero.', 'web-frontend', '12-24h', 12, 24, 'intermediate', '["dataviz","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Webcam Hand-Gesture Controller for Slide Decks in the Browser', 'Control de diapositivas por gestos de mano con webcam en el navegador', 'A browser tool that watches your webcam and advances slides with a swipe of the hand, with a circular gesture to zoom and a fist to blank the screen. No clicker, no install, runs on the page. The hook is presenting hands-free from any laptop. The demo flips through a deck on stage with nothing but gestures.', 'Una herramienta de navegador que observa tu webcam y avanza diapositivas con un movimiento de la mano, con un gesto circular para hacer zoom y un puño para apagar la pantalla. Sin control remoto, sin instalación, corre en la página. El gancho es presentar sin manos desde cualquier laptop. La demo recorre una presentación en el escenario solo con gestos.', 'web-frontend', '12-24h', 12, 24, 'advanced', '["ui-tooling","real-time","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Generative SVG Pattern Studio with a Shareable Seed URL', 'Estudio de patrones SVG generativos con URL de semilla compartible', 'A studio that generates tiling SVG backgrounds from a few sliders, encoding every parameter into the URL so any pattern is a link you can send. Animate the pattern subtly and export it as a clean SVG or CSS background. A delightful, self-contained tool with instant gratification. The demo drags sliders and copies a link that reopens the exact pattern.', 'Un estudio que genera fondos SVG en mosaico a partir de unos pocos deslizadores, codificando cada parámetro en la URL para que cualquier patrón sea un enlace que puedes enviar. Anima el patrón sutilmente y lo exporta como un SVG limpio o un fondo CSS. Una herramienta encantadora y autónoma con gratificación instantánea. La demo arrastra deslizadores y copia un enlace que reabre el patrón exacto.', 'web-frontend', '3-6h', 3, 6, 'intermediate', '["animation","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Co-op Drawing Game where Two Phones Steer One Pen', 'Juego de dibujo cooperativo donde dos teléfonos guían un solo lápiz', 'A party game where two players share one drawing cursor over a link, each controlling a different axis, so a recognizable picture only emerges if they cooperate. A round timer and a guesser round add stakes. The whole comedy is the forced teamwork on screen. The demo has two judges try to draw a cat and fail hilariously.', 'Un juego de fiesta donde dos jugadores comparten un solo cursor de dibujo a través de un enlace, cada uno controlando un eje distinto, así que una imagen reconocible solo surge si cooperan. Un temporizador de ronda y una ronda de adivinanza suben la apuesta. Toda la comedia está en el trabajo en equipo forzado en pantalla. La demo hace que dos jueces intenten dibujar un gato y fallen de forma graciosa.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["game-ui","real-time"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Diff Viewer for Two Screenshots that Highlights UI Drift', 'Visor de diferencias entre dos capturas que resalta el drift de UI', 'Drop two screenshots of the same screen and the tool overlays them, highlighting moved, resized, or missing elements with a slider to wipe between before and after. Perfect for catching visual regressions without a test suite. A sharp single-purpose utility with an immediately readable result. The demo wipes between two versions and the changed button lights up.', 'Sueltas dos capturas de la misma pantalla y la herramienta las superpone, resaltando elementos movidos, redimensionados o faltantes con un deslizador para barrer entre el antes y el después. Perfecta para atrapar regresiones visuales sin una suite de pruebas. Una utilidad de propósito único y nítida con un resultado legible al instante. La demo barre entre dos versiones y el botón modificado se ilumina.', 'web-frontend', '3-6h', 3, 6, 'intermediate', '["ui-tooling","dataviz"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Live Typography Tester that Reflows Real Copy as You Tune', 'Probador tipográfico en vivo que reacomoda texto real mientras ajustas', 'A tool that loads a paragraph of real content and lets you tune font, size, line height, and measure while it reflows live, scoring readability against typographic best practices. Flag lines that are too long or too tight. A focused UI utility that makes good type decisions obvious. The demo nudges line height and the readability score climbs.', 'Una herramienta que carga un párrafo de contenido real y te deja ajustar fuente, tamaño, interlineado y ancho mientras se reacomoda en vivo, puntuando la legibilidad según las mejores prácticas tipográficas. Marca líneas demasiado largas o apretadas. Una utilidad de UI enfocada que hace obvias las buenas decisiones de tipografía. La demo ajusta el interlineado y el puntaje de legibilidad sube.', 'web-frontend', '1-3h', 1, 3, 'beginner', '["ui-tooling","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Extension that Shows the Carbon Cost of the Page You Loaded', 'Extensión que muestra el costo de carbono de la página que cargaste', 'A browser extension that estimates the data weight and rough carbon footprint of each page you visit, charting the heaviest assets and offering a one-click lightweight reader view. A small badge keeps a running daily total. The hook is making the invisible cost of bloated sites visible. The demo loads a heavy site and the badge jumps, then drops in reader mode.', 'Una extensión de navegador que estima el peso de datos y la huella de carbono aproximada de cada página que visitas, graficando los recursos más pesados y ofreciendo una vista de lectura ligera con un clic. Una pequeña insignia lleva un total diario acumulado. El gancho es hacer visible el costo invisible de los sitios sobrecargados. La demo carga un sitio pesado, la insignia salta y luego baja en modo lectura.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["browser-extension","dataviz"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Animated Org Chart that Grows Itself from a Pasted List', 'Organigrama animado que se construye solo desde una lista pegada', 'Paste an indented list of names and roles and the tool animates a clean org chart into existence, with nodes easing into place and lines drawing themselves. Click any node to collapse a branch with a smooth transition. A satisfying dataviz build that turns boring text into a living diagram. The demo pastes a team list and watches the tree assemble.', 'Pegas una lista indentada de nombres y roles y la herramienta anima un organigrama limpio que cobra vida, con nodos que se deslizan a su lugar y líneas que se dibujan solas. Haces clic en cualquier nodo para colapsar una rama con una transición suave. Una construcción de visualización satisfactoria que convierte texto aburrido en un diagrama vivo. La demo pega una lista de equipo y mira el árbol ensamblarse.', 'web-frontend', '3-6h', 3, 6, 'intermediate', '["dataviz","animation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Shared Whiteboard with a Time-Travel Slider for Every Stroke', 'Pizarra compartida con deslizador de viaje en el tiempo para cada trazo', 'A real-time collaborative whiteboard where every stroke is timestamped, so a slider lets the room scrub the drawing back and forth through its whole history. Replay a brainstorm from blank to full. The hook is collaboration plus a built-in rewind that no sticky-note app has. The demo has two people draw, then scrubs the board back to an earlier moment.', 'Una pizarra colaborativa en tiempo real donde cada trazo lleva marca de tiempo, así que un deslizador permite a la sala recorrer el dibujo adelante y atrás por toda su historia. Reproduces una lluvia de ideas desde el lienzo vacío hasta el lleno. El gancho es la colaboración más un rebobinado integrado que ninguna app de notas tiene. La demo hace que dos personas dibujen y luego retrocede la pizarra a un momento anterior.', 'web-frontend', '12-24h', 12, 24, 'advanced', '["real-time","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('One-Page Resume Builder that Live-Scores ATS Readability', 'Constructor de CV de una página que califica la legibilidad ATS en vivo', 'An editor where you fill a resume and a live panel scores how cleanly an applicant-tracking system would parse it, flagging risky columns, icons, and missing sections. Toggle a plain-text preview to see exactly what a bot reads. A focused tool with a tangible payoff. The demo edits a fancy resume and watches the parse score react.', 'Un editor donde completas un CV y un panel en vivo califica qué tan limpiamente lo interpretaría un sistema de seguimiento de candidatos, marcando columnas riesgosas, iconos y secciones faltantes. Activas una vista en texto plano para ver exactamente lo que lee un bot. Una herramienta enfocada con un beneficio tangible. La demo edita un CV recargado y observa cómo reacciona el puntaje de interpretación.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["ui-tooling","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Browser Game where You Code-Golf CSS to Match a Target', 'Juego de navegador donde haces code-golf de CSS para igualar un objetivo', 'A puzzle game that shows a target shape and challenges you to recreate it in as few CSS characters as possible, scoring you on brevity and accuracy each round. A live preview updates as you type and a leaderboard ranks the shortest solutions. The hook is making CSS a competitive puzzle. The demo solves a level and shrinks the solution for a higher score.', 'Un juego de rompecabezas que muestra una forma objetivo y te reta a recrearla con la menor cantidad posible de caracteres CSS, puntuándote por brevedad y precisión en cada ronda. Una vista previa en vivo se actualiza mientras escribes y una tabla de líderes ordena las soluciones más cortas. El gancho es convertir el CSS en un rompecabezas competitivo. La demo resuelve un nivel y acorta la solución para un mejor puntaje.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["game-ui","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Extension that Turns Any Table on the Web into a Live Chart', 'Extensión que convierte cualquier tabla web en un gráfico en vivo', 'A browser extension that detects HTML tables on any page and offers a one-click chart, letting you pick columns and chart type in a popup without copying data anywhere. Sort and filter feed straight into the visual. The hook is instant dataviz on data you are already looking at. The demo lands on a stats page and charts a table in two clicks.', 'Una extensión de navegador que detecta tablas HTML en cualquier página y ofrece un gráfico con un clic, dejándote elegir columnas y tipo de gráfico en un popup sin copiar datos a ningún lado. Ordenar y filtrar alimenta directamente el visual. El gancho es visualización instantánea sobre datos que ya estás mirando. La demo aterriza en una página de estadísticas y grafica una tabla en dos clics.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["browser-extension","dataviz"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Skeleton-Loader Generator that Matches Your Real Layout', 'Generador de skeleton-loaders que coincide con tu layout real', 'Paste a snippet of markup and the tool generates a matching shimmering skeleton-loader component, mirroring the box shapes of your actual layout. Tweak the shimmer speed and corner radius, then copy the code. A tight utility that kills a tedious frontend chore. The demo pastes a card layout and exports a pixel-aligned loading state.', 'Pegas un fragmento de marcado y la herramienta genera un componente skeleton-loader con brillo a juego, reflejando las formas de cajas de tu layout real. Ajustas la velocidad del brillo y el radio de las esquinas, luego copias el código. Una utilidad ajustada que elimina una tarea tediosa del frontend. La demo pega un layout de tarjeta y exporta un estado de carga alineado al pixel.', 'web-frontend', '1-3h', 1, 3, 'beginner', '["ui-tooling","animation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Voice-Driven Form Filler that Reads Fields Back for Confirmation', 'Llenador de formularios por voz que lee los campos para confirmar', 'A web layer that lets a user complete any form entirely by voice, jumping field to field, dictating answers, and reading each one back before submit. Built for low-vision users and anyone whose hands are busy. The hook is making forms truly hands-free with a confirmation loop. The demo fills a multi-field form by talking, with the fields highlighting as they fill.', 'Una capa web que permite a un usuario completar cualquier formulario enteramente por voz, saltando de campo en campo, dictando respuestas y leyendo cada una antes de enviar. Hecha para usuarios con baja visión y para cualquiera con las manos ocupadas. El gancho es hacer los formularios verdaderamente manos libres con un ciclo de confirmación. La demo llena un formulario de varios campos hablando, con los campos resaltándose al completarse.', 'web-frontend', '12-24h', 12, 24, 'advanced', '["accessibility","real-time","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Animated Subway-Map Generator from a List of Stops', 'Generador de mapas de metro animados a partir de una lista de paradas', 'Type lines and stops in plain text and the tool draws a clean, animated transit-style map with the signature 45-degree angles and smooth route bends. Hover a station to trace connecting lines. A delightful dataviz piece that turns any sequence into a beautiful diagram. The demo types a few lines and the map snaps into a polished transit graphic.', 'Escribes líneas y paradas en texto plano y la herramienta dibuja un mapa estilo transporte limpio y animado, con los característicos ángulos de 45 grados y curvas de ruta suaves. Pasas el cursor sobre una estación para trazar las líneas que conectan. Una pieza de visualización encantadora que convierte cualquier secuencia en un diagrama hermoso. La demo escribe unas pocas líneas y el mapa encaja en un gráfico de transporte pulido.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["dataviz","animation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('PWA Habit Tracker that Buzzes Without Any Server', 'PWA de hábitos que avisa sin ningún servidor', 'A fully offline PWA that tracks daily habits and fires local reminder notifications straight from the device, with an animated streak ring that fills as you check in. Everything stays on the phone, installable from the browser. The hook is real push-style nudges with zero backend. The demo installs it, checks a habit, and a local notification fires.', 'Una PWA totalmente offline que registra hábitos diarios y dispara notificaciones de recordatorio locales directamente desde el dispositivo, con un anillo de racha animado que se llena al registrarte. Todo se queda en el teléfono, instalable desde el navegador. El gancho son avisos tipo push reales sin ningún backend. La demo la instala, marca un hábito y dispara una notificación local.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["pwa","animation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Spectator View that Renders a Chess Game as Living Heat', 'Vista de espectador que muestra una partida de ajedrez como calor vivo', 'A real-time board that visualizes a live chess game not as pieces but as a heatmap of square control, pulsing as the balance of power shifts each move. Toggle to see threatened squares glow. The hook is a fresh, beautiful way to feel the tension of a game. The demo streams a game and the board breathes as control swings.', 'Un tablero en tiempo real que visualiza una partida de ajedrez en vivo no como piezas sino como un mapa de calor del control de casillas, latiendo a medida que el equilibrio de poder cambia con cada jugada. Activas una vista para ver brillar las casillas amenazadas. El gancho es una forma fresca y hermosa de sentir la tensión de una partida. La demo transmite una partida y el tablero respira mientras el control oscila.', 'web-frontend', '12-24h', 12, 24, 'advanced', '["dataviz","real-time","game-ui"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Extension that Adds Reading Rulers and Tints for Dyslexia', 'Extensión que agrega reglas de lectura y tintes para dislexia', 'A browser extension that overlays a focus ruler tracking your cursor line, dims the rest of the page, and applies dyslexia-friendly tints and spacing on any site. Save per-site presets so favorite pages remember your settings. A small, genuinely helpful accessibility hack. The demo turns a wall of text into a calm, line-by-line reading experience.', 'Una extensión de navegador que superpone una regla de enfoque que sigue la línea de tu cursor, atenúa el resto de la página y aplica tintes y espaciado amigables con la dislexia en cualquier sitio. Guarda preajustes por sitio para que tus páginas favoritas recuerden tu configuración. Un hack de accesibilidad pequeño y genuinamente útil. La demo convierte un muro de texto en una lectura tranquila, línea por línea.', 'web-frontend', '3-6h', 3, 6, 'intermediate', '["browser-extension","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Component Theming Sandbox that Diffs Two Design Tokens Sets', 'Sandbox de theming que compara dos conjuntos de design tokens', 'A sandbox that renders the same component gallery under two token sets side by side, instantly showing how a theme change ripples across buttons, cards, and forms. Flag any pairing that breaks contrast or spacing rules. A fuller tool that earns its time for design systems work. The demo swaps a brand token and the whole gallery recolors at once.', 'Un sandbox que renderiza la misma galería de componentes bajo dos conjuntos de tokens lado a lado, mostrando al instante cómo un cambio de tema repercute en botones, tarjetas y formularios. Marca cualquier combinación que rompa reglas de contraste o espaciado. Una herramienta más completa que justifica su tiempo para trabajo de design systems. La demo cambia un token de marca y toda la galería se recolorea de una vez.', 'web-frontend', '12-24h', 12, 24, 'intermediate', '["ui-tooling","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Particle Music Visualizer that Reacts to the Mic in Real Time', 'Visualizador musical de partículas que reacciona al micrófono en tiempo real', 'A full-screen visualizer that listens to the microphone and drives a particle field by beat and frequency, bursting on the bass and shimmering on the highs. Pick a palette and a motion style, then go full screen for an instant party display. The hook is turning any room''s sound into live visual art. The demo plays a track and the screen erupts in sync.', 'Un visualizador a pantalla completa que escucha el micrófono y controla un campo de partículas según el ritmo y la frecuencia, estallando con los graves y brillando con los agudos. Eliges una paleta y un estilo de movimiento, luego pasas a pantalla completa para una fiesta instantánea. El gancho es convertir el sonido de cualquier sala en arte visual en vivo. La demo reproduce una canción y la pantalla estalla en sincronía.', 'web-frontend', '3-6h', 3, 6, 'intermediate', '["animation","real-time"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Async Standup Board that Replays the Day as a Timeline', 'Tablero de standup async que reproduce el día como una línea de tiempo', 'A team board where everyone drops short async updates and the tool stitches them into a scrubbable timeline of the day, animating who touched what and when. Filter by person or project to replay just one thread. A real-time collaboration piece with a memorable playback twist. The demo posts a few updates and scrubs the day from morning to evening.', 'Un tablero de equipo donde todos dejan actualizaciones asincrónicas cortas y la herramienta las une en una línea de tiempo recorrible del día, animando quién tocó qué y cuándo. Filtras por persona o proyecto para reproducir solo un hilo. Una pieza de colaboración en tiempo real con un giro de reproducción memorable. La demo publica unas actualizaciones y recorre el día de la mañana a la noche.', 'web-frontend', '12-24h', 12, 24, 'intermediate', '["real-time","dataviz","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Gradient Mesh Picker that Animates Between Saved Moods', 'Selector de malla de gradiente que anima entre estados guardados', 'A tool for building rich mesh gradients by dragging color points on a canvas, saving several as named moods and morphing smoothly between them. Export the result as CSS or an animated background. A tight, beautiful utility with instant visual payoff. The demo drags a few points, saves two moods, and plays the transition between them.', 'Una herramienta para crear mallas de gradiente ricas arrastrando puntos de color en un lienzo, guardando varias como estados con nombre y transformándose suavemente entre ellas. Exporta el resultado como CSS o un fondo animado. Una utilidad ajustada y hermosa con recompensa visual instantánea. La demo arrastra unos puntos, guarda dos estados y reproduce la transición entre ellos.', 'web-frontend', '1-3h', 1, 3, 'beginner', '["animation","ui-tooling"]');
